/** Side panel with the fight details and the party tab. Swing thread only. */
class GoldenDpsPanel extends PluginPanel
{
	/** Ids of the two fight list choices that are not a saved fight. */
	static final String LIVE_CHOICE = "live";
	static final String SESSION_CHOICE = "session";

	static class Choice
	{
		final String id;
		final String label;

		Choice(String id, String label)
		{
			this.id = id;
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Everything the panel shows, built on the client thread. */
	static class Data
	{
		List<Choice> choices = new ArrayList<>();
		FightReport report;
		boolean running;
		boolean paused;
		boolean bossOnly;
		String endReason;
		int fights;
		long startMs;
		GoldenDpsPartyPanel.View party = new GoldenDpsPartyPanel.View();
		/** Boss damage over the boss time; null without a boss or in boss-only mode. */
		FightReport bossReport;
		/** {label, value} lines comparing a boss kill with the personal bests. */
		List<String[]> killLines = new ArrayList<>();
		/** In a raid: {boss, time, "PB 1:50" / "NEW PB!" / ""} for every boss so far. */
		List<String[]> bossTimes = new ArrayList<>();
		/** {label, value} lines of the monsters whose defence special attacks lowered. */
		List<String[]> defence = new ArrayList<>();
		/** Every monster, raid and Barrows run with its personal bests and stats, last kill first. */
		List<MonsterStats.Entry> monsters = new ArrayList<>();
		List<KillRates.Rate> killRates = new ArrayList<>();
		/** The live Barrows run time, or null without a run. */
		String barrowsRunTime;
		boolean barrowsRunPaused;
	}

	/** Sections you can show and hide; the name is saved, the flag is the default. */
	private enum Part
	{
		PER_HOUR(true),
		CHESTS(true),
		RAIDS(true),
		BOSSES(true),
		MONSTERS(false),
		FIGHT(true),
		BOSS_TIMES(true),
		DEFENCE(true),
		PLAYERS(true),
		TARGETS(false),
		MONSTER_STATS(false);

		final boolean openByDefault;

		Part(boolean openByDefault)
		{
			this.openByDefault = openByDefault;
		}
	}

	private static final String TAB_METER = "Meter";
	private static final String TAB_PARTY = "Party";
	private static final String NO_FIGHTS = "No fights yet. Hit something!";

	private final GoldenDpsPlugin plugin;
	private final JComboBox<Choice> fightBox = new JComboBox<>();
	private final GoldenDpsPartyPanel partyPanel;
	private final CardLayout cardLayout = new CardLayout();
	private final JPanel cards = new JPanel(cardLayout);
	private final JButton meterTab = tabButton(TAB_METER);
	private final JButton partyTab = tabButton(TAB_PARTY);
	private final JCheckBox bossOnlyBox = new JCheckBox("Boss only");
	private final JPanel content = new JPanel();
	private volatile String selectedId = LIVE_CHOICE;
	private volatile boolean active;
	private boolean updating;
	/** Sections whose show/hide differs from the default. */
	private final Set<Part> toggled = EnumSet.noneOf(Part.class);
	/** Weapons in the breakdown that show their accuracy (this session only). */
	private final Set<String> openSources = new HashSet<>();
	/** Monsters in the monster stats that show their card (this session only). */
	private final Set<String> openMonsters = new HashSet<>();

	GoldenDpsPanel(GoldenDpsPlugin plugin)
	{
		this.plugin = plugin;
		this.partyPanel = new GoldenDpsPartyPanel(plugin);
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout(0, 8));

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);

		fightBox.setFocusable(false);
		fightBox.addActionListener(e ->
		{
			if (updating)
			{
				return;
			}
			Choice c = (Choice) fightBox.getSelectedItem();
			selectedId = c == null ? LIVE_CHOICE : c.id;
			plugin.requestPanelUpdate();
		});
		top.add(fightBox);

		bossOnlyBox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bossOnlyBox.setFocusable(false);
		bossOnlyBox.addActionListener(e ->
		{
			if (!updating)
			{
				plugin.setBossOnly(bossOnlyBox.isSelected());
			}
		});
		top.add(bossOnlyBox);
		top.add(fightButtons());
		top.add(reportButtons());

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel meterCard = new JPanel(new BorderLayout(0, 8));
		meterCard.setOpaque(false);
		meterCard.add(top, BorderLayout.NORTH);
		meterCard.add(content, BorderLayout.CENTER);
		JPanel partyCard = new JPanel(new BorderLayout());
		partyCard.setOpaque(false);
		partyCard.add(partyPanel, BorderLayout.NORTH);
		cards.setOpaque(false);
		cards.add(meterCard, TAB_METER);
		cards.add(partyCard, TAB_PARTY);

		add(tabBar(), BorderLayout.NORTH);
		add(cards, BorderLayout.CENTER);
		showTab(TAB_METER);

		loadToggles(plugin.panelToggles());
		content.add(note(NO_FIGHTS));
	}

	private JComponent fightButtons()
	{
		JPanel buttons = new JPanel(new GridLayout(1, 3, 4, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(button("End fight", "End the running fight now", plugin::endFight));
		buttons.add(button("New session", "Start a new session total", plugin::resetSession));
		buttons.add(button("Clear", "Delete all saved fights", this::confirmClearHistory));
		return buttons;
	}

	private void confirmResetMonster(String name)
	{
		if (askYes("Delete the personal bests and stats of " + name + "?"))
		{
			plugin.resetMonster(name);
		}
	}

	private void confirmClearHistory()
	{
		if (askYes("Delete all saved fights for this account?"))
		{
			plugin.clearHistory();
		}
	}

	/** "Report to party" with a button per report kind. */
	private JComponent reportButtons()
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.add(small("Report:", ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.WEST);
		JPanel buttons = new JPanel(new GridLayout(1, ReportKind.values().length, 4, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (ReportKind kind : ReportKind.values())
		{
			String text = kind.label.replace(" damage", "");
			buttons.add(button(text, "Send the top 5 (" + kind.label.toLowerCase() + ") of the shown fight to your party chat",
				() -> plugin.reportPanelToParty(kind)));
		}
		row.add(buttons, BorderLayout.CENTER);
		return row;
	}

	@Override
	public void onActivate()
	{
		active = true;
		plugin.requestPanelUpdate();
	}

	@Override
	public void onDeactivate()
	{
		active = false;
	}

	/** Safe to call from any thread. */
	boolean isPanelOpen()
	{
		return active;
	}

	String getSelectedId()
	{
		return selectedId;
	}

	static String label(Fight f, long now)
	{
		String time = new SimpleDateFormat("HH:mm").format(new Date(f.startMs));
		// bosses inside a raid are listed under the raid
		return time + "  " + (f.partOf != null ? "> " : "") + f.title() + "  " + Format.preciseDuration(f.durationMs(now));
	}

	private JComponent tabBar()
	{
		JLabel title = bold("GoldenDPS", GOLD);
		meterTab.addActionListener(e -> showTab(TAB_METER));
		partyTab.addActionListener(e -> showTab(TAB_PARTY));
		JPanel tabs = new JPanel(new GridLayout(1, 2, 0, 0));
		tabs.setOpaque(false);
		tabs.add(meterTab);
		tabs.add(partyTab);
		JPanel bar = new JPanel(new BorderLayout(0, 6));
		bar.setOpaque(false);
		bar.add(title, BorderLayout.NORTH);
		bar.add(tabs, BorderLayout.CENTER);
		return bar;
	}

	private static JButton tabButton(String text)
	{
		JButton b = new JButton(text);
		b.setFocusable(false);
		b.setContentAreaFilled(false);
		b.setFont(FontManager.getRunescapeBoldFont());
		return b;
	}

	private void showTab(String tab)
	{
		cardLayout.show(cards, tab);
		styleTab(meterTab, TAB_METER.equals(tab));
		styleTab(partyTab, TAB_PARTY.equals(tab));
		if (TAB_PARTY.equals(tab))
		{
			plugin.requestPanelUpdate();
		}
	}

	private static void styleTab(JButton b, boolean selected)
	{
		b.setForeground(selected ? GOLD : ColorScheme.LIGHT_GRAY_COLOR);
		b.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 2, 0, selected ? GOLD : ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 0, 4, 0)));
	}

	void setPartyName(String name)
	{
		partyPanel.setPartyName(name);
	}

	void update(Data d)
	{
		updating = true;
		try
		{
			updateChoices(d.choices);
			bossOnlyBox.setSelected(d.bossOnly);
			partyPanel.update(d.party);
		}
		finally
		{
			updating = false;
		}

		content.removeAll();
		if (d.barrowsRunTime != null)
		{
			JPanel run = section();
			run.add(line("Barrows run", (d.barrowsRunPaused ? "paused " : "") + d.barrowsRunTime,
				d.barrowsRunPaused ? Color.YELLOW : GOLD));
			content.add(run);
		}
		addPerHour(d.killRates);
		addFight(d);
		addMonsterStats(d.monsters);
		content.revalidate();
		content.repaint();
	}

	/** Kills per hour first, so chests and raids are always at the top. */
	private void addPerHour(List<KillRates.Rate> rates)
	{
		if (rates.isEmpty() || !addHeading("Per hour (this session)", Part.PER_HOUR, 0))
		{
			return;
		}
		addRates("Chests", rates, KillRates.Kind.RUN, Part.CHESTS);
		addRates("Raids", rates, KillRates.Kind.RAID, Part.RAIDS);
		addRates("Bosses", rates, KillRates.Kind.BOSS, Part.BOSSES);
		addRates("Monsters", rates, KillRates.Kind.MONSTER, Part.MONSTERS);
	}

	private void addFight(Data d)
	{
		FightReport r = d.report;
		if (r == null)
		{
			addHeading("Fight", null, 0);
			content.add(Box.createVerticalStrut(4));
			content.add(note(SESSION_CHOICE.equals(selectedId) ? "No fights in this session yet." : NO_FIGHTS));
			return;
		}
		if (addHeading("Fight", Part.FIGHT, 0))
		{
			content.add(Box.createVerticalStrut(4));
			content.add(FightCards.summary(d));
		}
		if (!d.bossTimes.isEmpty() && addHeading("Boss times", Part.BOSS_TIMES, d.bossTimes.size()))
		{
			content.add(Box.createVerticalStrut(4));
			content.add(FightCards.bossTimes(d.bossTimes));
		}
		if (!d.defence.isEmpty() && addHeading("Defence", Part.DEFENCE, 0))
		{
			content.add(Box.createVerticalStrut(4));
			content.add(FightCards.lines(d.defence));
		}

		List<FightReport.PlayerRow> rows = new ArrayList<>(r.getRows());
		rows.sort((a, b) -> Long.compare(b.damage, a.damage));
		boolean solo = r.isSolo();
		if (!rows.isEmpty() && addHeading(solo ? "Details" : "Players", Part.PLAYERS, solo ? 0 : rows.size()))
		{
			for (FightReport.PlayerRow row : rows)
			{
				content.add(Box.createVerticalStrut(4));
				content.add(FightCards.player(row, d.bossReport == null ? null : d.bossReport.row(row.name), solo,
					openSources, this::toggleSource));
			}
		}

		if (!r.getTargets().isEmpty() && addHeading("Damage per target", Part.TARGETS, r.getTargets().size()))
		{
			for (FightReport.TargetRow t : r.getTargets())
			{
				content.add(Box.createVerticalStrut(4));
				content.add(FightCards.target(t));
			}
		}
	}

	/** Every monster you killed; a click opens its personal bests and stats. */
	private void addMonsterStats(List<MonsterStats.Entry> entries)
	{
		if (entries.isEmpty())
		{
			return;
		}
		boolean open = addHeading("Monster stats", Part.MONSTER_STATS, entries.size());
		resetAllOnRightClick((JComponent) content.getComponent(content.getComponentCount() - 1));
		if (!open)
		{
			return;
		}
		content.add(Box.createVerticalStrut(4));
		JPanel list = section();
		for (MonsterStats.Entry e : entries)
		{
			JComponent row = line((openMonsters.contains(e.name) ? "- " : "+ ") + e.name, FightCards.monsterSummary(e));
			row.setToolTipText("Click for the personal bests and stats of " + e.name);
			PanelWidgets.clickable(row, () -> toggleMonster(e.name));
			list.add(row);
			if (openMonsters.contains(e.name))
			{
				FightCards.addMonster(list, e, openSources, this::toggleSource,
					() -> confirmResetMonster(e.name));
			}
		}
		resetAllOnRightClick(list);
		content.add(list);
	}

	private void resetAllOnRightClick(JComponent c)
	{
		PanelWidgets.rightClickMenu(c, "Reset all monster stats", this::confirmResetAllMonsters);
	}

	/** Asked twice: it deletes every personal best, and that cannot be undone. */
	private void confirmResetAllMonsters()
	{
		if (askYes("Delete the personal bests and stats of every monster, raid and Barrows run?")
			&& askYes("Are you sure? This cannot be undone."))
		{
			plugin.resetAllMonsters();
		}
	}

	private boolean askYes(String question)
	{
		return JOptionPane.showConfirmDialog(this, question, "GoldenDPS", JOptionPane.YES_NO_OPTION)
			== JOptionPane.YES_OPTION;
	}

	private void toggleMonster(String name)
	{
		if (!openMonsters.remove(name))
		{
			openMonsters.add(name);
		}
		plugin.requestPanelUpdate();
	}

	private boolean isOpen(Part part)
	{
		return part.openByDefault != toggled.contains(part);
	}

	private void toggleSource(String key)
	{
		if (!openSources.remove(key))
		{
			openSources.add(key);
		}
		plugin.requestPanelUpdate();
	}

	private void toggle(Part part)
	{
		if (!toggled.remove(part))
		{
			toggled.add(part);
		}
		StringBuilder saved = new StringBuilder();
		for (Part p : toggled)
		{
			saved.append(saved.length() > 0 ? "," : "").append(p.name());
		}
		plugin.savePanelToggles(saved.toString());
		plugin.requestPanelUpdate();
	}

	/** @param saved part names, comma separated; unknown names are skipped */
	private void loadToggles(String saved)
	{
		for (String name : saved.split(","))
		{
			for (Part part : Part.values())
			{
				if (part.name().equals(name))
				{
					toggled.add(part);
				}
			}
		}
	}

	/** A click on the row shows or hides the part; "show" or "hide" on the right says which. */
	private JComponent toggleRow(JLabel title, Part part, int count)
	{
		if (count > 0)
		{
			title.setText(title.getText() + " (" + count + ")");
		}
		if (part == null)
		{
			return actionRow(title, null, null, null);
		}
		boolean open = isOpen(part);
		return actionRow(title, open ? "hide" : "show", open ? "Click to hide" : "Click to show", () -> toggle(part));
	}

	/** One card per kind: "Vorkath    12 kc  18.5/hr". */
	private void addRates(String title, List<KillRates.Rate> rates, KillRates.Kind kind, Part part)
	{
		int count = (int) rates.stream().filter(r -> r.kind == kind).count();
		if (count == 0)
		{
			return;
		}
		JPanel card = section();
		card.add(toggleRow(bold(title, Color.WHITE), part, count));
		for (KillRates.Rate rate : rates)
		{
			if (rate.kind == kind && isOpen(part))
			{
				card.add(rateLine(rate));
			}
		}
		content.add(Box.createVerticalStrut(4));
		content.add(card);
	}

	private static JComponent rateLine(KillRates.Rate rate)
	{
		String perHour = String.format("%.1f/hr", rate.perHour);
		JComponent line = line(rate.name, rate.kills + " kc  " + perHour);
		String counted = rate.kind == KillRates.Kind.RAID ? " completions" : rate.kind == KillRates.Kind.RUN ? " chests" : " kills";
		line.setToolTipText(rate.name + ": " + rate.kills + counted + ", average " + Format.duration(rate.averageMs));
		return line;
	}

	/** Adds a gold heading; returns true when its part is shown. */
	private boolean addHeading(String text, Part part, int count)
	{
		content.add(Box.createVerticalStrut(content.getComponentCount() == 0 ? 0 : 10));
		content.add(toggleRow(bold(text, GOLD), part, count));
		return part == null || isOpen(part);
	}

	private void updateChoices(List<Choice> choices)
	{
		if (fightBox.isPopupVisible())
		{
			// a new list would close the open list under your mouse
			return;
		}
		DefaultComboBoxModel<Choice> model = new DefaultComboBoxModel<>();
		Choice select = null;
		for (Choice c : choices)
		{
			model.addElement(c);
			if (c.id.equals(selectedId))
			{
				select = c;
			}
		}
		if (select == null && !choices.isEmpty())
		{
			// the selected fight is gone: fall back to the live view
			select = choices.get(0);
			selectedId = select.id;
		}
		fightBox.setModel(model);
		if (select != null)
		{
			fightBox.setSelectedItem(select);
		}
	}
}

package com.goldendps;

import com.google.gson.annotations.SerializedName;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Party control, since RuneLite parties have no leader or kick:
 * <ul>
 * <li>{@code hi}: a member runs GoldenDPS and names the leader it knows (0 if none)</li>
 * <li>{@code leader}: the leader announces itself</li>
 * <li>{@code kick}: the leader asks the {@link #target} member to leave</li>
 * <li>{@code bye}: the member leaves now (the party server keeps listing it for minutes)</li>
 * </ul>
 * The party server identifies messages by class name, which must therefore never change.
 */
public class GoldenDpsPartyMessage extends PartyMemberMessage
{
	static final String HI = "hi";
	static final String LEADER = "leader";
	static final String KICK = "kick";
	static final String BYE = "bye";

	@SerializedName("v")
	public int version = 1;
	public String type;
	public long leader;
	public long target;

	public GoldenDpsPartyMessage()
	{
	}

	GoldenDpsPartyMessage(String type, long leader, long target)
	{
		this.type = type;
		this.leader = leader;
		this.target = target;
	}
}

package com.goldendps;

import static com.goldendps.PanelWidgets.GOLD;
import static com.goldendps.PanelWidgets.bold;
import static com.goldendps.PanelWidgets.small;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** The party tab of the side panel. Swing thread only. */
class GoldenDpsPartyPanel extends JPanel
{
	static class Member
	{
		long id;
		String name;
		boolean online;
		boolean you;
		boolean leader;
		boolean hasPlugin;
	}

	/** Everything the tab shows, built on the client thread. */
	static class View
	{
		boolean inParty;
		String code;
		boolean youLead;
		/** "Raid party" or "Own party" when GoldenDPS joined it, else null. */
		String autoLabel;
		/** The last party you were in, for Rejoin, or null. */
		String lastParty;
		List<Member> members = new ArrayList<>();
	}

	private static final Color ONLINE = new Color(90, 200, 90);
	private static final Color OFFLINE = new Color(110, 110, 110);
	private static final Color KICK = new Color(170, 50, 50);
	/** Kick needs a second click within this time. */
	private static final int KICK_CONFIRM_MS = 4000;
	private static final String JOIN_TIP = "Join (or start) the party with this name";
	private static final String RANDOM_TIP = "Fill in a random party name";
	private static final String LEAVE_FIRST = "Leave this party first";

	private final GoldenDpsPlugin plugin;
	private final JLabel status = new JLabel();
	private final JTextField nameField = new JTextField();
	private final JPanel memberList = new JPanel();
	private final JButton joinButton;
	private final JButton randomButton;
	private final JButton copyButton;
	private final JButton leaveButton;
	private final JButton rejoinButton;
	private View lastView = new View();
	private String shownCode;
	private long confirmKickId = -1;
	private long confirmUntil;

	GoldenDpsPartyPanel(GoldenDpsPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, GOLD),
			BorderFactory.createEmptyBorder(6, 8, 8, 8)));

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JLabel title = bold("Party", GOLD);
		status.setFont(FontManager.getRunescapeSmallFont());
		header.add(title, BorderLayout.WEST);
		header.add(status, BorderLayout.EAST);

		JLabel nameLabel = small("Party name", ColorScheme.LIGHT_GRAY_COLOR);
		nameLabel.setToolTipText("Everyone who joins with the same name is in the same party");
		nameField.setToolTipText("Type a party name (spaces are fine), or press Random");
		nameField.addActionListener(e -> join());
		joinButton = button("Join", JOIN_TIP, ColorScheme.BRAND_ORANGE, this::join);
		JPanel nameRow = new JPanel(new BorderLayout(4, 0));
		nameRow.setOpaque(false);
		nameRow.add(nameField, BorderLayout.CENTER);
		nameRow.add(joinButton, BorderLayout.EAST);

		JPanel actions = new JPanel(new GridLayout(1, 3, 4, 0));
		actions.setOpaque(false);
		randomButton = button("Random", RANDOM_TIP, null, plugin::randomPartyName);
		actions.add(randomButton);
		copyButton = button("Copy", "Copy the party name to send to your friends", null, this::copy);
		actions.add(copyButton);
		leaveButton = button("Leave", "Leave the party", null, plugin::leaveParty);
		actions.add(leaveButton);
		rejoinButton = button("Rejoin", null, null, plugin::rejoinParty);

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.setOpaque(false);
		top.add(header);
		top.add(nameLabel);
		top.add(nameRow);
		top.add(actions);
		top.add(rejoinButton);

		memberList.setLayout(new BoxLayout(memberList, BoxLayout.Y_AXIS));
		memberList.setOpaque(false);

		add(top, BorderLayout.NORTH);
		add(memberList, BorderLayout.CENTER);
		update(new View());
	}

	void setPartyName(String name)
	{
		nameField.setText(name);
		nameField.requestFocusInWindow();
	}

	void update(View v)
	{
		lastView = v;
		if (v.inParty)
		{
			int online = 0;
			for (Member m : v.members)
			{
				online += m.online ? 1 : 0;
			}
			status.setText(online + " online");
			status.setForeground(ONLINE);
			if (v.code != null && !v.code.equals(nameField.getText()))
			{
				nameField.setText(v.code);
			}
		}
		else
		{
			status.setText("not in a party");
			status.setForeground(OFFLINE);
		}
		shownCode = v.inParty ? v.code : null;
		leaveButton.setEnabled(v.inParty);
		copyButton.setEnabled(v.inParty);
		rejoinButton.setEnabled(!v.inParty && v.lastParty != null);
		rejoinButton.setToolTipText(v.inParty ? LEAVE_FIRST : v.lastParty != null
			? "Join your last party \"" + v.lastParty + "\" again" : "No last party yet");
		// switching party needs an explicit Leave first
		nameField.setEditable(!v.inParty);
		randomButton.setEnabled(!v.inParty);
		joinButton.setEnabled(!v.inParty);
		joinButton.setBackground(v.inParty ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.BRAND_ORANGE);
		randomButton.setToolTipText(v.inParty ? LEAVE_FIRST : RANDOM_TIP);
		joinButton.setToolTipText(v.inParty ? LEAVE_FIRST : JOIN_TIP);
		nameField.setToolTipText(v.inParty ? "Your party name. " + LEAVE_FIRST + " to pick another one."
			: "Type a party name (spaces are fine), or press Random");

		memberList.removeAll();
		if (v.inParty)
		{
			if (v.autoLabel != null)
			{
				memberList.add(small(v.autoLabel, GOLD));
			}
			memberList.add(small(v.youLead ? "Members - you lead" : "Members", ColorScheme.LIGHT_GRAY_COLOR));
			for (Member m : v.members)
			{
				memberList.add(memberRow(m, v.youLead));
			}
		}
		memberList.revalidate();
		memberList.repaint();
	}

	private JComponent memberRow(Member m, boolean youLead)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 4));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		row.setAlignmentX(LEFT_ALIGNMENT);

		row.add(new Dot(m.online ? ONLINE : OFFLINE), BorderLayout.WEST);

		JPanel names = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		names.setOpaque(false);
		JLabel name = new JLabel((m.leader ? "★ " : "") + m.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(m.leader ? GOLD : m.online ? Color.WHITE : OFFLINE);
		name.setToolTipText(m.leader ? "Party leader" : null);
		names.add(name);
		if (m.you)
		{
			names.add(small("(you)", ColorScheme.LIGHT_GRAY_COLOR));
		}
		else if (!m.hasPlugin)
		{
			JLabel noPlugin = small("no GoldenDPS", OFFLINE);
			noPlugin.setToolTipText("Uses only the Party plugin: their damage is a guess, and they can't be kicked");
			names.add(noPlugin);
		}
		row.add(names, BorderLayout.CENTER);

		if (youLead && !m.you)
		{
			boolean sure = confirmKickId == m.id && System.currentTimeMillis() < confirmUntil;
			JButton kick = button(sure ? "Sure?" : "Kick", !m.hasPlugin ? "Can't kick: " + m.name + " does not run GoldenDPS"
				: sure ? "Click again to remove " + m.name : "Remove " + m.name + " from the party (click twice)",
				KICK, () -> kickClicked(m));
			kick.setEnabled(m.hasPlugin);
			row.add(kick, BorderLayout.EAST);
		}

		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setOpaque(false);
		wrap.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		wrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 27));
		wrap.setAlignmentX(LEFT_ALIGNMENT);
		wrap.add(row);
		return wrap;
	}

	private void kickClicked(Member m)
	{
		long now = System.currentTimeMillis();
		if (confirmKickId == m.id && now < confirmUntil)
		{
			confirmKickId = -1;
			plugin.kickFromParty(m.id, m.name);
			return;
		}
		confirmKickId = m.id;
		confirmUntil = now + KICK_CONFIRM_MS;
		update(lastView);
		Timer reset = new Timer(KICK_CONFIRM_MS + 50, e -> update(lastView));
		reset.setRepeats(false);
		reset.start();
	}

	private void join()
	{
		if (!joinButton.isEnabled())
		{
			return;
		}
		String name = nameField.getText() == null ? "" : nameField.getText().trim().replaceAll("\\s+", " ");
		if (!name.isEmpty())
		{
			plugin.joinParty(name);
		}
	}

	private void copy()
	{
		if (shownCode != null)
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(shownCode), null);
		}
	}

	/** @param background null for the default look */
	private static JButton button(String text, String tip, Color background, Runnable action)
	{
		JButton b = PanelWidgets.button(text, tip, action);
		if (background != null)
		{
			b.setBackground(background);
			b.setForeground(Color.WHITE);
		}
		return b;
	}

	/** Online / offline dot. */
	private static class Dot extends JComponent
	{
		private final Color color;

		Dot(Color color)
		{
			this.color = color;
			setPreferredSize(new Dimension(10, 16));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			int d = 8;
			g2.fillOval((getWidth() - d) / 2, (getHeight() - d) / 2, d, d);
			g2.dispose();
		}
	}
}

