/**
 * Damage and healing meter. Game data is read and counted on the client thread; party messages
 * are moved there from the websocket thread, and the panel receives finished reports on the
 * Swing thread.
 */
@Slf4j
@PluginDescriptor(
	name = "GoldenDPS",
	description = "DPS, damage and healing meter for groups and individuals",
	tags = {"dps", "damage", "meter", "party", "healing", "boss", "pvm", "raid"},
	internalName = "goldendps",
	// fights and personal bests used to be saved in .runelite/goldendps
	legacyDataDirectory = "goldendps"
)
// the hit chance counts the slayer helmet on the task that RuneLite's Slayer plugin knows
@PluginDependency(SlayerPlugin.class)
public class GoldenDpsPlugin extends Plugin implements FightTracker.Listener
{
	private static final int PANEL_EVERY_TICKS = 2;
	private static final String PANEL_TOGGLES_KEY = "panelToggles";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GoldenDpsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GoldenDpsOverlay overlay;

	@Inject
	private HeadIconOverlay headIconOverlay;

	@Inject
	private DefenceOverlay defenceOverlay;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SlayerPluginService slayer;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ChatNotifier chat;

	@Inject
	private PartyManager party;

	@Inject
	private LocalHealing healing;

	@Inject
	private BarrowsTracker barrows;

	private final FightTracker tracker = new FightTracker();
	private final Bosses bosses = new Bosses();
	private final TargetMatcher matcher = new TargetMatcher();
	private final FunEffects fun = new FunEffects();
	/** Kept over plugin restarts, like the game chat it is read from. */
	private final KillCounts killCounts = new KillCounts();
	private final RaidPoints raidPoints = new RaidPoints();

	// made in startUp, when the injected fields are set
	private FightStorage storage;
	private PartyUpdates partyUpdates;
	private CombatEvents combat;
	private RaidFights raids;
	private PartyReports reports;
	private MeterViews views;
	private DefenceDrains defence;
	private TargetHitChance hitChance;
	/** Your hit chance on the monster you attack, null when unknown; read by the panel. */
	private volatile TargetHitChance.Result hitChanceCache;

	private GoldenDpsPanel panel;
	private NavigationButton navButton;
	private int ticks;
	private volatile FightReport overlayCache;
	private volatile BossMeter bossCache;
	/** Target key to the lines above that NPC. */
	private volatile Map<String, String[]> defenceCache = Collections.emptyMap();
	/** Worked out on the client thread: the overlay must not read the fight history. */
	private volatile boolean overallGoingOn;
	private volatile boolean overallPaused;

	@Provides
	GoldenDpsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GoldenDpsConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		createParts();
		tracker.setListener(this);

		overlayManager.add(overlay);
		overlayManager.add(headIconOverlay);
		overlayManager.add(defenceOverlay);
		wsClient.registerMessage(GoldenDpsUpdate.class);
		wsClient.registerMessage(GoldenDpsPartyMessage.class);

		panel = new GoldenDpsPanel(this);
		navButton = NavigationButton.builder()
			.tooltip("GoldenDPS")
			.icon(ImageUtil.loadImageResource(GoldenDpsPlugin.class, "icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				storage.loadAccount(client.getAccountHash());
			}
		});
	}

	private void createParts() throws IOException
	{
		HistoryStore store = new HistoryStore(gson, getPluginDirectory());
		storage = new FightStorage(tracker, store, executor, clientThread, () ->
		{
			refreshOverlay();
			updatePanel();
		});
		NpcStats npcStats = NpcStats.load();
		defence = new DefenceDrains(npcStats);
		partyUpdates = new PartyUpdates(client, partyService, party, config, tracker, bosses, matcher, defence);
		combat = new CombatEvents(client, partyService, config, tracker, bosses, matcher, healing, barrows, party,
			partyUpdates, defence);
		hitChance = new TargetHitChance(client, itemManager, slayer, npcStats, WeaponStyles.load(), defence, tracker,
			combat);
		raids = new RaidFights(client, chat, tracker);
		reports = new PartyReports(config, partyService, party, chat, storage, killCounts, raidPoints);
		views = new MeterViews(config, tracker, storage, new BossHealth(client), barrows, party, fun, defence);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() ->
		{
			tracker.endNow(System.currentTimeMillis(), "Plugin turned off");
			storage.save();
			storage.unload();
			tracker.clearHistory();
			overlayCache = null;
			bossCache = null;
			hitChanceCache = null;
			defence.clear();
			defenceCache = Collections.emptyMap();
			reports.clear();
			healing.reset();
			partyUpdates.clear();
		});
		wsClient.unregisterMessage(GoldenDpsUpdate.class);
		wsClient.unregisterMessage(GoldenDpsPartyMessage.class);
		overlayManager.remove(overlay);
		overlayManager.remove(headIconOverlay);
		overlayManager.remove(defenceOverlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (GoldenDpsConfig.GROUP.equals(e.getGroup()))
		{
			clientThread.invoke(() ->
			{
				refreshOverlay();
				updatePanel();
				if ("chatColor".equals(e.getKey()))
				{
					chat.recolorOldMessages();
				}
			});
		}
	}

	// ---- game events ----

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		combat.hitsplatApplied(e.getActor(), e.getHitsplat());
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged e)
	{
		combat.graphicChanged(e.getActor());
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved e)
	{
		combat.projectileMoved(e.getProjectile());
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		combat.animationChanged(e.getActor());
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (e.getSkill() == Skill.HITPOINTS)
		{
			healing.hpChanged(e.getLevel(), e.getBoostedLevel());
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		String option = Text.removeTags(e.getMenuOption());
		if (option == null)
		{
			return;
		}
		int tick = client.getTickCount();
		if (option.equals("Eat") || option.equals("Drink") || option.equals("Quaff"))
		{
			healing.eatClicked(e.getItemId(), tick);
		}
		else if (option.equals("Cast"))
		{
			String target = Text.removeTags(e.getMenuTarget());
			if (target == null)
			{
				return;
			}
			if (target.startsWith("Heal Other") || target.startsWith("Heal Group"))
			{
				healing.healOtherCast(tick);
			}
			else if (target.contains("->"))
			{
				combat.spellCastClicked(tick, target);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == InventoryID.INV)
		{
			healing.inventoryChanged(e.getItemContainer(), client.getTickCount());
		}
	}

	/** While GoldenDPS shows a line over a player, their typed chat only shows in the chatbox. */
	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged e)
	{
		if (e.getActor() instanceof Player && hasFunLine((Player) e.getActor()))
		{
			e.getActor().setOverheadText("");
		}
	}

	private boolean hasFunLine(Player p)
	{
		String name = Names.clean(p.getName());
		return name != null && config.healerSnack() && fun.line(name, System.currentTimeMillis()) != null;
	}

	/** Hides chat that was already over a head when a GoldenDPS line starts. */
	private void hideOverheadChat()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !fun.anyone())
		{
			return;
		}
		for (Player p : wv.players())
		{
			String text = p == null ? null : p.getOverheadText();
			if (text != null && !text.isEmpty() && hasFunLine(p))
			{
				p.setOverheadText("");
			}
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		NPC npc = e.getNpc();
		String key = TargetMatcher.key(client.getWorld(), npc.getIndex());
		defence.remove(key);
		if (npc.isDead())
		{
			// the fight may end with this death, so take it before
			Fight fight = tracker.getCurrent();
			tracker.npcDied(System.currentTimeMillis(), key, bosses.isBoss(npc.getId(), Names.clean(npc.getName())));
			if (fight != null)
			{
				storage.monsterDied(fight, key);
			}
			barrows.died(System.currentTimeMillis(), Names.clean(npc.getName()));
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() == ChatMessageType.GAMEMESSAGE)
		{
			long now = System.currentTimeMillis();
			killCounts.message(now, e.getMessage());
			raidPoints.message(now, e.getMessage());
			raids.gameMessage(now, e.getMessage());
			barrows.gameMessage(now, e.getMessage(), tracker);
			takeGameTime(now, e.getMessage());
			combat.gameMessage(e.getMessage());
		}
	}

	private void takeGameTime(long now, String message)
	{
		GameTimes.Time time = GameTimes.parse(message);
		Fight ended = time == null ? null : tracker.gameTime(now, time);
		if (ended != null)
		{
			storage.gameTimeChanged(ended);
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		long now = System.currentTimeMillis();
		int tick = client.getTickCount();

		combat.tick(tick);

		List<HealthWatcher.Heal> heals = healing.endTick(tick);
		if (tracker.getCurrent() != null)
		{
			heals.forEach(heal -> addOwnHeal(now, heal));
		}

		tracker.tick(now);
		barrows.tick(now, tick);
		partyUpdates.send();
		reports.sendDue(tick);
		storage.tick(now);
		raids.tick(now);
		party.tick(now, raids.isInsideRaid());
		refreshOverlay();
		hideOverheadChat();
		if (++ticks % PANEL_EVERY_TICKS == 0)
		{
			updatePanel();
		}
	}

	private void addOwnHeal(long now, HealthWatcher.Heal heal)
	{
		if (heal.type == HealType.RECEIVED)
		{
			return;
		}
		tracker.heal(now, localName(), PlayerKind.LOCAL, heal.type, heal.amount, heal.overheal);
		partyUpdates.addHeal(heal);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState state = e.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			storage.loadAccount(client.getAccountHash());
			barrows.loggedIn();
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// the party first: an error in the clean-up below must not keep you in the party
			party.loggedOut(state == GameState.LOGIN_SCREEN);
			if (state == GameState.LOGIN_SCREEN)
			{
				executor.schedule(party::leaveIfStillLoggedOut, PartyManager.LEAVE_AFTER_LOGOUT_MS,
					TimeUnit.MILLISECONDS);
			}
			long now = System.currentTimeMillis();
			String reason = state == GameState.HOPPING ? "World hop" : "Logged out";
			healing.reset();
			combat.reset();
			matcher.clear();
			defence.clear();
			raids.reset();
			barrows.loggedOut(now);
			partyUpdates.clear();
			tracker.endRaid(now, reason);
			tracker.endNow(now, reason);
			storage.save();
			refreshOverlay();
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown e)
	{
		// not on the client thread, but the game loop has stopped by now
		try
		{
			long now = System.currentTimeMillis();
			party.clientClosed();
			barrows.clientClosed(now);
			tracker.endNow(now, "Client closed");
			Future<?> write = storage.saveNow();
			if (write != null)
			{
				e.waitFor(write);
			}
		}
		catch (ConcurrentModificationException ex)
		{
			log.warn("Could not save on shutdown", ex);
		}
	}

	@Override
	public void fightEnded(Fight fight)
	{
		storage.fightEnded(fight);
		reports.fightEnded(fight, client.getTickCount());
	}

	// ---- party ----

	@Subscribe
	public void onGoldenDpsUpdate(GoldenDpsUpdate update)
	{
		clientThread.invokeLater(() -> partyUpdates.receive(update));
	}

	@Subscribe
	public void onGoldenDpsPartyMessage(GoldenDpsPartyMessage message)
	{
		clientThread.invokeLater(() ->
		{
			party.onMessage(message);
			updatePanel();
		});
	}

	@Subscribe
	public void onUserPart(UserPart e)
	{
		clientThread.invokeLater(() -> party.onMemberLeft(e.getMemberId()));
	}

	// ---- overlay and panel ----

	FightReport overlayReport()
	{
		return overlayCache;
	}

	BossMeter bossMeter()
	{
		return bossCache;
	}

	boolean isFightRunning()
	{
		return overallGoingOn;
	}

	boolean isFightPaused()
	{
		return overallPaused;
	}

	String barrowsRunTime()
	{
		return barrows.liveTime();
	}

	boolean isBarrowsRunPaused()
	{
		return barrows.isPaused();
	}

	/** The overlays draw on their own thread, so what they show is built here on the client thread. */
	private void refreshOverlay()
	{
		long now = System.currentTimeMillis();
		overlayCache = views.overlayReport(now);
		overallGoingOn = tracker.isOverallGoingOn(now);
		// between two fights of the overall meter, or no hits for a while in the running fight
		Fight running = tracker.getCurrent();
		overallPaused = running != null ? running.isPaused(now) : overallGoingOn;
		views.updateFun(now);
		bossCache = views.bossMeter(now);
		hitChanceCache = config.showHitChance() ? hitChance.now() : null;
		defenceCache = views.defenceLabels(config.showDefence(), hitChanceCache);
	}

	/** Target key to the lines above that NPC; read by the defence overlay. */
	Map<String, String[]> defenceLabels()
	{
		return defenceCache;
	}

	FunEffects fun()
	{
		return fun;
	}

	/** Builds the panel data on the client thread and hands it to Swing. */
	void updatePanel()
	{
		GoldenDpsPanel p = panel;
		if (p == null || !p.isPanelOpen())
		{
			return;
		}
		GoldenDpsPanel.Data data = views.panelData(p.getSelectedId(), localName(), System.currentTimeMillis(),
			hitChanceCache);
		SwingUtilities.invokeLater(() -> p.update(data));
	}

	// ---- actions from the overlay menu and the panel (Swing thread) ----

	void joinParty(String name)
	{
		clientThread.invoke(() ->
		{
			party.join(name);
			updatePanel();
		});
	}

	void randomPartyName()
	{
		clientThread.invoke(() ->
		{
			String name = party.randomName();
			GoldenDpsPanel p = panel;
			if (name != null && p != null)
			{
				SwingUtilities.invokeLater(() -> p.setPartyName(name));
			}
		});
	}

	void rejoinParty()
	{
		clientThread.invoke(() ->
		{
			party.rejoin();
			updatePanel();
		});
	}

	void leaveParty()
	{
		clientThread.invoke(() ->
		{
			party.leave();
			updatePanel();
		});
	}

	void kickFromParty(long memberId, String name)
	{
		clientThread.invoke(() ->
		{
			party.kick(memberId, name);
			updatePanel();
		});
	}

	/** Reports what the overlay shows: the fight (or session), or the boss of the boss meter. */
	void reportOverlayToParty(ReportKind kind)
	{
		clientThread.invoke(() ->
		{
			long now = System.currentTimeMillis();
			reports.sendByHand(views.overlayFight(kind, now), kind, views.isSessionOverlay(), now);
		});
	}

	/** Reports the fight picked in the panel. */
	void reportPanelToParty(ReportKind kind)
	{
		GoldenDpsPanel p = panel;
		String selected = p == null ? null : p.getSelectedId();
		clientThread.invoke(() ->
		{
			long now = System.currentTimeMillis();
			reports.sendByHand(views.panelFight(selected, now), kind, GoldenDpsPanel.SESSION_CHOICE.equals(selected), now);
		});
	}

	void setMode(MeterMode mode)
	{
		configManager.setConfiguration(GoldenDpsConfig.GROUP, GoldenDpsConfig.MODE_KEY, mode);
	}

	void setBossOnly(boolean bossOnly)
	{
		configManager.setConfiguration(GoldenDpsConfig.GROUP, GoldenDpsConfig.BOSS_ONLY_KEY, bossOnly);
	}

	void setScope(GoldenDpsConfig.Scope scope)
	{
		configManager.setConfiguration(GoldenDpsConfig.GROUP, GoldenDpsConfig.SCOPE_KEY, scope);
	}

	void resetSession()
	{
		runAndRefresh(() ->
		{
			tracker.resetSession(System.currentTimeMillis());
			storage.save();
		});
	}

	void endFight()
	{
		runAndRefresh(() -> tracker.endNow(System.currentTimeMillis(), "Ended by you"));
	}

	void resetMonster(String name)
	{
		runAndRefresh(() -> storage.resetMonster(name));
	}

	void resetAllMonsters()
	{
		runAndRefresh(storage::resetAllMonsters);
	}

	void clearHistory()
	{
		runAndRefresh(() ->
		{
			tracker.clearHistory();
			storage.save();
		});
	}

	/** The panel sections that are shown or hidden against their default, comma separated. */
	String panelToggles()
	{
		String toggles = configManager.getConfiguration(GoldenDpsConfig.STATE_GROUP, PANEL_TOGGLES_KEY);
		return toggles == null ? "" : toggles;
	}

	void savePanelToggles(String toggles)
	{
		configManager.setConfiguration(GoldenDpsConfig.STATE_GROUP, PANEL_TOGGLES_KEY, toggles);
	}

	void requestPanelUpdate()
	{
		clientThread.invoke(this::updatePanel);
	}

	/** Runs a change to the fights on the client thread and shows the result. */
	private void runAndRefresh(Runnable action)
	{
		clientThread.invoke(() ->
		{
			action.run();
			refreshOverlay();
			updatePanel();
		});
	}

	private String localName()
	{
		return Names.localName(client);
	}
}

package com.goldendps;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Everything one player did in a game tick, sent to the party. Sent every tick, so the JSON
 * field names are kept short. The party server identifies messages by class name, which must
 * therefore never change.
 */
public class GoldenDpsUpdate extends PartyMemberMessage
{
	public static class Hit
	{
		/** The same on every client in the same world or instance. */
		@SerializedName("i")
		public int npcIndex;
		@SerializedName("id")
		public int npcId;
		@SerializedName("nm")
		public String npcName;
		@SerializedName("a")
		public int amount;
		public boolean miss;
		public boolean boss;
		/** NPC position; instances have their own coordinates, which tells instances apart. */
		public int x;
		public int y;
		@SerializedName("p")
		public int plane;
		/** Weapon, special attack or spell; null from older versions. */
		@SerializedName("s")
		public String source;

		public Hit()
		{
		}

		Hit(int npcIndex, int npcId, String npcName, int amount, boolean miss, boolean boss, WorldPoint pos)
		{
			this.npcIndex = npcIndex;
			this.npcId = npcId;
			this.npcName = npcName;
			this.amount = amount;
			this.miss = miss;
			this.boss = boss;
			if (pos != null)
			{
				x = pos.getX();
				y = pos.getY();
				plane = pos.getPlane();
			}
		}
	}

	@SerializedName("v")
	public int version = 3;
	@SerializedName("w")
	public int world;
	@SerializedName("n")
	public String name;
	@SerializedName("h")
	public List<Hit> hits = new ArrayList<>();
	public int taken;
	public int food;
	@SerializedName("life")
	public int lifesteal;
	public int regen;
	@SerializedName("other")
	public int healOther;
	@SerializedName("of")
	public int foodOverheal;
	@SerializedName("ol")
	public int lifestealOverheal;

	boolean isEmpty()
	{
		return hits.isEmpty() && taken == 0 && food == 0 && lifesteal == 0 && regen == 0 && healOther == 0
			&& foodOverheal == 0 && lifestealOverheal == 0;
	}
}

package com.goldendps;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the crown over the MVP and the snacks with hungry lines over the top healers. */
class HeadIconOverlay extends Overlay
{
	/** Above the head, clear of overhead prayers and skulls. */
	private static final int ABOVE_HEAD = 90;
	/** Height of one icon in the stack above a head. */
	private static final int ICON_STEP = 22;
	private static final Color TALK_COLOR = new Color(255, 255, 0);

	private final Client client;
	private final GoldenDpsConfig config;
	private final FunEffects fun;

	@Inject
	HeadIconOverlay(Client client, GoldenDpsConfig config, GoldenDpsPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.fun = plugin.fun();
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long now = System.currentTimeMillis();
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !fun.anyone())
		{
			return null;
		}
		g.setFont(FontManager.getRunescapeBoldFont());
		for (Player p : wv.players())
		{
			String name = p == null ? null : Names.clean(p.getName());
			if (name != null)
			{
				drawAbove(g, p, name, now);
			}
		}
		return null;
	}

	/** Stacks the icons upwards from the head: burger, fries, crown, then what the player says. */
	private void drawAbove(Graphics2D g, Player p, String name, long now)
	{
		int height = p.getLogicalHeight() + ABOVE_HEAD;
		boolean snacks = config.healerSnack();
		if (snacks && fun.hasBurger(name))
		{
			drawIcon(g, p, FunIcons.BURGER, height);
			height += ICON_STEP;
		}
		if (snacks && fun.hasFries(name))
		{
			drawIcon(g, p, FunIcons.FRIES, height);
			height += ICON_STEP;
		}
		if (config.mvpCrown() && fun.hasCrown(name))
		{
			drawIcon(g, p, FunIcons.CROWN, height);
			height += ICON_STEP;
		}
		String line = snacks ? fun.line(name, now) : null;
		if (line != null)
		{
			drawText(g, p, line, height + 8);
		}
	}

	private static void drawIcon(Graphics2D g, Player p, BufferedImage icon, int height)
	{
		Point at = p.getCanvasImageLocation(icon, height);
		if (at != null)
		{
			g.drawImage(icon, at.getX(), at.getY(), null);
		}
	}

	private static void drawText(Graphics2D g, Player p, String text, int height)
	{
		Point at = p.getCanvasTextLocation(g, text, height);
		if (at != null)
		{
			g.setColor(Color.BLACK);
			g.drawString(text, at.getX() + 1, at.getY() + 1);
			g.setColor(TALK_COLOR);
			g.drawString(text, at.getX(), at.getY());
		}
	}
}

package com.goldendps;

import com.goldendps.model.HealTable;
import com.goldendps.model.HealthWatcher;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.SpotanimID;

/**
 * Your own healing: food and potions, lifesteal (Sanguinesti staff, blood spells) and Heal Other.
 * Feeds the game events into {@link HealthWatcher}, which turns HP changes into heals and overheal.
 * Client thread only.
 */
class LocalHealing
{
	private static final int WEAPON_SLOT = 3;
	/** A food click is confirmed when the item leaves the inventory within this many ticks. */
	private static final int EAT_CONFIRM_TICKS = 3;
	private static final int[] SANGUINESTI_HEAL = {SpotanimID.SANGUINESTI_STAFF_HEAL, SpotanimID.SANGUINESTI_STAFF_HEAL_JUSTICIAR};
	private static final int[] BLOOD_SPELL_IMPACT = {SpotanimID.BLOOD_RUSH_IMPACT, SpotanimID.BLOOD_BLITZ_IMPACT,
		SpotanimID.SPELL_BLOOD_BURST_IMPACT, SpotanimID.SPELL_BLOOD_BARRAGE_IMPACT};

	private final Client client;
	private final HealthWatcher health = new HealthWatcher();
	/** Your damage per NPC this tick, for lifesteal. */
	private final Map<NPC, Integer> damageThisTick = new HashMap<>();
	/** Item id to the tick it was clicked to eat or drink. */
	private final Map<Integer, Integer> eatClicks = new HashMap<>();
	private Map<Integer, Integer> lastInventory;

	@Inject
	LocalHealing(Client client)
	{
		this.client = client;
	}

	void hpChanged(int level, int boosted)
	{
		health.setMaxHp(level);
		health.hpChanged(boosted);
	}

	void damageOnYou(int amount)
	{
		health.damageOnMe(amount);
	}

	void youHit(NPC npc, int amount, int tick)
	{
		health.myHit(tick);
		damageThisTick.merge(npc, amount, Integer::sum);
	}

	void eatClicked(int itemId, int tick)
	{
		health.consumed(tick);
		if (itemId > 0)
		{
			eatClicks.put(itemId, tick);
		}
	}

	void healOtherCast(int tick)
	{
		health.healOtherCast(tick);
	}

	void inventoryChanged(ItemContainer inventory, int tick)
	{
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : inventory.getItems())
		{
			if (item.getId() > 0)
			{
				now.merge(item.getId(), Math.max(1, item.getQuantity()), Integer::sum);
			}
		}
		Map<Integer, Integer> before = lastInventory;
		lastInventory = now;
		if (before == null || eatClicks.isEmpty())
		{
			return;
		}
		int hpLevel = client.getRealSkillLevel(Skill.HITPOINTS);
		Iterator<Map.Entry<Integer, Integer>> it = eatClicks.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<Integer, Integer> click = it.next();
			int id = click.getKey();
			if (tick - click.getValue() > EAT_CONFIRM_TICKS)
			{
				it.remove();
			}
			else if (now.getOrDefault(id, 0) < before.getOrDefault(id, 0))
			{
				String name = itemName(id);
				health.foodEaten(tick, HealTable.foodHeal(name, hpLevel), HealTable.foodBoost(name, hpLevel));
				it.remove();
			}
		}
	}

	List<HealthWatcher.Heal> endTick(int tick)
	{
		checkLifesteal(tick);
		return health.endTick(tick);
	}

	void reset()
	{
		health.reset();
		damageThisTick.clear();
		eatClicks.clear();
		lastInventory = null;
	}

	/** Weapon name, or null when unarmed. */
	String weaponName()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return null;
		}
		Item[] items = worn.getItems();
		return items.length > WEAPON_SLOT && items[WEAPON_SLOT].getId() > 0 ? itemName(items[WEAPON_SLOT].getId()) : null;
	}

	private String itemName(int itemId)
	{
		ItemComposition def = client.getItemDefinition(itemId);
		return def == null ? null : def.getName();
	}

	/** Tells the watcher how much this tick's Sanguinesti procs and blood spells would heal. */
	private void checkLifesteal(int tick)
	{
		if (damageThisTick.isEmpty())
		{
			return;
		}
		Player me = client.getLocalPlayer();
		boolean sangOnMe = me != null && hasAny(me, SANGUINESTI_HEAL);
		String weapon = null;
		int bloodbark = 0;
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			Item[] items = worn.getItems();
			for (int i = 0; i < items.length; i++)
			{
				if (items[i].getId() <= 0)
				{
					continue;
				}
				String name = itemName(items[i].getId());
				if (i == WEAPON_SLOT)
				{
					weapon = name;
				}
				if (name != null && name.startsWith("Bloodbark"))
				{
					bloodbark++;
				}
			}
		}
		int sang = 0;
		int blood = 0;
		for (Map.Entry<NPC, Integer> e : damageThisTick.entrySet())
		{
			NPC npc = e.getKey();
			if (sangOnMe || hasAny(npc, SANGUINESTI_HEAL))
			{
				sang += HealTable.sanguinesti(e.getValue());
			}
			else if (HealTable.isMagicWeapon(weapon) && hasAny(npc, BLOOD_SPELL_IMPACT))
			{
				blood += HealTable.bloodSpell(e.getValue(), bloodbark, weapon);
			}
		}
		damageThisTick.clear();
		health.lifesteal(tick, sang, 0);
		health.lifesteal(tick, blood, HealTable.bloodBoost(weapon, client.getRealSkillLevel(Skill.HITPOINTS)));
	}

	private static boolean hasAny(Actor actor, int[] spotAnims)
	{
		for (int id : spotAnims)
		{
			if (actor.hasSpotAnim(id))
			{
				return true;
			}
		}
		return false;
	}
}

package com.goldendps;

import com.goldendps.model.BossRecords;
import com.goldendps.model.DefenceDrains;
import com.goldendps.model.Fight;
import com.goldendps.model.FightReport;
import com.goldendps.model.FightTracker;
import com.goldendps.model.Format;
import com.goldendps.model.KillRates;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Turns the tracked fights into what the overlays and the panel show. Client thread only. */
class MeterViews
{
	private final GoldenDpsConfig config;
	private final FightTracker tracker;
	private final FightStorage storage;
	private final BossHealth bossHealth;
	private final BarrowsTracker barrows;
	private final PartyManager party;
	private final FunEffects fun;
	private final DefenceDrains defence;

	MeterViews(GoldenDpsConfig config, FightTracker tracker, FightStorage storage, BossHealth bossHealth,
		BarrowsTracker barrows, PartyManager party, FunEffects fun, DefenceDrains defence)
	{
		this.config = config;
		this.tracker = tracker;
		this.storage = storage;
		this.bossHealth = bossHealth;
		this.barrows = barrows;
		this.party = party;
		this.fun = fun;
		this.defence = defence;
	}

	/**
	 * Target key to the lines above that NPC: "Def 120 / 246  Hit chance 78%" and "DWH x2 -126, BGS -34".
	 * @param showDefence false shows only the hit chance
	 * @param hit your hit chance on the monster you attack, or null
	 */
	Map<String, String[]> defenceLabels(boolean showDefence, TargetHitChance.Result hit)
	{
		Map<String, String[]> labels = new HashMap<>();
		if (showDefence)
		{
			defence.all().forEach((key, t) -> labels.put(key, new String[]{levels(t), t.summary()}));
		}
		if (hit != null)
		{
			String[] lines = labels.get(hit.targetKey);
			String chance = (hit.spec ? "Spec hit chance " : "Hit chance ") + percent(hit.now);
			labels.put(hit.targetKey, lines == null ? new String[]{chance} : new String[]{lines[0] + "  " + chance, lines[1]});
		}
		return labels;
	}

	/** "Def 120 / 246", plus "  Magic 120 / 150" when the magic level is lowered too. */
	private static String levels(DefenceDrains.Target t)
	{
		String magic = t.getMagicCurrent() < t.magicBase ? "  Magic " + t.getMagicCurrent() + " / " + t.magicBase : "";
		return "Def " + t.getCurrent() + " / " + t.base + magic;
	}

	private static String percent(double chance)
	{
		return Math.round(chance * 100) + "%";
	}

	/** {label, value} lines for the panel: each monster with lowered defence, then each special attack. */
	private List<String[]> defenceLines(String localName, TargetHitChance.Result hit)
	{
		List<String[]> lines = new ArrayList<>();
		if (hit != null)
		{
			String now = percent(hit.now);
			String before = percent(hit.before);
			String value = now.equals(before) ? now : now + " (was " + before + ")";
			lines.add(new String[]{(hit.spec ? "Spec hit chance: " : "Hit chance: ") + hit.name, value});
		}
		for (DefenceDrains.Target t : defence.all().values())
		{
			lines.add(new String[]{t.name, levels(t)});
			for (DefenceDrains.Drain d : t.getDrains())
			{
				String who = Objects.equals(d.player, localName) ? "you" : d.player;
				lines.add(new String[]{"+ " + DefenceDrains.shortName(d.weapon) + " (" + who + ")",
					"-" + d.amount + (d.magic ? " magic" : "")});
			}
		}
		return lines;
	}

	/** The main overlay meter: the overall fights or the session; null when there is none. */
	FightReport overlayReport(long now)
	{
		Fight fight = isSessionOverlay() ? tracker.getSessionTotal(now) : tracker.getOverall(now);
		return fight == null ? null : FightReport.of(fight, config.bossOnly(), now);
	}

	/** The second overlay meter for the current boss, or null when it is turned off or has nothing to show. */
	BossMeter bossMeter(long now)
	{
		Fight shown = tracker.getBossDisplayFight();
		if (!config.bossMeter() || config.bossOnly() || shown == null || !shown.hasBossMeter())
		{
			return null;
		}
		FightReport report = FightReport.of(shown, true, now);
		BossRecords.Record record = storage.record(report.getTitle(), BossRecords.isParty(report));
		String pb = BossRecords.meterTag(record, storage.compare(shown.id));
		boolean dead = shown.bossDiedMs() > 0;
		// a timed boss's health bar is its clock, not your damage: no pace there
		Long pace = dead || BossRecords.isTimed(report.getTitle()) ? null
			: BossRecords.paceMs(report.getDurationMs(), bossHealth.done(shown), record);
		return new BossMeter(report, dead, !dead && shown.isPaused(now), pb, pace);
	}

	/** Gives the crown and the snacks to the players of the shown fight and boss. */
	void updateFun(long now)
	{
		Fight fight = tracker.getDisplayFight();
		Fight boss = tracker.getBossDisplayFight();
		FightReport fightReport = fight == null ? null : FightReport.of(fight, false, now);
		FightReport bossReport = boss == null || !boss.hasBossTarget()
			? null : FightReport.of(boss, true, now);
		fun.update(fightReport, fight == null ? 0 : fight.endMs, bossReport, boss == null ? 0 : boss.endMs,
			boss == null ? "" : boss.id, now);
	}

	/** The fight shown in the overlay, for a report of this kind. */
	Fight overlayFight(ReportKind kind, long now)
	{
		if (isSessionOverlay())
		{
			return tracker.getSessionTotal(now);
		}
		return kind == ReportKind.BOSS ? tracker.getBossDisplayFight() : tracker.getOverall(now);
	}

	boolean isSessionOverlay()
	{
		return config.overlayScope() == GoldenDpsConfig.Scope.SESSION;
	}

	/** The fight for a choice of the panel's fight list, or null. */
	Fight panelFight(String choiceId, long now)
	{
		if (GoldenDpsPanel.SESSION_CHOICE.equals(choiceId))
		{
			return tracker.getSessionTotal(now);
		}
		if (choiceId == null || GoldenDpsPanel.LIVE_CHOICE.equals(choiceId))
		{
			return tracker.getDisplayFight();
		}
		return tracker.findFight(choiceId);
	}

	/** @param hit your hit chance on the monster you attack, or null */
	GoldenDpsPanel.Data panelData(String selectedId, String localName, long now, TargetHitChance.Result hit)
	{
		GoldenDpsPanel.Data data = new GoldenDpsPanel.Data();
		data.choices.add(new GoldenDpsPanel.Choice(GoldenDpsPanel.LIVE_CHOICE,
			tracker.getCurrent() != null ? "Current fight (live)" : "Current / last fight"));
		data.choices.add(new GoldenDpsPanel.Choice(GoldenDpsPanel.SESSION_CHOICE, "Session total"));
		for (Fight f : tracker.getHistory())
		{
			data.choices.add(new GoldenDpsPanel.Choice(f.id, GoldenDpsPanel.label(f, now)));
		}
		data.bossOnly = config.bossOnly();

		Fight fight = panelFight(selectedId, now);
		if (fight != null)
		{
			data.report = FightReport.of(fight, config.bossOnly(), now);
			data.running = fight.isActive();
			data.paused = fight.isPaused(now);
			data.endReason = fight.endReason;
			data.fights = fight.mergedFights;
			data.startMs = fight.startMs;
			if (!config.bossOnly() && fight.hasBossTarget())
			{
				data.bossReport = FightReport.of(fight, true, now);
			}
			data.killLines = BossRecords.killLines(storage.compare(fight.id));
			data.bossTimes = bossTimes(fight, now);
		}
		data.monsters = storage.monsterEntries();
		data.killRates = KillRates.of(sessionFights(), now);
		data.barrowsRunTime = barrows.liveTime();
		data.barrowsRunPaused = barrows.isPaused();
		data.party = party.view(localName);
		data.defence = defenceLines(localName, hit);
		return data;
	}

	/** Raid splits: every boss of a raid fight with its time and PB. */
	private List<String[]> bossTimes(Fight raidFight, long now)
	{
		List<String[]> out = new ArrayList<>();
		if (raidFight.raid == null || raidFight.partOf != null || raidFight.run)
		{
			return out;
		}
		for (Fight part : tracker.partsOf(raidFight))
		{
			FightReport report = FightReport.of(part, true, now);
			BossRecords.Compare kill = storage.compare(part.id);
			String tag;
			if (kill != null)
			{
				tag = kill.newFastest && kill.before != null ? "NEW PB!"
					: kill.before != null ? "PB " + Format.preciseDuration(kill.before.fastestMs) : "";
			}
			else
			{
				BossRecords.Record pb = storage.record(report.getTitle(), BossRecords.isParty(report));
				tag = pb != null ? "PB " + Format.preciseDuration(pb.fastestMs) : "";
			}
			out.add(new String[]{report.getTitle(), Format.preciseDuration(report.getDurationMs()), tag});
		}
		return out;
	}

	/** The ended fights of this session and the running one. */
	private List<Fight> sessionFights()
	{
		List<Fight> fights = tracker.getSessionFights();
		if (tracker.getCurrent() != null)
		{
			fights.add(0, tracker.getCurrent());
		}
		return fights;
	}
}

package com.goldendps;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.util.Text;

final class Names
{
	private Names()
	{
	}

	/** Player or NPC name without tags (CoX colors "<col=00ffff>Guardian</col>") and non-breaking spaces, or null when it is unknown. */
	static String clean(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = Text.removeTags(name).replace(' ', ' ').trim();
		return n.isEmpty() || n.equals("<unknown>") ? null : n;
	}

	/** Your own name, or "You" before the game knows it. Client thread only. */
	static String localName(Client client)
	{
		Player me = client.getLocalPlayer();
		String name = me == null ? null : clean(me.getName());
		return name == null ? "You" : name;
	}
}

package com.goldendps;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** The small Swing pieces both panel tabs are built from. Swing thread only. */
final class PanelWidgets
{
	static final Color GOLD = new Color(255, 196, 0);

	private PanelWidgets()
	{
	}

	static JButton button(String text, String tip, Runnable action)
	{
		JButton b = new JButton(text);
		b.setToolTipText(tip);
		b.setFocusable(false);
		b.setMargin(new Insets(2, 2, 2, 2));
		b.setFont(FontManager.getRunescapeSmallFont());
		b.addActionListener(e -> action.run());
		return b;
	}

	static JLabel small(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		return l;
	}

	static JLabel bold(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(color);
		return l;
	}

	/** A gray hint in the default font. */
	static JLabel note(String text)
	{
		JLabel l = new JLabel(text);
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		return l;
	}

	/** A dark card that holds lines. */
	static JPanel section()
	{
		// never taller than its lines, also when the panel has room to spare
		JPanel p = new JPanel(new GridLayout(0, 1, 0, 1))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		p.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		return p;
	}

	static JComponent line(String key, String value)
	{
		return line(key, value, null);
	}

	/** A title on the left and a small gray action word ("hide", "reset") on the right; a click runs it. */
	static JComponent actionRow(JLabel title, String action, String tip, Runnable onClick)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.add(title, BorderLayout.WEST);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		if (action == null)
		{
			return row;
		}
		row.add(small(action, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		row.setToolTipText(tip);
		clickable(row, onClick);
		return row;
	}

	/** A right-click menu with one item, on the component and everything in it. */
	static void rightClickMenu(JComponent c, String item, Runnable onClick)
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem menuItem = new JMenuItem(item);
		menuItem.addActionListener(e -> onClick.run());
		menu.add(menuItem);
		c.setComponentPopupMenu(menu);
		inheritMenu(c);
	}

	private static void inheritMenu(Container c)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof Container)
			{
				inheritMenu((Container) child);
			}
		}
	}

	/** A hand cursor, and a left click runs {@code onClick}. Labels with a tooltip catch clicks, so they get it too. */
	static void clickable(Component c, Runnable onClick)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// a right click opens a menu, if there is one; it should not also open or close a section
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}
		});
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				clickable(child, onClick);
			}
		}
	}

	/** A key on the left and a value on the right; {@code highlight} colors both. */
	static JComponent line(String key, String value, Color highlight)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		JLabel keyLabel = new JLabel(key);
		keyLabel.setForeground(highlight != null ? highlight : ColorScheme.LIGHT_GRAY_COLOR);
		keyLabel.setFont(FontManager.getRunescapeSmallFont());
		JLabel valueLabel = new JLabel(value);
		valueLabel.setForeground(highlight != null ? highlight : Color.WHITE);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		// in the center the key gets what the value leaves and ends with "..." instead of overlapping it
		keyLabel.setToolTipText(key);
		p.add(keyLabel, BorderLayout.CENTER);
		p.add(valueLabel, BorderLayout.EAST);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
		return p;
	}
}

package com.goldendps;

import com.goldendps.model.PartyLeader;
import com.goldendps.model.PartyNotices;
import com.goldendps.model.RaidParty;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

/**
 * Everything about the RuneLite party: joining and leaving, the GoldenDPS leader and kick,
 * chat notices, the automatic raid party, and which members are in your instance.
 * All methods run on the client thread.
 */
@Slf4j
@Singleton
class PartyManager
{
	/** A member counts as running GoldenDPS for this long after their last update. */
	private static final long REPORTER_MS = 120_000;
	/**
	 * Kicked members are hidden at once, for this long: the party server may list them a little longer.
	 * Members who said bye stay hidden until the server drops them, which can take minutes.
	 */
	private static final long KICK_HIDE_MS = 120_000;
	/** After a logout you stay in the party this long, to pick another world on the login screen. */
	static final long LEAVE_AFTER_LOGOUT_MS = 10_000;
	/** A remembered raid party is kept over a client restart for this long (a long CoX raid). */
	private static final long REMEMBER_MS = 2 * 60 * 60_000;
	private static final String RAID_PARTY_KEY = "raidParty";
	private static final String LAST_PARTY_KEY = "lastParty";

	private final Client client;
	private final PartyService partyService;
	private final GoldenDpsConfig config;
	private final ChatNotifier chat;
	private final RaidPartyDetector raidPartyDetector;
	private final ConfigManager configManager;

	private final PartyLeader leader = new PartyLeader();
	private final RaidParty raidParty = new RaidParty();
	private final PartyNotices notices = new PartyNotices();
	private final Map<String, Long> reporters = new HashMap<>();
	/** Members who are gone but still listed by the party server, with the time to show them again. */
	private final Map<Long, Long> hidden = new HashMap<>();
	private final Set<String> instanceMates = new HashSet<>();
	private long localMemberId;
	/** Read by the logout timer, which runs off the client thread. */
	private volatile long loggedOutAtMs;
	/** You left or were kicked: no own party until the next login. */
	private boolean ownPartyStopped;
	/** A boss fight (or Barrows run) started: make your own party if you are in none. */
	private boolean ownPartyWanted;
	/** The party at the last tick, to see you leave your own party in RuneLite's Party panel. */
	private String lastParty;
	/** GoldenDPS changed the party since the last tick. */
	private volatile boolean changedByUs;
	private boolean rememberedLoaded;
	/** The last party you were in, for the Rejoin button. Kept over a client restart. */
	private String lastPartyName;
	private boolean lastPartyLoaded;
	private String rememberedSaved;

	@Inject
	PartyManager(Client client, PartyService partyService, GoldenDpsConfig config, ChatNotifier chat,
		RaidPartyDetector raidPartyDetector, ConfigManager configManager)
	{
		this.configManager = configManager;
		this.client = client;
		this.partyService = partyService;
		this.config = config;
		this.chat = chat;
		this.raidPartyDetector = raidPartyDetector;
	}

	/** You lead the party (as GoldenDPS sees it). */
	boolean isLeader()
	{
		return inParty() && leader.isLeader();
	}

	boolean inParty()
	{
		return partyService.isInParty() && partyService.getLocalMember() != null;
	}

	void join(String name)
	{
		if (partyService.isInParty())
		{
			return;
		}
		changeParty(name);
		chat.info("you joined party \"" + name + "\".");
	}

	/** A random name for a new party, or null when you are in a party already. */
	String randomName()
	{
		return partyService.isInParty() ? null : partyService.generatePassphrase().replace('-', ' ');
	}

	/** Join the last party you were in again. */
	void rejoin()
	{
		String name = lastParty();
		if (name != null)
		{
			join(name);
		}
	}

	/** The last party you were in, or null. Your own party is left out: nobody else is in it. */
	String lastParty()
	{
		if (!lastPartyLoaded)
		{
			lastPartyLoaded = true;
			lastPartyName = configManager.getConfiguration(GoldenDpsConfig.STATE_GROUP, LAST_PARTY_KEY);
		}
		return lastPartyName;
	}

	private void rememberLastParty()
	{
		String current = partyService.isInParty() ? partyService.getPartyPassphrase() : null;
		if (current == null || RaidParty.isOwn(current) || current.equals(lastParty()))
		{
			return;
		}
		lastPartyName = current;
		configManager.setConfiguration(GoldenDpsConfig.STATE_GROUP, LAST_PARTY_KEY, current);
	}

	void leave()
	{
		if (partyService.isInParty())
		{
			ownPartyStopped = true;
			changeParty(null);
			chat.info("you left the party.");
		}
	}

	void kick(long memberId, String name)
	{
		if (!leader.isLeader() || !partyService.isInParty())
		{
			chat.info("only the party leader can kick.");
			return;
		}
		partyService.send(new GoldenDpsPartyMessage(GoldenDpsPartyMessage.KICK, leader.getLeader(), memberId));
		hidden.put(memberId, System.currentTimeMillis() + KICK_HIDE_MS);
		notices.kicked(memberId);
		chat.kicked("you removed " + name + " from the party.");
	}

	private void changeParty(String passphrase)
	{
		// RuneLite just closes the connection, and the party server keeps listing you for minutes
		send(GoldenDpsPartyMessage.BYE);
		changedByUs = true;
		partyService.changeParty(passphrase);
		leader.left();
	}

	/** A GoldenDPS message arrived from this member. */
	void pluginSeen(long memberId)
	{
		leader.sawPlugin(memberId);
	}

	/** A GoldenDPS update arrived from this player. */
	void reporterSeen(String name, long now)
	{
		reporters.put(name, now);
	}

	boolean isReporter(String name, long now)
	{
		Long last = reporters.get(name);
		return last != null && now - last <= REPORTER_MS;
	}

	/** The member was seen in your instance since you entered it. */
	boolean isInstanceMate(String name)
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv != null && wv.isInstance() && instanceMates.contains(name);
	}

	void onMessage(GoldenDpsPartyMessage m)
	{
		PartyMember local = partyService.getLocalMember();
		if (m.type == null || local == null || m.getMemberId() == local.getMemberId())
		{
			return;
		}
		switch (m.type)
		{
			case GoldenDpsPartyMessage.HI:
				leader.announce(m.getMemberId(), m.leader);
				if (leader.isLeader())
				{
					send(GoldenDpsPartyMessage.LEADER);
				}
				break;
			case GoldenDpsPartyMessage.LEADER:
				leader.announce(m.getMemberId(), m.leader);
				break;
			case GoldenDpsPartyMessage.KICK:
				onKick(m);
				break;
			case GoldenDpsPartyMessage.BYE:
				hidden.put(m.getMemberId(), Long.MAX_VALUE);
				onMemberLeft(m.getMemberId());
				break;
			default:
				break;
		}
	}

	private void onKick(GoldenDpsPartyMessage m)
	{
		leader.sawPlugin(m.getMemberId());
		String by = memberName(m.getMemberId());
		String bySuffix = by != null ? " by " + by + "." : ".";
		if (leader.acceptKick(m.getMemberId(), m.target))
		{
			ownPartyStopped = true;
			changeParty(null);
			chat.kicked("you were removed from the party" + bySuffix);
		}
		else if (m.leader == m.getMemberId() && m.leader == leader.getLeader())
		{
			notices.kicked(m.target);
			String who = memberName(m.target);
			if (who != null)
			{
				chat.kicked(who + " was removed from the party" + bySuffix);
			}
		}
	}

	void onMemberLeft(long memberId)
	{
		leader.memberLeft(memberId, memberIds());
	}

	/**
	 * You logged out or hopped: tell again who is in the party after the next login.
	 * @param toLoginScreen a real logout (not a world hop): your own party may be made again
	 */
	void loggedOut(boolean toLoginScreen)
	{
		notices.reset();
		if (!toLoginScreen)
		{
			return;
		}
		ownPartyStopped = false;
		loggedOutAtMs = System.currentTimeMillis();
	}

	/**
	 * Some time after a logout: still logged out, so leave. RuneLite keeps you in the party while
	 * logged out, and the others would see you there for nothing. Runs on the timer thread: on the
	 * login screen the client thread does not reliably run queued work, and nothing else touches
	 * the party there.
	 */
	void leaveIfStillLoggedOut()
	{
		// a little slack: the timer may fire a moment early; a newer logout has its own timer
		GameState state = client.getGameState();
		long outMs = System.currentTimeMillis() - loggedOutAtMs;
		boolean stillOut = state == GameState.LOGIN_SCREEN && outMs >= LEAVE_AFTER_LOGOUT_MS - 500;
		log.debug("GoldenDPS logout check: state={}, out for {} ms, setting={}, in party={}", state, outMs,
			config.leaveOnLogout(), partyService.isInParty());
		if (stillOut && config.leaveOnLogout() && partyService.isInParty())
		{
			changeParty(null);
		}
	}

	/** Closing the client: tell the party server you are gone, instead of leaving a stale member behind. */
	void clientClosed()
	{
		if (config.leaveOnLogout() && partyService.isInParty())
		{
			changeParty(null);
		}
	}

	/** @param inRaid you are inside a raid */
	void tick(long now, boolean inRaid)
	{
		updateInstanceMates();
		watchOwnParty();
		rememberLastParty();
		updateRaidParty(inRaid);
		updateOwnParty();
		updateMembership(now);
	}

	private void updateMembership(long now)
	{
		List<Long> listed = new ArrayList<>();
		for (PartyMember m : partyService.getMembers())
		{
			listed.add(m.getMemberId());
		}
		hidden.entrySet().removeIf(e -> now > e.getValue() || !listed.contains(e.getKey()));

		PartyMember local = partyService.isInParty() ? partyService.getLocalMember() : null;
		if (local == null)
		{
			if (leader.isJoined())
			{
				leader.left();
			}
			localMemberId = 0;
			notices.reset();
			return;
		}
		if (local.getMemberId() != localMemberId)
		{
			// RuneLite gives you a new member id in every party
			localMemberId = local.getMemberId();
			leader.joined(localMemberId, now);
			send(GoldenDpsPartyMessage.HI);
		}
		if (leader.tick(now, memberIds()) && leader.isLeader())
		{
			send(GoldenDpsPartyMessage.LEADER);
		}

		Map<Long, String> named = new HashMap<>();
		for (PartyMember m : partyService.getMembers())
		{
			String n = Names.clean(m.getDisplayName());
			if (n != null && m.getMemberId() != localMemberId && !hidden.containsKey(m.getMemberId()))
			{
				named.put(m.getMemberId(), n);
			}
		}
		for (PartyNotices.Notice n : notices.tick(now, localMemberId, named))
		{
			if (n.joined)
			{
				chat.info(n.name + " joined the party.");
			}
			else
			{
				chat.left(n.name + " left the party.");
			}
		}
		List<String> others = notices.welcome(now);
		if (others != null)
		{
			chat.info(PartyNotices.welcomeText(partyService.getPartyPassphrase(), others));
		}
	}

	private void updateInstanceMates()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !wv.isInstance() || !partyService.isInParty())
		{
			instanceMates.clear();
			return;
		}
		Set<String> party = new HashSet<>();
		for (PartyMember m : partyService.getMembers())
		{
			String n = Names.clean(m.getDisplayName());
			if (n != null)
			{
				party.add(n);
			}
		}
		for (Player p : wv.players())
		{
			String n = p == null ? null : Names.clean(p.getName());
			if (n != null && party.contains(n))
			{
				instanceMates.add(n);
			}
		}
	}

	private void updateRaidParty(boolean inRaid)
	{
		if (!config.autoRaidParty())
		{
			return;
		}
		RaidPartyDetector.Detected raid = raidPartyDetector.current();
		String current = partyService.isInParty() ? partyService.getPartyPassphrase() : null;
		loadRememberedRaidParty();
		RaidParty.Action action = raidParty.tick(raid.partyName, current, inRaid);
		saveRememberedRaidParty();
		if (action.join != null)
		{
			changeParty(action.join);
			chat.info("you joined the " + raid.raid + " raid party automatically.");
		}
		else if (action.leave)
		{
			changeParty(null);
			chat.info("the raid is over: you left the raid party automatically.");
		}
	}

	/** After a client restart: the raid party you were in, if it is recent. */
	private void loadRememberedRaidParty()
	{
		if (rememberedLoaded)
		{
			return;
		}
		rememberedLoaded = true;
		String saved = configManager.getConfiguration(GoldenDpsConfig.STATE_GROUP, RAID_PARTY_KEY);
		int split = saved == null ? -1 : saved.lastIndexOf('|');
		if (split <= 0)
		{
			return;
		}
		try
		{
			long savedAt = Long.parseLong(saved.substring(split + 1));
			if (System.currentTimeMillis() - savedAt <= REMEMBER_MS)
			{
				raidParty.remember(saved.substring(0, split));
			}
		}
		catch (NumberFormatException ignored)
		{
			// an unreadable value is the same as none
		}
		rememberedSaved = raidParty.getRemembered();
	}

	private void saveRememberedRaidParty()
	{
		String name = raidParty.getRemembered();
		if (Objects.equals(name, rememberedSaved))
		{
			return;
		}
		rememberedSaved = name;
		if (name == null)
		{
			configManager.unsetConfiguration(GoldenDpsConfig.STATE_GROUP, RAID_PARTY_KEY);
		}
		else
		{
			configManager.setConfiguration(GoldenDpsConfig.STATE_GROUP, RAID_PARTY_KEY,
				name + "|" + System.currentTimeMillis());
		}
	}

	/** A party lost without GoldenDPS (RuneLite's Party panel, a dropped connection) stops own parties until logout. */
	private void watchOwnParty()
	{
		String current = partyService.isInParty() ? partyService.getPartyPassphrase() : null;
		boolean lostByOthers = lastParty != null && !lastParty.equals(current) && !changedByUs;
		// a party you lose (left in RuneLite's panel, or a dropped connection) must not be swapped
		// for an own party behind your back: you may want to join your friends again
		if (lostByOthers && (current == null || RaidParty.isOwn(lastParty)))
		{
			ownPartyStopped = true;
		}
		lastParty = current;
		changedByUs = false;
	}

	/** You hit a boss: the fight timer runs. */
	void bossHit()
	{
		ownPartyWanted = true;
	}

	/** Setting "Own party": when a boss fight starts and you are in no party, make one just for you. */
	private void updateOwnParty()
	{
		boolean wanted = ownPartyWanted;
		ownPartyWanted = false;
		if (!wanted || !config.ownParty() || ownPartyStopped || partyService.isInParty()
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		changeParty(RaidParty.OWN_PREFIX + partyService.generatePassphrase().replace('-', ' '));
		chat.info("you are in your own party now, so boss reports also work solo (setting: Own party).");
	}

	GoldenDpsPartyPanel.View view(String localName)
	{
		GoldenDpsPartyPanel.View v = new GoldenDpsPartyPanel.View();
		v.inParty = partyService.isInParty();
		v.lastParty = lastParty();
		if (!v.inParty)
		{
			return v;
		}
		v.code = partyService.getPartyPassphrase();
		v.youLead = leader.isLeader();
		v.autoLabel = RaidParty.isOwn(v.code) ? "Own party" : RaidParty.isAuto(v.code) ? "Raid party" : null;

		long now = System.currentTimeMillis();
		PartyMember local = partyService.getLocalMember();
		for (PartyMember m : partyService.getMembers())
		{
			if (hidden.containsKey(m.getMemberId()))
			{
				continue;
			}
			GoldenDpsPartyPanel.Member row = new GoldenDpsPartyPanel.Member();
			row.id = m.getMemberId();
			row.you = local != null && m.getMemberId() == local.getMemberId();
			String name = Names.clean(m.getDisplayName());
			// no name and logged out: a connection the party server has not dropped yet (a closed client)
			if (!row.you && name == null && !m.isLoggedIn())
			{
				continue;
			}
			row.name = name != null ? name : row.you ? localName : "(joining...)";
			row.online = m.isLoggedIn();
			row.leader = m.getMemberId() == leader.getLeader();
			row.hasPlugin = row.you || leader.hasPlugin(m.getMemberId()) || (name != null && isReporter(name, now));
			v.members.add(row);
		}
		v.members.sort((a, b) -> a.leader != b.leader ? (a.leader ? -1 : 1)
			: a.you != b.you ? (a.you ? -1 : 1) : a.name.compareToIgnoreCase(b.name));
		return v;
	}

	private String memberName(long memberId)
	{
		PartyMember m = partyService.getMemberById(memberId);
		return m == null ? null : Names.clean(m.getDisplayName());
	}

	private void send(String type)
	{
		if (inParty())
		{
			partyService.send(new GoldenDpsPartyMessage(type, leader.getLeader(), 0));
		}
	}

	private List<Long> memberIds()
	{
		List<Long> ids = new ArrayList<>();
		for (PartyMember m : partyService.getMembers())
		{
			if (!hidden.containsKey(m.getMemberId()))
			{
				ids.add(m.getMemberId());
			}
		}
		return ids;
	}
}

package com.goldendps;

import com.goldendps.model.AutoReports;
import com.goldendps.model.BossRecords;
import com.goldendps.model.Fight;
import com.goldendps.model.FightReport;
import com.goldendps.model.KillCounts;
import com.goldendps.model.MeterMode;
import com.goldendps.model.RaidPoints;
import com.goldendps.model.ReportFormatter;
import java.util.List;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.messages.PartyChatMessage;

/**
 * Sends the top players of a fight to the RuneLite party chat, by hand or (for the leader)
 * after every boss kill. Plugins may not write to the game chat, so the party chat is the only
 * way to share a report. Client thread only.
 */
class PartyReports
{
	/** Reports by hand at most this often, so the party chat cannot be spammed. */
	private static final long HAND_REPORT_MS = 10_000;

	private final GoldenDpsConfig config;
	private final PartyService partyService;
	private final PartyManager party;
	private final ChatNotifier chat;
	private final FightStorage storage;
	private final KillCounts killCounts;
	private final RaidPoints raidPoints;
	private final AutoReports autoReports = new AutoReports();
	private long lastHandReportMs;

	PartyReports(GoldenDpsConfig config, PartyService partyService, PartyManager party, ChatNotifier chat,
		FightStorage storage, KillCounts killCounts, RaidPoints raidPoints)
	{
		this.config = config;
		this.partyService = partyService;
		this.party = party;
		this.chat = chat;
		this.storage = storage;
		this.killCounts = killCounts;
		this.raidPoints = raidPoints;
	}

	void fightEnded(Fight fight, int tick)
	{
		if (config.autoBossReport())
		{
			autoReports.fightEnded(fight, tick);
		}
	}

	/** The leader reports boss kills and Barrows runs to the party by itself. */
	void sendDue(int tick)
	{
		for (Fight fight : autoReports.due(tick))
		{
			if (config.autoBossReport() && party.isLeader())
			{
				send(fight, ReportKind.BOSS, false, System.currentTimeMillis());
			}
		}
	}

	void clear()
	{
		autoReports.clear();
	}

	/** A report button or menu click. */
	void sendByHand(Fight fight, ReportKind kind, boolean session, long now)
	{
		long wait = lastHandReportMs + HAND_REPORT_MS - now;
		if (wait > 0)
		{
			chat.info("wait " + (wait + 999) / 1000 + "s before the next report.");
			return;
		}
		if (send(fight, kind, session, now))
		{
			lastHandReportMs = now;
		}
	}

	/**
	 * @param session the fight is the session total
	 * @return true when the report was sent
	 */
	private boolean send(Fight fight, ReportKind kind, boolean session, long now)
	{
		if (fight == null)
		{
			chat.info("nothing to report yet.");
			return false;
		}
		if (kind == ReportKind.BOSS && !fight.hasBossTarget())
		{
			chat.info("no boss in this fight.");
			return false;
		}
		if (!party.inParty())
		{
			chat.info("join a party to report to it.");
			return false;
		}
		for (String line : lines(fight, kind, session, now))
		{
			partyService.send(new PartyChatMessage(line));
		}
		return true;
	}

	private List<String> lines(Fight fight, ReportKind kind, boolean session, long now)
	{
		boolean bossOnly = kind == ReportKind.BOSS;
		// a finished raid or Barrows run is reported as a whole, with its full time:
		// "Chambers of Xeric complete: 31:30 - total 52,000 (27.5/s) - KC 21"
		boolean completed = bossOnly && fight.isCompleteRaid();
		FightReport report = FightReport.of(fight, bossOnly && !completed, now);
		String title = session ? "Session" : completed ? "" : report.getTitle();
		String label = completed ? fight.raid + (fight.run ? " run complete:" : " complete:") : kind.label;
		MeterMode mode = kind == ReportKind.HEALING ? MeterMode.HEALING : MeterMode.DAMAGE;
		List<String> lines = ReportFormatter.lines(report, mode, label, title, ReportFormatter.DEFAULT_TOP,
			kind == ReportKind.OVERALL);
		if (bossOnly && !session)
		{
			long endMs = fight.endMs > 0 ? fight.endMs : now;
			int kc = killCounts.near(completed ? fight.raid : report.getTitle(), endMs);
			String points = completed && !fight.run ? raidPoints.near(endMs) : null;
			String pb = BossRecords.meterTag(null, storage.compare(fight.id));
			lines.set(0, lines.get(0) + (kc > 0 ? " - KC " + kc : "") + (points != null ? " - " + points : "")
				+ (pb != null ? " - " + pb : ""));
		}
		return lines;
	}
}

package com.goldendps;

import com.goldendps.model.DefenceDrains;
import com.goldendps.model.Fight;
import com.goldendps.model.FightTracker;
import com.goldendps.model.HealType;
import com.goldendps.model.HealthWatcher;
import com.goldendps.model.PlayerKind;
import com.goldendps.model.TargetMatcher;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

/**
 * The {@link GoldenDpsUpdate} of every tick: collects what you did, sends it to the party, and
 * counts the updates that other members send. Client thread only.
 */
class PartyUpdates
{
	/** Other clients send the source as free text; anything this long is not a weapon or spell name. */
	private static final int MAX_SOURCE_LENGTH = 64;

	private final Client client;
	private final PartyService partyService;
	private final PartyManager party;
	private final GoldenDpsConfig config;
	private final FightTracker tracker;
	private final Bosses bosses;
	private final TargetMatcher matcher;
	private final DefenceDrains defence;

	private GoldenDpsUpdate outgoing = new GoldenDpsUpdate();

	PartyUpdates(Client client, PartyService partyService, PartyManager party, GoldenDpsConfig config,
		FightTracker tracker, Bosses bosses, TargetMatcher matcher, DefenceDrains defence)
	{
		this.client = client;
		this.partyService = partyService;
		this.party = party;
		this.config = config;
		this.tracker = tracker;
		this.bosses = bosses;
		this.matcher = matcher;
		this.defence = defence;
	}

	void addHit(GoldenDpsUpdate.Hit hit)
	{
		outgoing.hits.add(hit);
	}

	void addDamageTaken(int amount)
	{
		outgoing.taken += amount;
	}

	void addHeal(HealthWatcher.Heal heal)
	{
		switch (heal.type)
		{
			case FOOD:
				outgoing.food += heal.amount;
				outgoing.foodOverheal += heal.overheal;
				break;
			case LIFESTEAL:
				outgoing.lifesteal += heal.amount;
				outgoing.lifestealOverheal += heal.overheal;
				break;
			case REGEN:
				// not counted any more, still sent for older GoldenDPS versions
				outgoing.regen += heal.amount;
				break;
			case HEAL_OTHER:
				outgoing.healOther += heal.amount;
				break;
			default:
				break;
		}
	}

	/** Forgets what was collected but not sent yet. */
	void clear()
	{
		outgoing = new GoldenDpsUpdate();
	}

	/** Sends this tick's update (when there is something to share) and starts the next one. */
	void send()
	{
		GoldenDpsUpdate update = outgoing;
		outgoing = new GoldenDpsUpdate();
		if (update.isEmpty() || !config.shareWithParty() || !party.inParty())
		{
			return;
		}
		update.world = client.getWorld();
		update.name = Names.localName(client);
		partyService.send(update);
	}

	/** Adds a party member's update to the fight. */
	void receive(GoldenDpsUpdate update)
	{
		PartyMember local = partyService.getLocalMember();
		if (local != null && update.getMemberId() == local.getMemberId())
		{
			return;
		}
		party.pluginSeen(update.getMemberId());
		String name = senderName(update);
		if (name == null || name.equals(Names.localName(client)))
		{
			return;
		}

		long now = System.currentTimeMillis();
		party.reporterSeen(name, now);
		boolean together = !config.othersOnlyTogether() || party.isInstanceMate(name);
		boolean counted = together;
		if (update.hits != null)
		{
			for (GoldenDpsUpdate.Hit hit : update.hits)
			{
				// party members on an older GoldenDPS send the name with its color tags
				String npcName = Names.clean(hit.npcName);
				boolean boss = hit.boss || bosses.isBoss(hit.npcId, npcName);
				// away from you, only hits on a boss you can see count
				if (!together && !(boss && npcInScene(update.world, hit) != null))
				{
					continue;
				}
				counted = true;
				String source = hit.source == null || hit.source.length() > MAX_SOURCE_LENGTH ? null : hit.source;
				String targetKey = partyTargetKey(update.world, hit, name);
				tracker.playerHit(now, name, PlayerKind.PARTY, targetKey, hit.npcId, npcName, boss, hit.amount, hit.miss,
					source);
				if (!tracker.isInRaid())
				{
					defence.hit(client.getTickCount(), targetKey, hit.npcId, npcName, name, source, hit.amount, hit.miss);
				}
			}
		}
		Fight current = tracker.getCurrent();
		if (!counted && (current == null || !current.players.containsKey(name)))
		{
			return;
		}
		tracker.damageTaken(now, name, PlayerKind.PARTY, update.taken);
		tracker.heal(now, name, PlayerKind.PARTY, HealType.FOOD, update.food, update.foodOverheal);
		tracker.heal(now, name, PlayerKind.PARTY, HealType.LIFESTEAL, update.lifesteal, update.lifestealOverheal);
		tracker.heal(now, name, PlayerKind.PARTY, HealType.HEAL_OTHER, update.healOther);
	}

	/** The name in the update, or the member's party display name when the update has none. */
	private String senderName(GoldenDpsUpdate update)
	{
		String name = Names.clean(update.name);
		if (name != null)
		{
			return name;
		}
		PartyMember member = partyService.getMemberById(update.getMemberId());
		return member == null ? null : Names.clean(member.getDisplayName());
	}

	/** The NPC in your scene that a party member hit, or null when you cannot see it. */
	private NPC npcInScene(int world, GoldenDpsUpdate.Hit hit)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (world != client.getWorld() || wv == null)
		{
			return null;
		}
		NPC npc = wv.npcs().byIndex(hit.npcIndex);
		return npc != null && npc.getId() == hit.npcId ? npc : null;
	}

	/** Your key for the NPC when it is the same one you see, otherwise a key of its own. */
	private String partyTargetKey(int world, GoldenDpsUpdate.Hit hit, String sender)
	{
		NPC npc = npcInScene(world, hit);
		WorldPoint pos = npc == null ? null : npc.getWorldLocation();
		if (pos != null)
		{
			matcher.seen(TargetMatcher.key(world, hit.npcIndex), pos.getX(), pos.getY(), pos.getPlane());
		}
		return matcher.partyKey(client.getWorld(), world, hit.npcIndex, hit.x, hit.y, hit.plane, sender);
	}
}

package com.goldendps;

import com.goldendps.model.FightTracker;
import com.goldendps.model.RaidZone;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/** One fight per raid: starts when you enter the raid instance and ends when you leave it. Client thread only. */
class RaidFights
{
	private static final String RAID_BEGAN = "The raid has begun!";

	private final Client client;
	private final ChatNotifier chat;
	private final FightTracker tracker;
	private final RaidZone raidZone = new RaidZone();

	RaidFights(Client client, ChatNotifier chat, FightTracker tracker)
	{
		this.client = client;
		this.chat = chat;
		this.tracker = tracker;
	}

	void tick(long now)
	{
		RaidZone.Change change = raidZone.tick(currentRaid());
		if (change.start != null)
		{
			tracker.startRaid(now, change.start);
			chat.info(change.start + " started. The meter counts the whole raid until you leave.");
		}
		else if (change.end)
		{
			tracker.endRaid(now, "Left the raid");
		}
	}

	/** CoX starts its timer with this message; ToB and ToA start theirs at the first room. */
	void gameMessage(long now, String message)
	{
		if (message.startsWith(RAID_BEGAN))
		{
			tracker.raidBegan(now);
		}
	}

	boolean isInsideRaid()
	{
		return raidZone.getInside() != null;
	}

	void reset()
	{
		raidZone.reset();
	}

	/** The raid whose instance you stand in, or null. */
	private String currentRaid()
	{
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (me == null || me.getLocalLocation() == null || wv == null)
		{
			return null;
		}
		WorldPoint pos = WorldPoint.fromLocalInstance(client, me.getLocalLocation());
		return pos == null ? null : RaidZone.raidFor(pos.getRegionID(), wv.isInstance());
	}
}

package com.goldendps;

import com.goldendps.model.RaidParty;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads the raid party you are in from the game and turns it into a shared party name. */
class RaidPartyDetector
{
	/** The raid party you are in. */
	static final class Detected
	{
		final String raid;
		/** Null while the party name cannot be made yet (for example when you are alone). */
		final String partyName;

		Detected(String raid, String partyName)
		{
			this.raid = raid;
			this.partyName = partyName;
		}
	}

	/** A raid whose members all see the member names. */
	private static final class NamedRaid
	{
		final String name;
		final int statusVarbit;
		final int firstNameVarc;
		final int lastNameVarc;

		NamedRaid(String name, int statusVarbit, int firstNameVarc, int lastNameVarc)
		{
			this.name = name;
			this.statusVarbit = statusVarbit;
			this.firstNameVarc = firstNameVarc;
			this.lastNameVarc = lastNameVarc;
		}
	}

	private static final NamedRaid[] NAMED_RAIDS = {
		new NamedRaid("ToB", VarbitID.TOB_CLIENT_PARTYSTATUS, VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME4),
		new NamedRaid("ToA", VarbitID.TOA_CLIENT_PARTYSTATUS, VarClientID.TOA_CLIENT_NAME0, VarClientID.TOA_CLIENT_NAME7),
		new NamedRaid("Archive", VarbitID.TFA_CLIENT_PARTYSTATUS, VarClientID.TFA_CLIENT_NAME0, VarClientID.TFA_CLIENT_NAME7),
	};

	private final Client client;

	@Inject
	RaidPartyDetector(Client client)
	{
		this.client = client;
	}

	/** Client thread only. */
	Detected current()
	{
		for (NamedRaid r : NAMED_RAIDS)
		{
			if (client.getVarbitValue(r.statusVarbit) > 0)
			{
				List<String> names = new ArrayList<>();
				for (int v = r.firstNameVarc; v <= r.lastNameVarc; v++)
				{
					names.add(client.getVarcStrValue(v));
				}
				return new Detected(r.name, RaidParty.partyName(r.name, client.getWorld(), names));
			}
		}
		// CoX has no member list, but every member gets the same raid party id
		return new Detected("CoX", RaidParty.coxPartyName(client.getWorld(),
			client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER), client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE)));
	}
}

