package com.goldendps.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.StringJoiner;

/**
 * The defence (and magic level) of monsters after special attacks that lower it (yours and your party's),
 * with the rules of the OSRS Wiki. Drained stats come back 1 level a minute. Not yet: raids, Tekton's misses,
 * and monsters that restore faster or limit drains.
 */
public class DefenceDrains
{
	/** One special attack that lowered the defence. */
	public static final class Drain
	{
		public final String player;
		public final String weapon;
		public final int amount;
		/** It lowered the Magic level (Seercull, Accursed sceptre), not the Defence. */
		public final boolean magic;

		Drain(String player, String weapon, int amount, boolean magic)
		{
			this.player = player;
			this.weapon = weapon;
			this.amount = amount;
			this.magic = magic;
		}
	}

	/** The defence and magic level of one monster. */
	public static final class Target
	{
		public final String name;
		public final int base;
		public final int magicBase;
		private final boolean demon;
		private int current;
		private int magicCurrent;
		/** The tick the next level comes back is counted from; -1 while the stat is not lowered. */
		private int restoreTick = -1;
		private int magicRestoreTick = -1;
		private final List<Drain> drains = new ArrayList<>();

		Target(NpcStats.Npc npc)
		{
			name = npc.name;
			base = npc.defence;
			magicBase = npc.magicLevel;
			demon = npc.is("demon");
			current = npc.defence;
			magicCurrent = npc.magicLevel;
		}

		public int getCurrent()
		{
			return current;
		}

		/** The magic level blocks spells, so a lower one helps your magic hit chance. */
		public int getMagicCurrent()
		{
			return magicCurrent;
		}

		public List<Drain> getDrains()
		{
			return Collections.unmodifiableList(drains);
		}

		/** "DWH x2 -126, BGS -34, Seercull -30 magic": the drains per weapon, in the order they first hit. */
		public String summary()
		{
			Map<String, int[]> perWeapon = new LinkedHashMap<>();
			for (Drain d : drains)
			{
				String weapon = shortName(d.weapon) + (d.magic ? MAGIC : "");
				int[] countAndTotal = perWeapon.computeIfAbsent(weapon, k -> new int[2]);
				countAndTotal[0]++;
				countAndTotal[1] += d.amount;
			}
			StringJoiner out = new StringJoiner(", ");
			perWeapon.forEach((weapon, countAndTotal) ->
			{
				boolean magic = weapon.endsWith(MAGIC);
				String name = magic ? weapon.substring(0, weapon.length() - MAGIC.length()) : weapon;
				out.add(name + (countAndTotal[0] > 1 ? " x" + countAndTotal[0] : "") + " -" + countAndTotal[1]
					+ (magic ? " magic" : ""));
			});
			return out.toString();
		}
	}

	private static final String SPEC = " (spec)";
	private static final String MAGIC = "|magic";
	/** One minute. */
	static final int RESTORE_TICKS = 100;

	private final NpcStats stats;
	private final Map<String, Target> byKey = new HashMap<>();

	public DefenceDrains(NpcStats stats)
	{
		this.stats = stats;
	}

	/**
	 * A hit by you or a party member.
	 * @param source weapon or spell, "Dragon warhammer (spec)" for a spec
	 */
	public void hit(int tick, String targetKey, int npcId, String npcName, String player, String source, int damage,
		boolean miss)
	{
		if (source == null || !source.endsWith(SPEC))
		{
			return;
		}
		Target t = byKey.get(targetKey);
		if (t == null)
		{
			NpcStats.Npc npc = stats.get(npcId, npcName);
			if (npc == null)
			{
				return;
			}
			t = new Target(npc);
		}
		String weapon = source.substring(0, source.length() - SPEC.length());
		int drain = Math.min(t.current, drain(weapon, t, miss ? 0 : damage, miss));
		int magicDrain = Math.min(t.magicCurrent, magicDrain(weapon, t, miss ? 0 : damage));
		if (drain > 0)
		{
			t.current -= drain;
			t.restoreTick = t.restoreTick < 0 ? tick : t.restoreTick;
			t.drains.add(new Drain(player, weapon, drain, false));
		}
		if (magicDrain > 0)
		{
			t.magicCurrent -= magicDrain;
			t.magicRestoreTick = t.magicRestoreTick < 0 ? tick : t.magicRestoreTick;
			t.drains.add(new Drain(player, weapon, magicDrain, true));
		}
		if (!t.drains.isEmpty())
		{
			byKey.put(targetKey, t);
		}
	}

	/** How much Magic level this special attack takes away. */
	static int magicDrain(String weapon, Target t, int damage)
	{
		String w = weapon.toLowerCase(Locale.ROOT);
		if (w.startsWith("seercull"))
		{
			// only when the magic level is not lowered yet
			return t.magicCurrent >= t.magicBase ? damage : 0;
		}
		if (w.startsWith("accursed sceptre") && damage > 0)
		{
			// does not stack: at most 15% below the base in total
			return t.magicCurrent - (t.magicBase - t.magicBase * 15 / 100);
		}
		return 0;
	}

	/** How much defence this special attack takes away. */
	static int drain(String weapon, Target t, int damage, boolean miss)
	{
		String w = weapon.toLowerCase(Locale.ROOT);
		if (w.startsWith("bandos godsword"))
		{
			return damage;
		}
		if (miss)
		{
			return 0;
		}
		if (w.startsWith("dragon warhammer"))
		{
			return t.current * 30 / 100;
		}
		if (w.startsWith("elder maul"))
		{
			return t.current * 35 / 100;
		}
		if (w.startsWith("arclight"))
		{
			return t.base * (t.demon ? 10 : 5) / 100 + 1;
		}
		if (w.startsWith("emberlight"))
		{
			return t.base * (t.demon ? 15 : 5) / 100 + 1;
		}
		if (w.startsWith("accursed sceptre"))
		{
			// does not stack: at most 15% below the base in total
			return t.current - (t.base - t.base * 15 / 100);
		}
		if (w.startsWith("bone dagger") || w.startsWith("dorgeshuun crossbow"))
		{
			// only when the defence is not lowered yet
			return t.current >= t.base ? damage : 0;
		}
		if (w.startsWith("barrelchest anchor"))
		{
			// 10% of the damage; the wiki does not say how it rounds
			return damage / 10;
		}
		return 0;
	}

	/** "DWH" and "BGS", the names players use; other weapons keep their own name. */
	public static String shortName(String weapon)
	{
		String w = weapon.toLowerCase(Locale.ROOT);
		if (w.startsWith("dragon warhammer"))
		{
			return "DWH";
		}
		if (w.startsWith("bandos godsword"))
		{
			return "BGS";
		}
		return weapon;
	}

	/** The lowered defence of this NPC, or null when no special attack lowered it. */
	public Target get(String targetKey)
	{
		return byKey.get(targetKey);
	}

	/**
	 * Every minute (100 ticks) a drained stat comes back 1 level; a monster with all stats back is forgotten.
	 * Call each game tick.
	 */
	public void restore(int tick)
	{
		for (Iterator<Target> it = byKey.values().iterator(); it.hasNext(); )
		{
			Target t = it.next();
			while (t.restoreTick >= 0 && tick - t.restoreTick >= RESTORE_TICKS)
			{
				t.current++;
				t.restoreTick = t.current < t.base ? t.restoreTick + RESTORE_TICKS : -1;
			}
			while (t.magicRestoreTick >= 0 && tick - t.magicRestoreTick >= RESTORE_TICKS)
			{
				t.magicCurrent++;
				t.magicRestoreTick = t.magicCurrent < t.magicBase ? t.magicRestoreTick + RESTORE_TICKS : -1;
			}
			if (t.current >= t.base && t.magicCurrent >= t.magicBase)
			{
				it.remove();
			}
		}
	}

	/** The NPC died or is gone. */
	public void remove(String targetKey)
	{
		byKey.remove(targetKey);
	}

	public void clear()
	{
		byKey.clear();
	}

	/** Every NPC with lowered defence, by target key. */
	public Map<String, Target> all()
	{
		return Collections.unmodifiableMap(byKey);
	}
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One fight, or a merged total of several fights. Plain fields for Gson. */
public class Fight
{
	/** One game tick. The game counts its timers in ticks. */
	public static final long TICK_MS = 600;
	/** Shortest duration used for DPS: one game tick. */
	public static final long MIN_DURATION_MS = TICK_MS;

	public String id;
	public String sessionId;
	public long startMs;
	public long lastActivityMs;
	/** 0 while the fight is still going. */
	public long endMs;
	public String endReason;
	/** Only used for merged totals: sum of the fight times. */
	public long mergedDurationMs;
	public int mergedFights;
	/** Only used for merged totals: sum of the boss times. */
	public long mergedBossMs;
	/** Gaps without hits longer than this are not counted (active time). 0 disables it. */
	public long pauseAfterMs;
	/** Uncounted gaps as [from, to]. */
	public List<long[]> pauses = new ArrayList<>();
	/** Raid name for a raid fight and its boss fights. */
	public String raid;
	/** For a boss fight inside a raid: the id of the raid fight. */
	public String partOf;
	/**
	 * A finished run made of other fights (a Barrows run, from the first brother to the chest).
	 * Its kills are already counted in those fights.
	 */
	public boolean run;
	/**
	 * The time the game printed in the chat ("Fight duration: 0:54.60"), 0 = none. For a whole raid it
	 * is the raid time, else the boss time. It wins over our own clock.
	 */
	public long gameTimeMs;

	public Map<String, PlayerStats> players = new LinkedHashMap<>();
	public Map<String, TargetStats> targets = new LinkedHashMap<>();

	public Fight()
	{
	}

	public Fight(String id, String sessionId, long startMs)
	{
		this.id = id;
		this.sessionId = sessionId;
		this.startMs = startMs;
		this.lastActivityMs = startMs;
	}

	/** A whole raid in which every boss died, or a finished run. */
	public boolean isCompleteRaid()
	{
		return isWholeRaid() && endMs > 0 && (run || bossDiedMs() > 0);
	}

	public boolean isActive()
	{
		return endMs == 0 && mergedFights == 0;
	}

	public void activity(long nowMs)
	{
		addPause(nowMs);
		lastActivityMs = Math.max(lastActivityMs, nowMs);
	}

	private void addPause(long nowMs)
	{
		if (pauseAfterMs <= 0)
		{
			return;
		}
		long from = lastActivityMs + pauseAfterMs;
		if (nowMs > from)
		{
			if (pauses == null)
			{
				pauses = new ArrayList<>();
			}
			pauses.add(new long[]{from, nowMs});
		}
	}

	public void finish(long endAtMs, String reason)
	{
		endMs = Math.max(endAtMs, startMs);
		addPause(endMs);
		endReason = reason;
	}

	/** The fight is running but the clock is stopped (no hits for the pause time). */
	public boolean isPaused(long nowMs)
	{
		return isActive() && pauseAfterMs > 0 && nowMs > lastActivityMs + pauseAfterMs;
	}

	private long clockNow(long nowMs)
	{
		return isPaused(nowMs) ? lastActivityMs + pauseAfterMs : nowMs;
	}

	long activeBetween(long startMs, long endMs)
	{
		if (endMs <= startMs)
		{
			return 0;
		}
		long active = endMs - startMs;
		if (pauses != null)
		{
			for (long[] pause : pauses)
			{
				long from = Math.max(startMs, pause[0]);
				long to = Math.min(endMs, pause[1]);
				if (to > from)
				{
					active -= to - from;
				}
			}
		}
		return active;
	}

	/** A time rounded to whole game ticks, like the game's own timers. */
	public static long wholeTicks(long ms)
	{
		return Math.round(ms / (double) TICK_MS) * TICK_MS;
	}

	/** The fight of a whole raid (not one of its boss fights). */
	public boolean isWholeRaid()
	{
		return raid != null && partOf == null;
	}

	public long durationMs(long nowMs)
	{
		long d;
		if (mergedFights > 0)
		{
			d = mergedDurationMs;
		}
		else if (gameTimeMs > 0 && isWholeRaid())
		{
			d = gameTimeMs;
		}
		else if (endMs > 0)
		{
			d = activeBetween(startMs, endMs);
		}
		else
		{
			d = activeBetween(startMs, clockNow(nowMs));
		}
		return Math.max(MIN_DURATION_MS, wholeTicks(d));
	}

	/** Active time from the first boss hit to the last boss death (or now). 0 without bosses. */
	public long bossDurationMs(long nowMs)
	{
		if (mergedFights > 0)
		{
			return mergedBossMs;
		}
		if (gameTimeMs > 0 && !isWholeRaid())
		{
			return gameTimeMs;
		}
		long start = 0;
		long end = 0;
		boolean alive = false;
		for (TargetStats t : targets.values())
		{
			if (!t.boss || !t.engaged || t.firstMs <= 0)
			{
				continue;
			}
			start = start == 0 ? t.firstMs : Math.min(start, t.firstMs);
			if (t.died && t.diedMs > 0)
			{
				end = Math.max(end, t.diedMs);
			}
			else
			{
				alive = true;
				end = Math.max(end, t.lastMs);
			}
		}
		if (start == 0)
		{
			return 0;
		}
		if (alive && isActive())
		{
			end = Math.max(end, clockNow(nowMs));
		}
		return Math.max(MIN_DURATION_MS, wholeTicks(activeBetween(start, end)));
	}

	/** Time of the last boss death once every engaged boss is dead, else 0. */
	public long bossDiedMs()
	{
		long died = 0;
		for (TargetStats t : targets.values())
		{
			if (t.boss && t.engaged)
			{
				if (!t.died || t.diedMs <= 0)
				{
					return 0;
				}
				died = Math.max(died, t.diedMs);
			}
		}
		return died;
	}

	/** A single fight with a boss; its boss meter stays until the next boss fight replaces it. */
	public boolean hasBossMeter()
	{
		return mergedFights == 0 && !run && hasBossTarget();
	}

	public PlayerStats player(String name, PlayerKind kind)
	{
		PlayerStats p = players.computeIfAbsent(name, n -> new PlayerStats(n, kind));
		if (kind == PlayerKind.LOCAL)
		{
			p.kind = PlayerKind.LOCAL;
		}
		else if (kind == PlayerKind.PARTY && p.kind == PlayerKind.ESTIMATE)
		{
			p.kind = PlayerKind.PARTY;
		}
		return p;
	}

	public TargetStats target(String key, int npcId, String name, boolean boss)
	{
		TargetStats t = targets.computeIfAbsent(key, k -> new TargetStats(k, npcId, name, boss));
		// phase changes alter the id and name; keep the latest
		if (name != null && !name.isEmpty())
		{
			t.name = name;
		}
		t.npcId = npcId;
		t.boss |= boss;
		return t;
	}

	public boolean hasBossTarget()
	{
		for (TargetStats t : targets.values())
		{
			if (t.boss && t.engaged)
			{
				return true;
			}
		}
		return false;
	}

	/** Damage reported by players (excludes unknown and effect damage). */
	public long knownDamage()
	{
		long sum = 0;
		for (PlayerStats p : players.values())
		{
			for (TargetDamage d : p.byTarget.values())
			{
				sum += d.damage;
			}
		}
		return sum;
	}

	public String title()
	{
		return title(false);
	}

	/** The raid, or the boss or target that took the most damage. */
	/** "Great Olm (Left claw)" is part of "Great Olm": one boss, one record. */
	static String bossName(String npcName)
	{
		int part = npcName.indexOf(" (");
		String name = part > 0 ? npcName.substring(0, part) : npcName;
		// in the Vespula room the portal is what you kill; its own name says nothing about the room
		return name.equals("Abyssal portal") ? "Vespula portal" : name;
	}

	public String title(boolean bossOnly)
	{
		if (isWholeRaid() && !bossOnly)
		{
			return raid;
		}
		Map<String, Long> byName = new HashMap<>();
		Map<String, Boolean> bossByName = new HashMap<>();
		for (PlayerStats p : players.values())
		{
			for (Map.Entry<String, TargetDamage> e : p.damageByTarget().entrySet())
			{
				TargetStats t = targets.get(e.getKey());
				if (bossOnly && (t == null || !t.boss))
				{
					continue;
				}
				String n = t == null || t.name == null ? "Unknown" : t.boss ? bossName(t.name) : t.name;
				byName.merge(n, e.getValue().damage, Long::sum);
				if (t != null && t.boss)
				{
					bossByName.put(n, true);
				}
			}
		}
		String best = null;
		long bestDmg = -1;
		boolean bestBoss = false;
		for (Map.Entry<String, Long> e : byName.entrySet())
		{
			boolean boss = bossByName.containsKey(e.getKey());
			if ((boss && !bestBoss) || (boss == bestBoss && e.getValue() > bestDmg))
			{
				best = e.getKey();
				bestDmg = e.getValue();
				bestBoss = boss;
			}
		}
		if (best == null)
		{
			return "Fight";
		}
		// a boss names the fight on its own; "+2" only helps for fights against normal monsters
		return byName.size() > 1 && !bestBoss ? best + " +" + (byName.size() - 1) : best;
	}

	public void merge(Fight o, long nowMs)
	{
		mergedDurationMs += o.durationMs(nowMs);
		mergedBossMs += o.bossDurationMs(nowMs);
		mergedFights += o.mergedFights > 0 ? o.mergedFights : 1;
		if (startMs == 0 || (o.startMs > 0 && o.startMs < startMs))
		{
			startMs = o.startMs;
		}
		lastActivityMs = Math.max(lastActivityMs, o.lastActivityMs);
		// NPC indexes are reused across fights, so merged keys include the NPC name.
		Map<String, String> keyMap = new HashMap<>();
		for (TargetStats t : o.targets.values())
		{
			String newKey = o.mergedFights > 0 ? t.key : t.key + "|" + t.name;
			keyMap.put(t.key, newKey);
			TargetStats mine = targets.get(newKey);
			if (mine == null)
			{
				TargetStats c = t.copy();
				c.key = newKey;
				targets.put(newKey, c);
			}
			else
			{
				mine.merge(t);
			}
		}
		for (PlayerStats p : o.players.values())
		{
			players.computeIfAbsent(p.name, n -> new PlayerStats(n, p.kind))
				.merge(p, k -> keyMap.getOrDefault(k, k));
		}
	}

	public Fight copy()
	{
		Fight c = new Fight(id, sessionId, startMs);
		c.lastActivityMs = lastActivityMs;
		c.endMs = endMs;
		c.endReason = endReason;
		c.mergedDurationMs = mergedDurationMs;
		c.mergedFights = mergedFights;
		c.mergedBossMs = mergedBossMs;
		c.pauseAfterMs = pauseAfterMs;
		c.raid = raid;
		c.partOf = partOf;
		c.run = run;
		c.gameTimeMs = gameTimeMs;
		if (pauses != null)
		{
			for (long[] p : pauses)
			{
				c.pauses.add(new long[]{p[0], p[1]});
			}
		}
		for (PlayerStats p : players.values())
		{
			c.players.put(p.name, p.copy());
		}
		for (TargetStats t : targets.values())
		{
			c.targets.put(t.key, t.copy());
		}
		return c;
	}
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToLongFunction;

/**
 * Numbers for the overlay and the panel, worked out from one {@link Fight}.
 * Pure Java, so it is easy to unit test.
 */
public class FightReport
{
	public static final String UNKNOWN_NAME = "Others (unknown)";
	public static final String EFFECTS_NAME = "Poison / venom / burn";

	public static class PlayerRow
	{
		public String name;
		public PlayerKind kind;
		public long damage;
		public int hits;
		public int misses;
		public int biggestHit;
		public double dps;
		/** Share of the group damage, 0..100. */
		public double percent;
		public long healing;
		public long healFood;
		public long healLifesteal;
		public long healOther;
		/** Wasted food and potion healing. */
		public long overheal;
		public long damageTaken;
		/** Damage per weapon / spell, biggest first. Empty when not known. */
		public List<SourceRow> sources = new ArrayList<>();

		/** Share of this player's healing that was wasted, 0..100 (0 when nothing was healed). */
		public double overhealPercent()
		{
			return FightReport.overhealPercent(healing, overheal);
		}

		/** A real player row (you, party, or a guessed player). */
		public boolean isPlayer()
		{
			return kind == PlayerKind.LOCAL || kind == PlayerKind.PARTY || kind == PlayerKind.ESTIMATE;
		}

		/** Numbers are a guess (player without GoldenDPS). */
		public boolean isEstimate()
		{
			return kind == PlayerKind.ESTIMATE;
		}
	}

	/** One line of the breakdown: damage with one weapon or spell. */
	public static class SourceRow
	{
		public String name;
		public long damage;
		public int hits;
		public int misses;
		public int biggestHit;
		/** Share of this player's damage, 0..100. */
		public double percent;

		/** Average damage per attack (hits and misses). */
		public double average()
		{
			int attacks = hits + misses;
			return attacks == 0 ? 0 : (double) damage / attacks;
		}
	}

	public static class TargetRow
	{
		public String name;
		public boolean boss;
		public boolean died;
		public long total;
		/** Player name (or UNKNOWN_NAME / EFFECTS_NAME) to damage, biggest first. */
		public Map<String, Long> byPlayer = new LinkedHashMap<>();
		/** Hits and misses per player; guessed players are left out. */
		public Map<String, TargetDamage> attacksByPlayer = new LinkedHashMap<>();
	}

	private final List<PlayerRow> rows = new ArrayList<>();
	private final List<TargetRow> targets = new ArrayList<>();
	private long totalDamage;
	/** Targets fought that died. */
	private int kills;
	private long durationMs;
	private String title;

	public static FightReport of(Fight fight, boolean bossOnly, long nowMs)
	{
		FightReport r = new FightReport();
		r.durationMs = fight.durationMs(nowMs);
		if (bossOnly)
		{
			// boss DPS: only the time spent on bosses, not the trash before
			long boss = fight.bossDurationMs(nowMs);
			if (boss > 0)
			{
				r.durationMs = boss;
			}
		}
		r.title = fight.title(bossOnly && fight.hasBossTarget());
		for (TargetStats t : fight.targets.values())
		{
			if (t.engaged && (!bossOnly || t.boss))
			{
				r.kills += t.killCount();
			}
		}

		// damage by target that GoldenDPS knows the player of
		Map<String, Long> knownByTarget = new LinkedHashMap<>();
		for (PlayerStats p : fight.players.values())
		{
			r.rows.add(playerRow(fight, p, bossOnly, knownByTarget));
		}
		r.addUnaccountedRows(fight, bossOnly, knownByTarget);

		for (PlayerRow row : r.rows)
		{
			r.totalDamage += row.damage;
		}
		double seconds = r.durationMs / 1000.0;
		for (PlayerRow row : r.rows)
		{
			row.dps = row.damage / seconds;
			row.percent = r.totalDamage == 0 ? 0 : 100.0 * row.damage / r.totalDamage;
		}

		r.buildTargets(fight, bossOnly);
		return r;
	}

	/** @param knownByTarget gets the player's counted damage added */
	private static PlayerRow playerRow(Fight fight, PlayerStats p, boolean bossOnly,
		Map<String, Long> knownByTarget)
	{
		PlayerRow row = new PlayerRow();
		row.name = p.name;
		row.kind = p.kind;
		for (Map.Entry<String, TargetDamage> e : p.damageByTarget().entrySet())
		{
			if (!countsHit(fight, p, e.getKey(), bossOnly))
			{
				continue;
			}
			TargetDamage d = e.getValue();
			row.damage += d.damage;
			row.hits += d.hits;
			row.misses += d.misses;
			row.biggestHit = Math.max(row.biggestHit, d.biggestHit);
			knownByTarget.merge(e.getKey(), d.damage, Long::sum);
		}
		if (p.kind != PlayerKind.ESTIMATE)
		{
			row.sources = sourceRows(fight, p, bossOnly, row.damage);
		}
		row.healFood = p.healFood;
		row.healLifesteal = p.healLifesteal;
		row.healOther = p.healOther;
		row.healing = p.healing();
		row.overheal = p.overheal();
		row.damageTaken = p.takenTotal();
		return row;
	}

	/** The player's damage per weapon or spell, biggest first. */
	private static List<SourceRow> sourceRows(Fight fight, PlayerStats p, boolean bossOnly, long playerDamage)
	{
		Map<String, TargetDamage> bySource = new LinkedHashMap<>();
		for (Map.Entry<String, Map<String, TargetDamage>> source : p.sources().entrySet())
		{
			for (Map.Entry<String, TargetDamage> e : source.getValue().entrySet())
			{
				if (countsHit(fight, p, e.getKey(), bossOnly))
				{
					bySource.computeIfAbsent(source.getKey(), k -> new TargetDamage()).merge(e.getValue());
				}
			}
		}
		return sourceRows(bySource, playerDamage);
	}

	/** Damage per weapon or spell, biggest first; {@code totalDamage} is 100%. */
	public static List<SourceRow> sourceRows(Map<String, TargetDamage> bySource, long totalDamage)
	{
		List<SourceRow> out = new ArrayList<>();
		for (Map.Entry<String, TargetDamage> e : bySource.entrySet())
		{
			TargetDamage d = e.getValue();
			if (d.hits + d.misses == 0)
			{
				continue;
			}
			SourceRow row = new SourceRow();
			row.name = e.getKey();
			row.damage = d.damage;
			row.hits = d.hits;
			row.misses = d.misses;
			row.biggestHit = d.biggestHit;
			row.percent = totalDamage == 0 ? 0 : 100.0 * d.damage / totalDamage;
			out.add(row);
		}
		out.sort((a, b) -> Long.compare(b.damage, a.damage));
		return out;
	}

	/** Rows for the seen damage that no player row explains: hits by unknown players and effects. */
	private void addUnaccountedRows(Fight fight, boolean bossOnly, Map<String, Long> knownByTarget)
	{
		long unknown = 0;
		long effects = 0;
		for (TargetStats t : fight.targets.values())
		{
			if (!t.engaged || !counts(fight, t.key, bossOnly))
			{
				continue;
			}
			long known = knownByTarget.getOrDefault(t.key, 0L);
			unknown += Math.max(0, t.seenDamage - known);
			effects += t.effectDamage;
		}
		if (unknown > 0)
		{
			rows.add(pseudoRow(UNKNOWN_NAME, PlayerKind.UNKNOWN, unknown));
		}
		if (effects > 0)
		{
			rows.add(pseudoRow(EFFECTS_NAME, PlayerKind.EFFECTS, effects));
		}
	}

	private static PlayerRow pseudoRow(String name, PlayerKind kind, long damage)
	{
		PlayerRow row = new PlayerRow();
		row.name = name;
		row.kind = kind;
		row.damage = damage;
		return row;
	}

	private static boolean countsHit(Fight fight, PlayerStats p, String targetKey, boolean bossOnly)
	{
		return counts(fight, targetKey, bossOnly) && countsFor(fight, p, targetKey);
	}

	private static boolean counts(Fight fight, String targetKey, boolean bossOnly)
	{
		if (!bossOnly)
		{
			return true;
		}
		TargetStats t = fight.targets.get(targetKey);
		return t != null && t.boss;
	}

	/** Guesses only count on targets you or your party fought (same rule as "Others (unknown)"). */
	private static boolean countsFor(Fight fight, PlayerStats p, String targetKey)
	{
		if (p.kind != PlayerKind.ESTIMATE)
		{
			return true;
		}
		TargetStats t = fight.targets.get(targetKey);
		return t != null && t.engaged;
	}

	private void buildTargets(Fight fight, boolean bossOnly)
	{
		Map<String, TargetRow> byName = new LinkedHashMap<>();
		Map<String, Long> knownByTarget = new LinkedHashMap<>();
		for (PlayerStats p : fight.players.values())
		{
			for (Map.Entry<String, TargetDamage> e : p.damageByTarget().entrySet())
			{
				TargetStats t = fight.targets.get(e.getKey());
				if (t == null || !countsHit(fight, p, t.key, bossOnly) || e.getValue().damage == 0)
				{
					continue;
				}
				TargetRow row = targetRow(byName, t);
				row.byPlayer.merge(p.name, e.getValue().damage, Long::sum);
				if (p.kind != PlayerKind.ESTIMATE)
				{
					row.attacksByPlayer.computeIfAbsent(p.name, n -> new TargetDamage()).merge(e.getValue());
				}
				row.total += e.getValue().damage;
				knownByTarget.merge(t.key, e.getValue().damage, Long::sum);
			}
		}
		for (TargetStats t : fight.targets.values())
		{
			if (!t.engaged || !counts(fight, t.key, bossOnly))
			{
				continue;
			}
			long unknown = Math.max(0, t.seenDamage - knownByTarget.getOrDefault(t.key, 0L));
			if (unknown > 0 || t.effectDamage > 0)
			{
				TargetRow row = targetRow(byName, t);
				if (unknown > 0)
				{
					row.byPlayer.merge(UNKNOWN_NAME, unknown, Long::sum);
					row.total += unknown;
				}
				if (t.effectDamage > 0)
				{
					row.byPlayer.merge(EFFECTS_NAME, t.effectDamage, Long::sum);
					row.total += t.effectDamage;
				}
			}
		}
		for (TargetRow row : byName.values())
		{
			Map<String, Long> sorted = new LinkedHashMap<>();
			row.byPlayer.entrySet().stream()
				.sorted(Map.Entry.<String, Long>comparingByValue().reversed())
				.forEach(e -> sorted.put(e.getKey(), e.getValue()));
			row.byPlayer = sorted;
			targets.add(row);
		}
		targets.sort(Comparator.comparingLong((TargetRow t) -> t.total).reversed());
	}

	private static TargetRow targetRow(Map<String, TargetRow> byName, TargetStats t)
	{
		String name = t.name == null ? "Unknown" : t.name;
		TargetRow row = byName.computeIfAbsent(name, n ->
		{
			TargetRow tr = new TargetRow();
			tr.name = n;
			return tr;
		});
		row.boss |= t.boss;
		row.died |= t.died;
		return row;
	}

	/** The value a bar shows in this mode. */
	public static double value(PlayerRow row, MeterMode mode)
	{
		switch (mode)
		{
			case DPS:
				return row.dps;
			case HEALING:
				return row.healing;
			case DAMAGE_TAKEN:
				return row.damageTaken;
			case DAMAGE:
			default:
				return row.damage;
		}
	}

	/** Rows for a bar view, biggest first. Rows with 0 are left out. */
	public List<PlayerRow> sorted(MeterMode mode)
	{
		List<PlayerRow> out = new ArrayList<>();
		for (PlayerRow row : rows)
		{
			boolean damageMode = mode == MeterMode.DAMAGE || mode == MeterMode.DPS;
			if (!damageMode && !row.isPlayer())
			{
				continue;
			}
			if (value(row, mode) > 0)
			{
				out.add(row);
			}
		}
		out.sort(Comparator.comparingDouble((PlayerRow r) -> value(r, mode)).reversed()
			.thenComparing(r -> r.name));
		return out;
	}

	/** Overhealing as % of all healing (effective + overhealing). */
	public static double overhealPercent(long healing, long overheal)
	{
		long full = healing + overheal;
		return full <= 0 ? 0 : 100.0 * overheal / full;
	}

	/** Overhealing of the whole group as % of all healing. */
	public double groupOverhealPercent()
	{
		long heal = 0;
		long over = 0;
		for (PlayerRow r : rows)
		{
			heal += r.healing;
			over += r.overheal;
		}
		return overhealPercent(heal, over);
	}

	/** Sum of the values in this mode (for the header). */
	public double total(MeterMode mode)
	{
		double sum = 0;
		for (PlayerRow row : sorted(mode))
		{
			sum += value(row, mode);
		}
		return sum;
	}

	/** The player with the most damage, or null. */
	public PlayerRow topDamage()
	{
		return topPlayer(r -> r.damage);
	}

	/** The player with the most healing, or null. */
	public PlayerRow topHealer()
	{
		return topPlayer(r -> r.healing);
	}

	/** The player with the biggest hit, or null. */
	public PlayerRow topHit()
	{
		return topPlayer(r -> r.biggestHit);
	}

	/** Number of real players (you, party members and estimated players). */
	public int playerCount()
	{
		return (int) rows.stream().filter(PlayerRow::isPlayer).count();
	}

	private PlayerRow topPlayer(ToLongFunction<PlayerRow> value)
	{
		PlayerRow best = null;
		for (PlayerRow r : rows)
		{
			if (r.isPlayer() && value.applyAsLong(r) > 0 && (best == null || value.applyAsLong(r) > value.applyAsLong(best)))
			{
				best = r;
			}
		}
		return best;
	}

	public List<PlayerRow> getRows()
	{
		return rows;
	}

	/** Only you fought: poison, burn and hits nobody could be matched to do not make a group. */
	public boolean isSolo()
	{
		int players = 0;
		boolean you = false;
		for (PlayerRow row : rows)
		{
			if (row.isPlayer())
			{
				players++;
				you |= row.kind == PlayerKind.LOCAL;
			}
		}
		return players == 0 || (players == 1 && you);
	}

	public PlayerRow row(String name)
	{
		for (PlayerRow r : rows)
		{
			if (r.name.equals(name))
			{
				return r;
			}
		}
		return null;
	}

	public List<TargetRow> getTargets()
	{
		return targets;
	}

	public long getTotalDamage()
	{
		return totalDamage;
	}

	public int getKills()
	{
		return kills;
	}

	public double getGroupDps()
	{
		return totalDamage / (durationMs / 1000.0);
	}

	public long getDurationMs()
	{
		return durationMs;
	}

	public String getTitle()
	{
		return title;
	}
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.function.Predicate;

/**
 * Starts and ends fights and records every hit and heal. Free of RuneLite types, so it can be
 * tested with a fake clock. For your own hitsplats call {@link #playerHit} before
 * {@link #seenHit}, so the first hit of a fight is also seen.
 */
public class FightTracker
{
	/** Party reports arriving this long after a fight ended still count for it. */
	public static final long LATE_REPORT_MS = 5000;

	public interface Listener
	{
		void fightEnded(Fight fight);
	}

	private long idleTimeoutMs = 300_000;
	private long pauseAfterMs = 10_000;
	/** Saved fights; more makes the save file and the fight list slow. */
	private int maxHistory = 200;
	private String sessionId = newId();
	private Fight current;
	/** The raid you are in; the running fight then covers the whole raid. */
	private String raid;
	/** When the game started the raid's timer, or 0. */
	private long raidBeganMs;
	/** Inside a raid: the fight for the boss being fought now. */
	private Fight bossPart;
	/** Ended fights, newest first. */
	private final List<Fight> history = new ArrayList<>();
	private Listener listener;

	private static String newId()
	{
		return UUID.randomUUID().toString();
	}

	public void setListener(Listener listener)
	{
		this.listener = listener;
	}

	/** For tests: the plugin keeps the default (5 minutes). */
	void setIdleTimeoutMs(long idleTimeoutMs)
	{
		this.idleTimeoutMs = Math.max(1000, idleTimeoutMs);
	}

	/** For tests: the plugin keeps the default (10 seconds). */
	void setPauseAfterMs(long pauseAfterMs)
	{
		this.pauseAfterMs = Math.max(0, pauseAfterMs);
		if (current != null && current.raid == null)
		{
			current.pauseAfterMs = this.pauseAfterMs;
		}
	}

	/** For tests: the plugin keeps the default (200 fights). */
	void setMaxHistory(int maxHistory)
	{
		this.maxHistory = Math.max(1, maxHistory);
		trimHistory();
	}

	// ---- damage ----

	/** A hit by you or a party member. Starts a fight if none is running. */
	public void playerHit(long now, String player, PlayerKind kind, String targetKey, int npcId,
		String npcName, boolean boss, int amount, boolean miss)
	{
		playerHit(now, player, kind, targetKey, npcId, npcName, boss, amount, miss, null);
	}

	/** @param source weapon or spell name, or null */
	public void playerHit(long now, String player, PlayerKind kind, String targetKey, int npcId,
		String npcName, boolean boss, int amount, boolean miss, String source)
	{
		if (current == null && kind == PlayerKind.PARTY)
		{
			Fight late = recentFightWithTarget(now, targetKey);
			if (late != null)
			{
				late.player(player, kind).addHit(targetKey, amount, miss, source);
				return;
			}
		}
		for (Fight f : fightAndBossPart(now, boss))
		{
			f.target(targetKey, npcId, npcName, boss).hitAt(now);
			f.player(player, kind).addHit(targetKey, amount, miss, source);
			f.activity(now);
		}
	}

	/** Any damage hitsplat seen on an NPC. Starts a fight only on a boss. */
	public void seenHit(long now, String targetKey, int npcId, String npcName, boolean boss, int amount)
	{
		if (current == null && !boss)
		{
			return;
		}
		for (Fight f : fightAndBossPart(now, boss))
		{
			TargetStats t = f.target(targetKey, npcId, npcName, boss);
			t.seenDamage += Math.max(0, amount);
			if (t.engaged || t.boss)
			{
				f.activity(now);
			}
		}
	}

	/** Poison, venom, burn or bleed damage on an NPC. */
	public void effectHit(long now, String targetKey, int npcId, String npcName, boolean boss, int amount)
	{
		if (current == null || amount <= 0)
		{
			return;
		}
		current.target(targetKey, npcId, npcName, boss).effectDamage += amount;
		if (bossPart != null)
		{
			bossPart.target(targetKey, npcId, npcName, boss).effectDamage += amount;
		}
	}

	/** An estimated hit by a player without GoldenDPS. Call after {@link #seenHit}. */
	public void estimateHit(long now, String player, String targetKey, int amount, boolean miss)
	{
		if (current == null || player == null)
		{
			return;
		}
		for (Fight f : live())
		{
			PlayerStats p = f.player(player, PlayerKind.ESTIMATE);
			if (p.kind == PlayerKind.ESTIMATE)
			{
				p.addEstimate(targetKey, amount, miss);
			}
		}
	}

	/** A damage hitsplat seen on a player without GoldenDPS. */
	public void seenDamageTaken(long now, String player, int amount)
	{
		if (current == null || player == null || amount <= 0)
		{
			return;
		}
		for (Fight f : live())
		{
			f.player(player, PlayerKind.ESTIMATE).seenTaken += amount;
		}
	}

	// ---- damage taken and healing ----

	public void damageTaken(long now, String player, PlayerKind kind, int amount)
	{
		Fight f = fightForReport(now, kind);
		if (f != null && amount > 0)
		{
			f.player(player, kind).damageTaken += amount;
			if (f == current && bossPart != null)
			{
				bossPart.player(player, kind).damageTaken += amount;
			}
		}
	}

	public void heal(long now, String player, PlayerKind kind, HealType type, int amount)
	{
		heal(now, player, kind, type, amount, 0);
	}

	public void heal(long now, String player, PlayerKind kind, HealType type, int amount, int overheal)
	{
		Fight f = fightForReport(now, kind);
		if (f != null && (amount > 0 || overheal > 0))
		{
			f.player(player, kind).addHeal(type, amount, overheal);
			if (f == current && bossPart != null)
			{
				bossPart.player(player, kind).addHeal(type, amount, overheal);
			}
		}
	}

	// ---- fight end ----

	public void npcDied(long now, String targetKey, boolean boss)
	{
		if (current == null)
		{
			return;
		}
		if (bossPart != null)
		{
			TargetStats bt = bossPart.targets.get(targetKey);
			if (bt != null)
			{
				bt.diedAt(now);
				if ((boss || bt.boss) && bt.engaged && allBossesDead(bossPart))
				{
					endBossPart(now, "Boss died");
				}
			}
		}
		TargetStats t = current.targets.get(targetKey);
		if (t == null)
		{
			return;
		}
		t.diedAt(now);
		if (!(boss || t.boss) || !t.engaged || raid != null)
		{
			// a raid fight lasts until the raid is left
			return;
		}
		// end once every engaged boss is dead (e.g. all three Dagannoth Kings)
		if (allBossesDead(current))
		{
			end(now, "Boss died");
		}
	}

	/** Ends the fight after the idle timeout. Call every game tick. */
	public void tick(long now)
	{
		if (bossPart != null && now - bossPart.lastActivityMs >= idleTimeoutMs)
		{
			endBossPart(Math.min(now, bossPart.lastActivityMs + Math.min(pauseAfterMs, idleTimeoutMs)),
				"No hits for " + Format.duration(idleTimeoutMs));
		}
		if (raid != null)
		{
			return;
		}
		if (current != null && now - current.lastActivityMs >= idleTimeoutMs)
		{
			// the live clock ran on for the pause time after the last hit
			long endAt = current.lastActivityMs + Math.min(pauseAfterMs, idleTimeoutMs);
			end(Math.min(now, endAt), "No hits for " + Format.duration(idleTimeoutMs));
		}
	}

	public void endNow(long now, String reason)
	{
		if (bossPart != null)
		{
			endBossPart(now, reason);
		}
		if (current != null)
		{
			end(now, reason);
		}
	}

	private void end(long endMs, String reason)
	{
		Fight f = current;
		current = null;
		finishAndKeep(f, endMs, reason);
	}

	private void endBossPart(long endMs, String reason)
	{
		Fight b = bossPart;
		bossPart = null;
		finishAndKeep(b, endMs, reason);
	}

	private void finishAndKeep(Fight f, long endMs, String reason)
	{
		f.finish(endMs, reason);
		if (f.knownDamage() == 0)
		{
			// only strangers' hits: not our fight
			return;
		}
		addToHistory(f);
	}

	private void addToHistory(Fight f)
	{
		history.add(0, f);
		trimHistory();
		if (listener != null)
		{
			listener.fightEnded(f);
		}
	}

	// ---- game times ----

	/** A game time can come a little after the boss died and its fight ended. */
	static final long GAME_TIME_NEAR_MS = 10_000;

	/**
	 * The game printed the time of a boss or a raid: it becomes the time of that fight.
	 * Returns the fight if it had already ended (its personal best then needs the new time), else null.
	 */
	public Fight gameTime(long now, GameTimes.Time time)
	{
		Fight running = time.raid ? (raid != null ? current : null) : runningBossFight();
		if (running != null)
		{
			running.gameTimeMs = time.ms;
			return null;
		}
		Fight ended = recentlyEnded(now, time.raid);
		if (ended != null)
		{
			ended.gameTimeMs = time.ms;
		}
		return ended;
	}

	private Fight runningBossFight()
	{
		if (bossPart != null)
		{
			return bossPart;
		}
		return raid == null && current != null && current.hasBossTarget() ? current : null;
	}

	/** The last whole raid, or the last boss kill, that ended just now; or null. */
	private Fight recentlyEnded(long now, boolean wholeRaid)
	{
		for (Fight f : history)
		{
			if (now - f.endMs > GAME_TIME_NEAR_MS)
			{
				return null;
			}
			if (f.isWholeRaid() == wholeRaid && !f.run && (wholeRaid || f.bossDiedMs() > 0))
			{
				return f;
			}
		}
		return null;
	}

	// ---- raids ----

	/**
	 * Ends the running fight; the next fight covers the whole raid and only ends with
	 * {@link #endRaid}. Each boss in the raid also gets a fight of its own.
	 */
	public void startRaid(long now, String name)
	{
		if (name == null || name.equals(raid))
		{
			return;
		}
		endNow(now, "Raid started");
		raid = name;
		raidBeganMs = 0;
	}

	/**
	 * The game says the raid has begun and starts its own timer (CoX: "The raid has begun!").
	 * The raid fight then starts here and not at the first hit, so both timers match.
	 */
	public void raidBegan(long now)
	{
		if (raid != null && raidBeganMs == 0)
		{
			raidBeganMs = now;
		}
	}

	public void endRaid(long now, String reason)
	{
		if (raid == null)
		{
			return;
		}
		// the raid ends with its last hit, not when you leave after looting
		endNow(current != null ? Math.min(now, current.lastActivityMs) : now, reason);
		raid = null;
	}

	/**
	 * Adds a finished run (a Barrows run): the fights from {@code startMs} to {@code endMs} with
	 * targets that belong to the run, counting only the damage on those targets.
	 *
	 * @param activeMs the run time; the rest of the time from start to end is not counted
	 * @return the run fight
	 */
	public Fight addRun(String name, long startMs, long endMs, long activeMs, Predicate<TargetStats> belongs,
		String reason)
	{
		Fight run = new Fight(newId(), sessionId, startMs);
		run.raid = name;
		run.run = true;
		List<Fight> parts = new ArrayList<>(history);
		if (current != null)
		{
			parts.add(current);
		}
		for (Fight f : parts)
		{
			if (f.partOf != null || f.run || f.mergedFights > 0)
			{
				continue;
			}
			// by target: a brother can be fought in a fight that started before the run (a rat first)
			Set<String> keys = new HashSet<>();
			for (TargetStats t : f.targets.values())
			{
				if (belongs.test(t) && t.firstMs >= startMs && t.firstMs <= endMs)
				{
					keys.add(t.key);
					TargetStats runTarget = t.copy();
					runTarget.key = runKey(f, t.key);
					run.targets.put(runTarget.key, runTarget);
				}
			}
			if (keys.isEmpty())
			{
				continue;
			}
			for (PlayerStats p : f.players.values())
			{
				PlayerStats only = p.copy();
				only.keepTargets(keys);
				// NPC indexes are reused: two brothers may have had the same key in different fights
				run.player(p.name, p.kind).merge(only, key -> runKey(f, key));
			}
		}
		run.lastActivityMs = endMs;
		run.finish(endMs, reason);
		if (endMs - startMs > activeMs)
		{
			// the uncounted time (logged out, idle) as one gap at the end
			run.pauses.add(new long[]{startMs + activeMs, endMs});
		}
		addToHistory(run);
		return run;
	}

	private static String runKey(Fight f, String targetKey)
	{
		return f.id + "/" + targetKey;
	}

	/** Raids scale their monsters, so their defence is not known. */
	public boolean isInRaid()
	{
		return raid != null;
	}

	/** For tests. */
	String getRaid()
	{
		return raid;
	}

	/** The boss fights of a raid fight, oldest first, the running one included. */
	public List<Fight> partsOf(Fight raidFight)
	{
		List<Fight> parts = new ArrayList<>();
		for (Fight f : history)
		{
			if (raidFight.id.equals(f.partOf))
			{
				parts.add(0, f);
			}
		}
		if (bossPart != null && raidFight.id.equals(bossPart.partOf))
		{
			parts.add(bossPart);
		}
		return parts;
	}

	/** For tests. */
	Fight getBossPart()
	{
		return bossPart;
	}

	/**
	 * The fight for the boss meter: in a raid the current or last boss of this raid, otherwise the
	 * running or last fight that had a boss. It stays until the next boss fight.
	 */
	public Fight getBossDisplayFight()
	{
		if (raid == null)
		{
			if (current != null && current.hasBossTarget())
			{
				return current;
			}
			for (Fight f : history)
			{
				if (f.hasBossMeter())
				{
					return f;
				}
			}
			return null;
		}
		if (bossPart != null)
		{
			return bossPart;
		}
		if (current != null)
		{
			for (Fight f : history)
			{
				if (current.id.equals(f.partOf))
				{
					return f;
				}
			}
		}
		return null;
	}

	/** Inside a raid: the boss fight to record into; a boss hit starts one. */
	private Fight bossPartFor(long now, boolean boss)
	{
		if (raid == null || current == null)
		{
			return null;
		}
		if (bossPart == null && boss)
		{
			bossPart = new Fight(newId(), sessionId, now);
			bossPart.raid = raid;
			bossPart.partOf = current.id;
		}
		return bossPart;
	}

	/**
	 * Every boss fought is dead. A part of a boss ("Great Olm (Left claw)") does not end the fight on
	 * its own: Olm's claws die every phase, the fight ends with the head.
	 */
	private static boolean allBossesDead(Fight f)
	{
		boolean bossDied = false;
		for (TargetStats t : f.targets.values())
		{
			if (!t.boss || !t.engaged || (t.name != null && !Fight.bossName(t.name).equals(t.name)))
			{
				continue;
			}
			if (!t.died)
			{
				return false;
			}
			bossDied = true;
		}
		return bossDied;
	}

	/** The running fight (started if needed) and, inside a raid, the boss fight the same hit counts for. */
	private List<Fight> fightAndBossPart(long now, boolean boss)
	{
		List<Fight> out = new ArrayList<>(2);
		out.add(ensureFight(now));
		Fight b = bossPartFor(now, boss);
		if (b != null)
		{
			out.add(b);
		}
		return out;
	}

	private List<Fight> live()
	{
		List<Fight> out = new ArrayList<>(2);
		if (current != null)
		{
			out.add(current);
		}
		if (bossPart != null)
		{
			out.add(bossPart);
		}
		return out;
	}

	// ---- helpers ----

	private Fight ensureFight(long now)
	{
		if (current == null)
		{
			current = new Fight(newId(), sessionId, raid != null && raidBeganMs > 0 ? raidBeganMs : now);
			// a raid runs on the game clock: waiting between rooms counts too
			current.pauseAfterMs = raid == null ? pauseAfterMs : 0;
			current.raid = raid;
		}
		return current;
	}

	private Fight fightForReport(long now, PlayerKind kind)
	{
		if (current != null)
		{
			return current;
		}
		if (kind == PlayerKind.PARTY && !history.isEmpty())
		{
			Fight last = history.get(0);
			if (now - last.endMs <= LATE_REPORT_MS)
			{
				return last;
			}
		}
		return null;
	}

	private Fight recentFightWithTarget(long now, String targetKey)
	{
		if (history.isEmpty())
		{
			return null;
		}
		Fight last = history.get(0);
		if (now - last.endMs <= LATE_REPORT_MS && last.targets.containsKey(targetKey))
		{
			return last;
		}
		return null;
	}

	private void trimHistory()
	{
		while (history.size() > maxHistory)
		{
			history.remove(history.size() - 1);
		}
	}

	// ---- reading ----

	public Fight getCurrent()
	{
		return current;
	}

	/** The running fight, or else the last one (raid boss fights excluded). */
	public Fight getDisplayFight()
	{
		if (current != null)
		{
			return current;
		}
		for (Fight f : history)
		{
			if (f.partOf == null)
			{
				return f;
			}
		}
		return null;
	}

	public List<Fight> getHistory()
	{
		return Collections.unmodifiableList(history);
	}

	public Fight findFight(String id)
	{
		if (current != null && current.id.equals(id))
		{
			return current;
		}
		for (Fight f : history)
		{
			if (f.id.equals(id))
			{
				return f;
			}
		}
		return null;
	}

	/** Ended fights of this session, newest first. */
	public List<Fight> getSessionFights()
	{
		List<Fight> out = new ArrayList<>();
		for (Fight f : history)
		{
			if (sessionId.equals(f.sessionId))
			{
				out.add(f);
			}
		}
		return out;
	}

	/** All fights of this session added together, or null. */
	public Fight getSessionTotal(long now)
	{
		List<Fight> fights = new ArrayList<>();
		for (Fight f : history)
		{
			if (isWholeFight(f))
			{
				fights.add(f);
			}
		}
		if (current != null)
		{
			fights.add(0, current);
		}
		return added("session", fights, now);
	}

	/**
	 * The overall meter: the running or last fight together with the fights before it, back to the
	 * last break of {@link #idleTimeoutMs} without fighting. So the meter keeps counting over boss
	 * kills (Barrows, a slayer trip) instead of starting at zero after every kill.
	 */
	public Fight getOverall(long now)
	{
		List<Fight> chain = new ArrayList<>();
		if (current != null)
		{
			chain.add(current);
		}
		for (Fight f : history)
		{
			if (!isWholeFight(f))
			{
				continue;
			}
			if (!chain.isEmpty() && chain.get(chain.size() - 1).startMs - f.endMs > idleTimeoutMs)
			{
				break;
			}
			chain.add(f);
		}
		return chain.size() == 1 ? chain.get(0) : added("overall", chain, now);
	}

	/** The overall meter goes on: a fight runs, or the last one ended less than the idle time ago. */
	public boolean isOverallGoingOn(long now)
	{
		if (current != null)
		{
			return true;
		}
		for (Fight f : history)
		{
			if (isWholeFight(f))
			{
				return now - f.endMs <= idleTimeoutMs;
			}
		}
		return false;
	}

	/** A fight of this session that is not part of another one (raid boss fights, runs). */
	private boolean isWholeFight(Fight f)
	{
		return sessionId.equals(f.sessionId) && f.partOf == null && !f.run && f.mergedFights == 0;
	}

	/** The fights (newest first) added together, or null without fights. */
	private static Fight added(String id, List<Fight> newestFirst, long now)
	{
		if (newestFirst.isEmpty())
		{
			return null;
		}
		Fight total = new Fight(id, newestFirst.get(0).sessionId, 0);
		for (int i = newestFirst.size() - 1; i >= 0; i--)
		{
			total.merge(newestFirst.get(i), now);
		}
		return total;
	}

	/** Ends the running fight and starts a new session; the history is kept. */
	public void resetSession(long now)
	{
		endNow(now, "Reset");
		sessionId = newId();
	}

	public void clearHistory()
	{
		current = null;
		bossPart = null;
		history.clear();
	}

	/** Replaces the history with saved fights (newest first); keeps the running fight. */
	public void setHistory(List<Fight> fights)
	{
		history.clear();
		if (fights != null)
		{
			for (Fight f : fights)
			{
				if (f != null && f.id != null && f.players != null && f.targets != null)
				{
					history.add(f);
				}
			}
		}
		trimHistory();
	}
}

package com.goldendps.model;

import java.util.Locale;

public final class Format
{
	private Format()
	{
	}

	/** 950, 12.3k, 1.25m */
	public static String amount(double v)
	{
		if (v >= 1_000_000)
		{
			return String.format(Locale.US, "%.2fm", v / 1_000_000);
		}
		if (v >= 10_000)
		{
			return String.format(Locale.US, "%.1fk", v / 1_000);
		}
		return String.format(Locale.US, "%,d", Math.round(v));
	}

	/** DPS with one decimal: 7.4 */
	public static String dps(double v)
	{
		return String.format(Locale.US, "%.1f", v);
	}

	public static String percent(double v)
	{
		return String.format(Locale.US, "%.0f%%", v);
	}

	/** "90% (255/284)", or "-" without attacks. */
	public static String accuracy(int hits, int misses)
	{
		int attacks = hits + misses;
		return attacks == 0 ? "-" : String.format(Locale.US, "%.0f%% (%d/%d)", 100.0 * hits / attacks, hits, attacks);
	}

	/** 0:42, 12:05, 1:02:03 */
	public static String duration(long ms)
	{
		long s = ms / 1000;
		long h = s / 3600;
		long m = (s % 3600) / 60;
		long sec = s % 60;
		if (h > 0)
		{
			return String.format(Locale.US, "%d:%02d:%02d", h, m, sec);
		}
		return String.format(Locale.US, "%d:%02d", m, sec);
	}

	/** Like the game's own timers, to a hundredth of a second: 0:54.60, 12:05.40, 1:02:03.00 */
	public static String preciseDuration(long ms)
	{
		long hundredths = Math.round(ms / 10.0);
		return duration(hundredths / 100 * 1000) + String.format(Locale.US, ".%02d", hundredths % 100);
	}
}

package com.goldendps.model;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The times the game prints in the chat when a boss or raid is done, so the meter shows the
 * same time as the game ("Fight duration: 0:54.60").
 */
public final class GameTimes
{
	private static final String TIME = "(\\d+(?::\\d{1,2}){0,2}(?:\\.\\d+)?)";

	/** "Theatre of Blood total completion time: 20:00.00", CoX "your raid is complete! ... Duration: 25:13.20". */
	private static final Pattern RAID = Pattern.compile(
		"(?i)(?:total completion time|raid is complete!.*?\\bduration):\\s*" + TIME);

	/**
	 * "Fight duration:", "Challenge duration:" (Gauntlet), "...complete! Duration:" (ToB rooms) and
	 * "Challenge complete: Path of Het. Duration:" (ToA rooms). Not "Wave duration" or "Lap duration".
	 */
	private static final Pattern BOSS = Pattern.compile(
		"(?i)(?:\\b(?:fight|challenge) duration|(?:^|[.!])\\s*duration):\\s*" + TIME);

	/** A time from the chat. */
	public static final class Time
	{
		public final long ms;
		/** The time of a whole raid, else of one boss. */
		public final boolean raid;

		Time(long ms, boolean raid)
		{
			this.ms = ms;
			this.raid = raid;
		}
	}

	private GameTimes()
	{
	}

	/** The time in this game message, or null. */
	public static Time parse(String message)
	{
		String text = ChatText.withoutTags(message);
		Matcher raid = RAID.matcher(text);
		if (raid.find())
		{
			return new Time(toMs(raid.group(1)), true);
		}
		Matcher boss = BOSS.matcher(text);
		return boss.find() ? new Time(toMs(boss.group(1)), false) : null;
	}

	/** "1:02:03.40", "0:54.60" or "54" to milliseconds. */
	static long toMs(String time)
	{
		String[] parts = time.split(":");
		double seconds = 0;
		for (String part : parts)
		{
			seconds = seconds * 60 + Double.parseDouble(part);
		}
		return Math.round(seconds * 1000);
	}
}

package com.goldendps.model;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * How much a heal would give if nothing was wasted ("full heal"). Used for overhealing.
 * Numbers from the OSRS Wiki. Food is matched by item name, so noted/blighted/other
 * variants with the same name work too.
 */
public final class HealTable
{
	/** Not in the table: only effective healing is counted. */
	public static final int UNKNOWN = -1;

	private static final Map<String, Integer> FIXED = new HashMap<>();

	static
	{
		FIXED.put("lobster", 12);
		FIXED.put("swordfish", 14);
		FIXED.put("monkfish", 16);
		FIXED.put("cooked karambwan", 18);
		FIXED.put("blighted karambwan", 18);
		FIXED.put("curry", 19);
		FIXED.put("shark", 20);
		FIXED.put("sea turtle", 21);
		FIXED.put("manta ray", 22);
		FIXED.put("blighted manta ray", 22);
		FIXED.put("dark crab", 22);
		FIXED.put("tuna potato", 22);
	}

	private HealTable()
	{
	}

	/** "Saradomin brew(3)" becomes "saradomin brew". */
	static String baseName(String itemName)
	{
		if (itemName == null)
		{
			return "";
		}
		String n = itemName.toLowerCase(Locale.ROOT).trim();
		int p = n.indexOf('(');
		if (p > 0)
		{
			n = n.substring(0, p).trim();
		}
		return n;
	}

	/** Full heal of one bite / dose, or {@link #UNKNOWN}. hpLevel = your real Hitpoints level. */
	public static int foodHeal(String itemName, int hpLevel)
	{
		String n = baseName(itemName);
		if (n.equals("saradomin brew"))
		{
			return hpLevel * 15 / 100 + 2;
		}
		if (n.equals("anglerfish") || n.equals("blighted anglerfish"))
		{
			return hpLevel / 10 + 2 * (hpLevel / 25) + 5 * (hpLevel / 93) + 2;
		}
		Integer v = FIXED.get(n);
		return v == null ? UNKNOWN : v;
	}

	/** How far above your real Hitpoints level this food can take you (brew, anglerfish). */
	public static int foodBoost(String itemName, int hpLevel)
	{
		String n = baseName(itemName);
		if (n.equals("saradomin brew") || n.equals("anglerfish") || n.equals("blighted anglerfish"))
		{
			return foodHeal(itemName, hpLevel);
		}
		return 0;
	}

	/** Sanguinesti staff heal when it procs: half the damage of that hit. */
	public static int sanguinesti(int damage)
	{
		return Math.max(0, damage) / 2;
	}

	/**
	 * Blood spells: 25% of damage, +2% per bloodbark piece, x1.1 with an ancient sceptre,
	 * x1.5 with Zuriel's staff. Rounded down.
	 */
	public static int bloodSpell(int damage, int bloodbarkPieces, String weaponName)
	{
		double ratio = 0.25 + 0.02 * Math.max(0, Math.min(5, bloodbarkPieces));
		String w = weaponName == null ? "" : weaponName.toLowerCase(Locale.ROOT);
		if (w.contains("ancient sceptre"))
		{
			ratio *= 1.1;
		}
		else if (w.contains("zuriel"))
		{
			ratio *= 1.5;
		}
		return (int) Math.floor(Math.max(0, damage) * ratio + 1e-9);
	}

	/** The Blood ancient sceptre lets blood magic heal 10% of your Hitpoints above your level. */
	public static int bloodBoost(String weaponName, int hpLevel)
	{
		String w = weaponName == null ? "" : weaponName.toLowerCase(Locale.ROOT);
		return w.contains("blood ancient sceptre") ? hpLevel / 10 : 0;
	}

	/** Weapons you can cast blood spells with. */
	public static boolean isMagicWeapon(String weaponName)
	{
		String w = weaponName == null ? "" : weaponName.toLowerCase(Locale.ROOT);
		return w.contains("staff") || w.contains("wand") || w.contains("sceptre") || w.contains("kodai");
	}
}

package com.goldendps.model;

/** Source of a heal, decided by {@link HealthWatcher} from timing. */
public enum HealType
{
	FOOD,
	LIFESTEAL,
	/** Natural regeneration; only counted when enabled. */
	REGEN,
	/** Heal Other / Heal Group. */
	HEAL_OTHER,
	/** Healed by someone else; not credited to you. */
	RECEIVED
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.List;

/**
 * Turns your hitpoints changes into heals, with overhealing.
 *
 * <p>Effective heal = how much your HP really went up. Overheal = the full heal of the
 * source minus the effective heal, but only when you ended at your HP cap (so a wrong
 * table value never makes up overhealing when nothing was wasted).</p>
 *
 * <ul>
 * <li>{@link #foodEaten}: the plugin saw a food/potion really leave your inventory
 *     (full heal from {@link HealTable}, or {@link HealTable#UNKNOWN}).</li>
 * <li>{@link #lifesteal}: the plugin saw a Sanguinesti heal or a blood spell on an NPC you hit.</li>
 * <li>HP up the tick you hit something, without a known source: lifesteal without overheal
 *     (Soulreaper axe and others).</li>
 * <li>+1 or +2 with no reason: {@link HealType#REGEN}. Anything else: {@link HealType#RECEIVED}.</li>
 * <li>HP that goes down without a hitsplat after you cast Heal Other / Heal Group: {@link HealType#HEAL_OTHER}.</li>
 * </ul>
 *
 * <p>HP is only read once per tick, so a heal and a hit in the same tick are
 * added back together: heal = HP change + damage hitsplats on you.</p>
 */
public class HealthWatcher
{
	/** Ticks we wait for the HP to go up after eating. */
	static final int FOOD_TICKS = 2;
	/** Ticks we wait for the HP to go up after a lifesteal hit. */
	static final int LIFESTEAL_TICKS = 1;
	static final int HEAL_OTHER_TICKS = 5;
	static final int MAX_REGEN = 2;

	public static class Heal
	{
		public final HealType type;
		public final int amount;
		public final int overheal;

		Heal(HealType type, int amount, int overheal)
		{
			this.type = type;
			this.amount = amount;
			this.overheal = overheal;
		}

		@Override
		public String toString()
		{
			return type + " " + amount + " (+" + overheal + " over)";
		}
	}

	/** Heals we know are coming (food eaten, lifesteal seen) but have not been matched to HP yet. */
	private static class Pending
	{
		final int tick;
		final int full;
		/** HP above your level this source may reach. */
		final int boost;

		Pending(int tick, int full, int boost)
		{
			this.tick = tick;
			this.full = full;
			this.boost = boost;
		}
	}

	private int prevHp = -1;
	private int maxHp = 99;
	private int netChange;
	private int hitsplatDamage;
	private int lastClickTick = Integer.MIN_VALUE / 2;
	private int lastMyHitTick = Integer.MIN_VALUE / 2;
	private int healOtherCastTick = Integer.MIN_VALUE / 2;
	private final List<Pending> food = new ArrayList<>();
	private final List<Pending> life = new ArrayList<>();

	/** Forget the last HP value (login, world hop). */
	public void reset()
	{
		prevHp = -1;
		netChange = 0;
		hitsplatDamage = 0;
		food.clear();
		life.clear();
	}

	/** Your real (not boosted) Hitpoints level. */
	public void setMaxHp(int level)
	{
		if (level > 0)
		{
			maxHp = level;
		}
	}

	/** New current (boosted) hitpoints value. */
	public void hpChanged(int hp)
	{
		if (prevHp < 0)
		{
			prevHp = hp;
			return;
		}
		netChange += hp - prevHp;
		prevHp = hp;
	}

	/** You clicked Eat / Drink (backup when the item is not seen leaving the inventory). */
	public void consumed(int tick)
	{
		lastClickTick = tick;
	}

	/** Food or potion really eaten. full = {@link HealTable#UNKNOWN} when not in the table. */
	public void foodEaten(int tick, int full, int boost)
	{
		food.add(new Pending(tick, full, boost));
		lastClickTick = tick;
	}

	/** A lifesteal heal is coming (Sanguinesti heal, blood spell) worth this much if nothing is wasted. */
	public void lifesteal(int tick, int full, int boost)
	{
		if (full > 0)
		{
			life.add(new Pending(tick, full, boost));
		}
	}

	/** You hit an NPC for more than 0. */
	public void myHit(int tick)
	{
		lastMyHitTick = tick;
	}

	public void healOtherCast(int tick)
	{
		healOtherCastTick = tick;
	}

	/** A damage hitsplat on you. */
	public void damageOnMe(int amount)
	{
		hitsplatDamage += Math.max(0, amount);
	}

	/** Call once at the end of every tick. Returns the heals found this tick. */
	public List<Heal> endTick(int tick)
	{
		List<Heal> out = new ArrayList<>(2);
		int change = netChange + hitsplatDamage;
		boolean realGain = netChange > 0;
		int gain = Math.max(0, change);

		gain = settle(food, HealType.FOOD, FOOD_TICKS, tick, gain, out);
		gain = settle(life, HealType.LIFESTEAL, LIFESTEAL_TICKS, tick, gain, out);

		if (gain > 0)
		{
			HealType type;
			if (tick - lastClickTick <= FOOD_TICKS)
			{
				type = HealType.FOOD;
			}
			else if (tick - lastMyHitTick <= LIFESTEAL_TICKS)
			{
				type = HealType.LIFESTEAL;
			}
			else if (gain <= MAX_REGEN)
			{
				type = HealType.REGEN;
			}
			else
			{
				type = HealType.RECEIVED;
			}
			// HP did not really go up: only trust it when there is a clear reason
			if (realGain || type == HealType.FOOD || type == HealType.LIFESTEAL)
			{
				out.add(new Heal(type, gain, 0));
			}
		}
		else if (change < 0 && tick - healOtherCastTick <= HEAL_OTHER_TICKS)
		{
			out.add(new Heal(HealType.HEAL_OTHER, -change, 0));
			healOtherCastTick = Integer.MIN_VALUE / 2;
		}

		netChange = 0;
		hitsplatDamage = 0;
		return out;
	}

	/**
	 * Match waiting heals to the HP gain. Settles when HP went up, or when the wait is over
	 * (then everything was wasted). Returns the gain that is left for other sources.
	 */
	private int settle(List<Pending> list, HealType type, int waitTicks, int tick, int gain, List<Heal> out)
	{
		if (list.isEmpty())
		{
			return gain;
		}
		int oldest = Integer.MAX_VALUE;
		for (Pending p : list)
		{
			oldest = Math.min(oldest, p.tick);
		}
		if (gain <= 0 && tick - oldest < waitTicks)
		{
			return gain; // keep waiting
		}

		boolean unknown = false;
		int full = 0;
		int boost = 0;
		for (Pending p : list)
		{
			if (p.full < 0)
			{
				unknown = true;
			}
			else
			{
				full += p.full;
			}
			boost = Math.max(boost, p.boost);
		}
		list.clear();

		int effective = unknown ? gain : Math.min(gain, full);
		boolean capped = prevHp >= 0 && prevHp >= maxHp + boost;
		int overheal = !unknown && capped ? Math.max(0, full - effective) : 0;
		if (effective > 0 || overheal > 0)
		{
			out.add(new Heal(type, effective, overheal));
		}
		return gain - effective;
	}
}

package com.goldendps.model;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Fight history, personal bests and monster stats as JSON, one file of each per account. */
public class HistoryStore
{
	public static final int VERSION = 1;

	public static class SaveFile
	{
		public int version = VERSION;
		public long accountHash;
		public long savedAt;
		/** Newest first. */
		public List<Fight> fights = new ArrayList<>();
	}

	private final Gson gson;
	private final Filepath dir;

	/** @param dir the plugin's data folder (Plugin.getPluginDirectory) */
	public HistoryStore(Gson gson, Filepath dir)
	{
		this.gson = gson;
		this.dir = dir;
	}

	public Filepath fileFor(long accountHash)
	{
		return dir.joinSegment(accountHash + ".json");
	}

	public void save(long accountHash, List<Fight> fights, long now) throws IOException
	{
		SaveFile data = new SaveFile();
		data.accountHash = accountHash;
		data.savedAt = now;
		data.fights = new ArrayList<>(fights);
		write(fileFor(accountHash), data);
	}

	/** Personal bests have their own file, so they outlive the fights they came from. */
	public void saveRecords(long accountHash, BossRecords records) throws IOException
	{
		write(recordsFile(accountHash), records);
	}

	private Filepath recordsFile(long accountHash)
	{
		return dir.joinSegment(accountHash + ".records.json");
	}

	/** Monster stats have no limit, so they live apart from the fight history too. */
	public void saveMonsters(long accountHash, MonsterStats monsters) throws IOException
	{
		write(monstersFile(accountHash), monsters);
	}

	private Filepath monstersFile(long accountHash)
	{
		return dir.joinSegment(accountHash + ".monsters.json");
	}

	/** Writes to a temporary file first, so a crash never leaves a half-written file. */
	private void write(Filepath target, Object data) throws IOException
	{
		dir.createDirectories();
		Filepath tmp = dir.joinSegment(target.getFileName() + ".tmp");
		try (Writer w = tmp.openBufferedWriter())
		{
			gson.toJson(data, w);
		}
		try
		{
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	/** Saved personal bests, or null when there are none or the file is broken. */
	public BossRecords loadRecords(long accountHash) throws IOException
	{
		BossRecords data = read(recordsFile(accountHash), BossRecords.class);
		if (data == null || data.byBoss == null)
		{
			return null;
		}
		data.byBoss.values().removeIf(x -> x == null || x.boss == null);
		return data;
	}

	/** Saved monster stats; empty when there are none yet or the file is broken. */
	public MonsterStats loadMonsters(long accountHash) throws IOException
	{
		MonsterStats data = read(monstersFile(accountHash), MonsterStats.class);
		if (data == null || data.byName == null)
		{
			return new MonsterStats();
		}
		data.byName.values().removeIf(m -> m == null || m.name == null || m.attacks == null || m.weapons == null);
		return data;
	}

	/** The file as {@code type}, or null when it is missing or broken. */
	private <T> T read(Filepath file, Class<T> type) throws IOException
	{
		if (!file.exists())
		{
			return null;
		}
		try (Reader r = file.openBufferedReader())
		{
			return gson.fromJson(r, type);
		}
		catch (JsonParseException e)
		{
			return null;
		}
	}

	/** Saved fights, newest first. A broken file is kept aside and an empty list returned. */
	public List<Fight> load(long accountHash) throws IOException
	{
		Filepath file = fileFor(accountHash);
		if (!file.exists())
		{
			return new ArrayList<>();
		}
		try (Reader r = file.openBufferedReader())
		{
			SaveFile data = gson.fromJson(r, SaveFile.class);
			if (data == null || data.fights == null)
			{
				return new ArrayList<>();
			}
			List<Fight> out = new ArrayList<>();
			for (Fight f : data.fights)
			{
				if (f != null && f.id != null && f.players != null && f.targets != null)
				{
					out.add(f);
				}
			}
			return out;
		}
		catch (JsonParseException e)
		{
			file.moveTo(dir.joinSegment(accountHash + ".broken-" + System.currentTimeMillis() + ".json"),
				StandardCopyOption.REPLACE_EXISTING);
			return new ArrayList<>();
		}
	}
}

package com.goldendps.model;

import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Set;

/**
 * Guesses who did an "other" hitsplat on an NPC. The game does not tell us,
 * so we remember when other players start an attack animation on that NPC,
 * and give each hitsplat to the oldest attack that has not landed yet
 * (melee lands fast, ranged and magic a few ticks later).
 *
 * <p>It is a guess: when two players hit the same NPC in the same ticks it can
 * pick the wrong one. Hits we can't match stay "Others (unknown)".</p>
 */
public class HitAttributor
{
	/** Longest time from attack animation to hitsplat (long-range magic / ranged). */
	static final int MAX_DELAY_TICKS = 6;
	/** No weapon attacks faster than every 2 ticks: closer animations are not new attacks. */
	static final int MIN_ATTACK_GAP = 2;

	private static class Attack
	{
		final String player;
		final String target;
		final int tick;
		int matchedTick = Integer.MIN_VALUE;

		Attack(String player, String target, int tick)
		{
			this.player = player;
			this.target = target;
			this.tick = tick;
		}
	}

	/** Oldest first. */
	private final LinkedList<Attack> attacks = new LinkedList<>();
	private final Map<String, Integer> lastAttack = new HashMap<>();

	/** Another player started an attack animation while targeting this NPC. */
	public void attack(int tick, String player, String targetKey)
	{
		Integer last = lastAttack.get(player);
		if (last != null && tick - last < MIN_ATTACK_GAP && tick >= last)
		{
			return;
		}
		lastAttack.put(player, tick);
		attacks.add(new Attack(player, targetKey, tick));
	}

	/** Who probably did this hitsplat? Null if nobody fits. */
	public String assign(int tick, String targetKey)
	{
		expire(tick);

		// 1) the oldest attack on this NPC that has not landed yet
		for (Attack a : attacks)
		{
			if (a.matchedTick == Integer.MIN_VALUE && a.tick <= tick && a.target.equals(targetKey))
			{
				a.matchedTick = tick;
				return a.player;
			}
		}

		// 2) more hitsplats in the same tick (scythe, multi-hit weapons):
		//    only if one player landed a hit on this NPC this tick
		Set<String> landed = new LinkedHashSet<>();
		for (Attack a : attacks)
		{
			if (a.matchedTick == tick && a.target.equals(targetKey))
			{
				landed.add(a.player);
			}
		}
		return landed.size() == 1 ? landed.iterator().next() : null;
	}

	public void clear()
	{
		attacks.clear();
		lastAttack.clear();
	}

	private void expire(int tick)
	{
		Iterator<Attack> it = attacks.iterator();
		while (it.hasNext())
		{
			Attack a = it.next();
			if (tick - a.tick > MAX_DELAY_TICKS || a.tick > tick)
			{
				it.remove();
			}
		}
		if (lastAttack.size() > 200)
		{
			lastAttack.values().removeIf(t -> tick - t > MAX_DELAY_TICKS);
		}
	}
}

package com.goldendps.model;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Your chance to hit a monster with your next normal attack, with the formulas of the OSRS Wiki
 * ("Damage per second" pages), for a normal attack, a special attack or a spell you click.
 */
public final class HitChance
{
	private HitChance()
	{
	}

	/**
	 * @param weaponStyle the style selected for your weapon
	 * @param defenceLevel the monster's defence now, lowered by special attacks
	 * @param magicLevel the monster's magic level now, lowered by special attacks
	 */
	public static double of(PlayerState p, WeaponStyles.Style weaponStyle, NpcStats.Npc npc, int defenceLevel,
		int magicLevel)
	{
		WeaponStyles.Style style = p.clickedSpell != null ? WeaponStyles.CLICKED_SPELL : weaponStyle;
		if (alwaysHit(npc, style.type, p.clickedSpell != null))
		{
			return 1;
		}
		Spec spec = p.specialAttack && p.clickedSpell == null ? Spec.of(p.weaponName) : null;
		WeaponStyles.Type defendedWith = spec != null && spec.defendedWith != null ? spec.defendedWith : style.type;
		long roll = attackRoll(p, style, npc);
		if (spec != null)
		{
			roll = roll * spec.accuracyTimes / spec.accuracyPer;
		}
		if (spec != null && p.weaponName.toLowerCase(Locale.ROOT).startsWith("soulreaper axe"))
		{
			roll = roll * (100 + 12 * p.soulreaperStacks) / 100;
		}
		long defence = defenceRoll(defendedWith, npc, defenceLevel, magicLevel);
		if (spec != null && spec.rolls > 1)
		{
			// a spec that rolls again after a miss hits when any roll hits
			return 1 - Math.pow(1 - chance(roll, defence), spec.rolls);
		}
		String weapon = p.weaponName == null ? "" : p.weaponName.toLowerCase(Locale.ROOT);
		if (defendedWith == WeaponStyles.Type.STAB && weapon.startsWith("osmumten's fang"))
		{
			return fangChance(roll, defence);
		}
		if (defendedWith == WeaponStyles.Type.MAGIC && wears(p, "brimstone ring"))
		{
			// a quarter of the time it ignores 10% of the monster's magic defence
			return 0.75 * chance(roll, defence) + 0.25 * chance(roll, defence * 9 / 10);
		}
		return chance(roll, defence);
	}

	/**
	 * Osmumten's fang rolls its accuracy twice and keeps the better roll, so it hits more often than one roll.
	 * The exact chance for two rolls, from the OSRS Wiki DPS calculator.
	 */
	static double fangChance(long attackRoll, long defenceRoll)
	{
		double a = attackRoll < 0 ? Math.min(0, attackRoll + 2) : attackRoll;
		double d = defenceRoll < 0 ? Math.min(0, defenceRoll + 2) : defenceRoll;
		if (a >= 0 && d >= 0)
		{
			if (a > d)
			{
				return 1 - (d + 2) * (2 * d + 3) / (a + 1) / (a + 1) / 6;
			}
			return a * (4 * a + 5) / 6 / (a + 1) / (d + 1);
		}
		if (a >= 0)
		{
			return 1 - 1 / (-d + 1) / (a + 1);
		}
		// both negative: swap them, like the calculator does
		return d >= 0 ? 0 : 1 - (-a + 2) * (2 * -a + 3) / 6 / (-a + 1) / (-d + 1);
	}
	/** What a special attack changes: more accuracy, and some hit another defence than your style. */
	static final class Spec
	{
		private static final Map<String, Spec> BY_WEAPON = new LinkedHashMap<>();

		static
		{
			// from the OSRS Wiki DPS calculator; a weapon not listed specs like a normal attack
			for (String godsword : new String[]{"armadyl", "bandos", "saradomin", "zamorak", "ancient"})
			{
				add(godsword + " godsword", 2, 1, WeaponStyles.Type.SLASH);
			}
			add("osmumten's fang", 3, 2, null);
			add("arkan blade", 3, 2, WeaponStyles.Type.SLASH);
			add("granite hammer", 3, 2, null);
			add("elder maul", 5, 4, null);
			add("dragon mace", 5, 4, WeaponStyles.Type.CRUSH);
			add("dragon sword", 5, 4, WeaponStyles.Type.STAB);
			add("dragon scimitar", 5, 4, WeaponStyles.Type.SLASH);
			add("abyssal whip", 5, 4, null);
			add("dragon dagger", 23, 20, WeaponStyles.Type.SLASH);
			add("abyssal dagger", 5, 4, WeaponStyles.Type.SLASH);
			add("brine sabre", 2, 1, null);
			add("barrelchest anchor", 2, 1, null);
			add("dragon claws", 1, 1, WeaponStyles.Type.SLASH).rolls = 4;
			add("dragon halberd", 1, 1, WeaponStyles.Type.SLASH);
			add("crystal halberd", 1, 1, WeaponStyles.Type.SLASH);
			add("dragon longsword", 1, 1, WeaponStyles.Type.SLASH);
			add("saradomin sword", 1, 1, WeaponStyles.Type.SLASH);
			add("arclight", 1, 1, WeaponStyles.Type.STAB);
			add("emberlight", 1, 1, WeaponStyles.Type.STAB);
			add("voidwaker", 1, 1, WeaponStyles.Type.MAGIC);
			add("saradomin's blessed sword", 1, 1, WeaponStyles.Type.MAGIC);
			add("crimson kisten", 1, 1, WeaponStyles.Type.CRUSH);
			add("zaryte crossbow", 2, 1, null);
			add("webweaver bow", 2, 1, null);
			add("toxic blowpipe", 2, 1, null);
			add("blazing blowpipe", 2, 1, null);
			add("magic shortbow", 10, 7, null);
			add("heavy ballista", 5, 4, null);
			add("light ballista", 5, 4, null);
			add("tonalztics of ralos", 3, 2, null);
			add("accursed sceptre", 3, 2, null);
			add("volatile nightmare staff", 3, 2, null);
			add("eye of ayak", 2, 1, null);
			add("zorya's tome", 5, 2, null);
		}

		final int accuracyTimes;
		final int accuracyPer;
		/** Dragon claws roll up to four times. */
		int rolls = 1;
		/** null: the defence of your style. */
		final WeaponStyles.Type defendedWith;

		private Spec(int accuracyTimes, int accuracyPer, WeaponStyles.Type defendedWith)
		{
			this.accuracyTimes = accuracyTimes;
			this.accuracyPer = accuracyPer;
			this.defendedWith = defendedWith;
		}

		private static Spec add(String weapon, int times, int per, WeaponStyles.Type defendedWith)
		{
			Spec spec = new Spec(times, per, defendedWith);
			BY_WEAPON.put(weapon, spec);
			return spec;
		}

		/** The special attack of this weapon; a weapon not listed specs like a normal attack. */
		static Spec of(String weaponName)
		{
			String weapon = weaponName == null ? "" : weaponName.toLowerCase(Locale.ROOT);
			for (Map.Entry<String, Spec> e : BY_WEAPON.entrySet())
			{
				if (weapon.startsWith(e.getKey()))
				{
					return e.getValue();
				}
			}
			return new Spec(1, 1, null);
		}
	}

	/** Some monsters are always hit: by every style, by one, or by anything but a spell you click. */
	static boolean alwaysHit(NpcStats.Npc npc, WeaponStyles.Type type, boolean clickedSpell)
	{
		String skill = type.isMelee() ? "melee" : type.isRanged() ? "ranged" : "magic";
		return npc.hasRule("always-hit") || npc.hasRule("always-hit-" + skill)
			|| npc.hasRule("always-hit-not-clicked") && !clickedSpell;
	}

	/** The game's hit chance; a roll can be negative with very low (or negative) bonuses. */
	static double chance(long attackRoll, long defenceRoll)
	{
		long attack = attackRoll < 0 ? Math.min(0, attackRoll + 2) : attackRoll;
		long defence = defenceRoll < 0 ? Math.min(0, defenceRoll + 2) : defenceRoll;
		if (attack >= 0 && defence >= 0)
		{
			return positiveChance(attack, defence);
		}
		if (attack >= 0)
		{
			return 1 - 1.0 / (-defence + 1) / (attack + 1);
		}
		return defence >= 0 ? 0 : positiveChance(-defence, -attack);
	}

	private static double positiveChance(long attack, long defence)
	{
		if (attack > defence)
		{
			return 1 - (defence + 2) / (2.0 * (attack + 1));
		}
		return attack / (2.0 * (defence + 1));
	}
	static long defenceRoll(WeaponStyles.Type type, NpcStats.Npc npc, int defenceLevel, int magicLevel)
	{
		// magic is blocked with the magic level (a few monsters use defence), so lowered defence does not help magic
		boolean magicLevelBlocks = type == WeaponStyles.Type.MAGIC && !npc.hasRule("magic-uses-defence");
		int level = magicLevelBlocks ? magicLevel : defenceLevel;
		return (long) (level + 9) * (defenceBonus(type, npc) + 64);
	}

	private static int defenceBonus(WeaponStyles.Type type, NpcStats.Npc npc)
	{
		switch (type)
		{
			case STAB:
				return npc.stab;
			case SLASH:
				return npc.slash;
			case CRUSH:
				return npc.crush;
			case MAGIC:
				return npc.magic;
			case LIGHT:
				return npc.light;
			case STANDARD:
				return npc.standard;
			case HEAVY:
				return npc.heavy;
			default:
				return (npc.light + npc.standard + npc.heavy) / 3;
		}
	}

	static long attackRoll(PlayerState p, WeaponStyles.Style style, NpcStats.Npc npc)
	{
		WeaponStyles.Type type = style.type;
		String weapon = p.weaponName == null ? "" : p.weaponName.toLowerCase(Locale.ROOT);
		if (type == WeaponStyles.Type.MAGIC)
		{
			long level = p.magic * (100L + prayerPercent(p, MAGIC_PRAYERS, MAGIC_PERCENT)) / 100 + style.stanceBonus + 9;
			if (hasVoid(p, "void mage helm"))
			{
				level = level * 29 / 20;
			}
			long baseRoll = level * (magicBonus(p) + 64);
			return magicBoosts(p, npc, weapon, baseRoll) + elementalWeakness(p, npc, baseRoll);
		}
		boolean ranged = type.isRanged();
		long level = ranged
			? p.ranged * (100L + prayerPercent(p, RANGED_PRAYERS, RANGED_PERCENT)) / 100
			: p.attack * (100L + prayerPercent(p, MELEE_PRAYERS, MELEE_PERCENT)) / 100;
		level += style.stanceBonus + 8;
		if (hasVoid(p, ranged ? "void ranger helm" : "void melee helm"))
		{
			level = level * 11 / 10;
		}
		long baseRoll = level * (attackBonus(p, type) + 64);
		return ranged ? rangedBoosts(p, npc, weapon, baseRoll) : meleeBoosts(p, type, npc, weapon, baseRoll);
	}

	/*
	 * Gear that hits better, often only some monsters. In the order of the OSRS Wiki DPS calculator, as the
	 * rounding depends on it. A salve amulet, slayer helmet and amulet of avarice do not stack: one counts.
	 */

	private static long meleeBoosts(PlayerState p, WeaponStyles.Type type, NpcStats.Npc npc, String weapon,
		long baseRoll)
	{
		long roll = baseRoll;
		if (npc.name.startsWith("Revenant") && wears(p, "amulet of avarice"))
		{
			roll = roll * 24 / 20;
		}
		else if (npc.is("undead") && (wears(p, "salve amulet(ei)") || wears(p, "salve amulet (e)")))
		{
			roll = roll * 6 / 5;
		}
		else if (npc.is("undead") && wears(p, "salve amulet"))
		{
			roll = roll * 7 / 6;
		}
		else if (p.onTask && wearsSlayerHelmet(p, false))
		{
			roll = roll * 7 / 6;
		}
		if ((weapon.startsWith("tzhaar-") || weapon.startsWith("toktz-"))
			&& wears(p, "obsidian helmet") && wears(p, "obsidian platebody") && wears(p, "obsidian platelegs"))
		{
			roll += baseRoll / 10;
		}
		if (p.inWilderness && isChargedRevenantWeapon(weapon, type))
		{
			roll = roll * 3 / 2;
		}
		if (npc.is("demon"))
		{
			if (weapon.startsWith("arclight") || weapon.startsWith("emberlight"))
			{
				roll += roll * 70 / 100;
			}
			else if (weapon.startsWith("silverlight") || weapon.startsWith("darklight"))
			{
				roll += roll * 60 / 100;
			}
			else if (weapon.startsWith("bone claws") || weapon.startsWith("burning claws"))
			{
				roll += roll * 5 / 100;
			}
		}
		if (npc.is("dragon") && weapon.startsWith("dragon hunter lance"))
		{
			roll = roll * 6 / 5;
		}
		if (npc.is("kalphite") && weapon.startsWith("keris partisan of breaching"))
		{
			roll = roll * 133 / 100;
		}
		if (isVampyre(npc))
		{
			if (weapon.startsWith("blisterwood flail") || weapon.startsWith("blisterwood sickle"))
			{
				roll = roll * 105 / 100;
			}
			if (weapon.startsWith("hallowed flail") || weapon.startsWith("sunspear"))
			{
				roll = roll * 125 / 100;
			}
			if (wears(p, "efaritay's aid") && isSilverWeapon(weapon))
			{
				roll = roll * 23 / 20;
			}
		}
		if (npc.is("golem") && weapon.startsWith("granite hammer"))
		{
			roll = roll * 13 / 10;
		}
		if (type == WeaponStyles.Type.CRUSH)
		{
			int inquisitor = (wears(p, "inquisitor's great helm") ? 1 : 0) + (wears(p, "inquisitor's hauberk") ? 2 : 0)
				+ (wears(p, "inquisitor's plateskirt") ? 2 : 0);
			roll = roll * (200 + inquisitor) / 200;
		}
		return roll;
	}

	private static long rangedBoosts(PlayerState p, NpcStats.Npc npc, String weapon, long baseRoll)
	{
		long roll = baseRoll;
		if (weapon.startsWith("crystal bow") || weapon.contains("bow of faerdhinen"))
		{
			roll = roll * (20 + crystalArmourPieces(p)) / 20;
		}
		if (npc.name.startsWith("Revenant") && wears(p, "amulet of avarice"))
		{
			roll = roll * 24 / 20;
		}
		else if (npc.is("undead") && wears(p, "salve amulet(ei)"))
		{
			roll = roll * 6 / 5;
		}
		else if (npc.is("undead") && wears(p, "salve amulet(i)"))
		{
			roll = roll * 7 / 6;
		}
		else if (p.onTask && wearsSlayerHelmet(p, true))
		{
			roll = roll * 23 / 20;
		}
		if (weapon.startsWith("twisted bow"))
		{
			roll = roll * twistedBowPercent(npc) / 100;
		}
		if (p.inWilderness && isChargedRevenantWeapon(weapon, WeaponStyles.Type.STANDARD))
		{
			roll = roll * 3 / 2;
		}
		if (npc.is("dragon") && weapon.startsWith("dragon hunter crossbow"))
		{
			roll = roll * 13 / 10;
		}
		if (npc.is("demon") && weapon.startsWith("scorching bow"))
		{
			roll += roll * 30 / 100;
		}
		return roll;
	}

	private static long magicBoosts(PlayerState p, NpcStats.Npc npc, String weapon, long baseRoll)
	{
		// these percents add up before they multiply
		int percent = 0;
		boolean slayerHelmet = false;
		if (npc.name.startsWith("Revenant") && wears(p, "amulet of avarice"))
		{
			percent += 20;
		}
		else if (npc.is("undead") && wears(p, "salve amulet(ei)"))
		{
			percent += 20;
		}
		else if (npc.is("undead") && wears(p, "salve amulet(i)"))
		{
			percent += 15;
		}
		else
		{
			slayerHelmet = p.onTask && wearsSlayerHelmet(p, true);
		}
		if (p.standardSpellbook && (weapon.contains("smoke battlestaff") || weapon.startsWith("mystic smoke staff")
			|| weapon.startsWith("twinflame staff")))
		{
			percent += 10;
		}
		long roll = baseRoll * (100 + percent) / 100;
		if (npc.is("dragon"))
		{
			if (weapon.startsWith("dragon hunter crossbow"))
			{
				roll = roll * 13 / 10;
			}
			else if (weapon.startsWith("dragon hunter lance"))
			{
				roll = roll * 6 / 5;
			}
			else if (weapon.startsWith("dragon hunter wand"))
			{
				roll = roll * 7 / 4;
			}
		}
		if (slayerHelmet)
		{
			roll = roll * 23 / 20;
		}
		boolean demonbaneSpell = p.clickedSpell != null ? p.clickedSpell.contains("Demonbane") : p.autocastDemonbane;
		if (npc.is("demon") && demonbaneSpell)
		{
			int demonbane = p.markOfDarkness ? 40 : 20;
			if (weapon.startsWith("purging staff"))
			{
				demonbane *= 2;
			}
			roll += roll * demonbane / 100;
		}
		if (p.inWilderness && isChargedRevenantWeapon(weapon, WeaponStyles.Type.MAGIC))
		{
			roll = roll * 3 / 2;
		}
		String element = p.clickedSpell != null ? elementOf(p.clickedSpell) : p.autocastElement;
		if ("water".equals(element) && wears(p, "tome of water") && !wears(p, "tome of water (empty)"))
		{
			roll = roll * 6 / 5;
		}
		return roll;
	}

	/** A black mask or slayer helmet; only the imbued ones help ranged and magic. */
	private static boolean wearsSlayerHelmet(PlayerState p, boolean imbuedOnly)
	{
		for (String item : p.worn)
		{
			String name = item == null ? "" : item.toLowerCase(Locale.ROOT);
			if ((name.startsWith("black mask") || name.contains("slayer helmet")) && (!imbuedOnly || name.contains("(i)")))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isVampyre(NpcStats.Npc npc)
	{
		return npc.is("vampyre1") || npc.is("vampyre2") || npc.is("vampyre3");
	}

	private static boolean isSilverWeapon(String weapon)
	{
		for (String silver : new String[]{"silverlight", "darklight", "silver sickle", "rod of ivandis", "ivandis flail",
			"blisterwood", "hallowed", "sunspear"})
		{
			if (weapon.startsWith(silver))
			{
				return true;
			}
		}
		return false;
	}

	/** Tumeken's shadow triples the magic attack bonus of your gear (not for a spell you click). */
	private static int magicBonus(PlayerState p)
	{
		boolean shadow = p.weaponName != null && p.weaponName.toLowerCase(Locale.ROOT).startsWith("tumeken's shadow");
		return shadow && p.clickedSpell == null ? p.magicBonus * 3 : p.magicBonus;
	}

	/**
	 * A monster weak to an element: elemental spells (strike, bolt, blast, wave, surge) get its weakness
	 * percent of the attack roll on top, before gear boosts.
	 */
	private static long elementalWeakness(PlayerState p, NpcStats.Npc npc, long roll)
	{
		String element = p.clickedSpell != null ? elementOf(p.clickedSpell) : p.autocastElement;
		return element != null && element.equals(npc.weakElement) ? roll * npc.weaknessPercent / 100 : 0;
	}

	/** "fire" for "Fire Surge"; null for spells that are not elemental strikes, bolts, blasts, waves or surges. */
	public static String elementOf(String spell)
	{
		String[] words = spell.toLowerCase(Locale.ROOT).split(" ");
		if (words.length != 2 || !Arrays.asList("strike", "bolt", "blast", "wave", "surge").contains(words[1]))
		{
			return null;
		}
		switch (words[0])
		{
			case "wind":
				return "air";
			case "water":
			case "earth":
			case "fire":
				return words[0];
			default:
				return null;
		}
	}

	private static int attackBonus(PlayerState p, WeaponStyles.Type type)
	{
		switch (type)
		{
			case STAB:
				return p.stabBonus;
			case SLASH:
				return p.slashBonus;
			case CRUSH:
				return p.crushBonus;
			default:
				return p.rangedBonus;
		}
	}

	private static final String[] MELEE_PRAYERS = {"CLARITY_OF_THOUGHT", "IMPROVED_REFLEXES", "INCREDIBLE_REFLEXES",
		"CHIVALRY", "PIETY"};
	private static final int[] MELEE_PERCENT = {5, 10, 15, 15, 20};
	private static final String[] RANGED_PRAYERS = {"SHARP_EYE", "HAWK_EYE", "EAGLE_EYE", "DEADEYE", "RIGOUR"};
	private static final int[] RANGED_PERCENT = {5, 10, 15, 18, 20};
	private static final String[] MAGIC_PRAYERS = {"MYSTIC_WILL", "MYSTIC_LORE", "MYSTIC_MIGHT", "MYSTIC_VIGOUR",
		"AUGURY"};
	private static final int[] MAGIC_PERCENT = {5, 10, 15, 18, 25};

	private static int prayerPercent(PlayerState p, String[] prayers, int[] percents)
	{
		int best = 0;
		for (int i = 0; i < prayers.length; i++)
		{
			if (p.prayers.contains(prayers[i]))
			{
				best = Math.max(best, percents[i]);
			}
		}
		return best;
	}

	/** A full void set: the helm of this style, a top, a robe and gloves (elite counts too). */
	private static boolean hasVoid(PlayerState p, String helm)
	{
		return wears(p, helm) && (wears(p, "void knight top") || wears(p, "elite void top"))
			&& (wears(p, "void knight robe") || wears(p, "elite void robe")) && wears(p, "void knight gloves");
	}

	/** Wears an item whose name starts with this (so "(or)" and "(l)" versions count). */
	private static boolean wears(PlayerState p, String name)
	{
		for (String item : p.worn)
		{
			if (item != null && item.toLowerCase(Locale.ROOT).startsWith(name))
			{
				return true;
			}
		}
		return false;
	}


	/** Helm 1, legs 2, body 3 points; with a crystal bow each point adds 5%. */
	private static int crystalArmourPieces(PlayerState p)
	{
		return (wears(p, "crystal helm") ? 1 : 0) + (wears(p, "crystal legs") ? 2 : 0) + (wears(p, "crystal body") ? 3 : 0);
	}

	/** Revenant weapons with charges ("(u)" is uncharged) of your attack type. */
	private static boolean isChargedRevenantWeapon(String weapon, WeaponStyles.Type type)
	{
		if (weapon.endsWith("(u)"))
		{
			return false;
		}
		if (type.isRanged())
		{
			return weapon.startsWith("craw's bow") || weapon.startsWith("webweaver bow");
		}
		if (type == WeaponStyles.Type.MAGIC)
		{
			return weapon.startsWith("thammaron's sceptre") || weapon.startsWith("accursed sceptre");
		}
		return weapon.startsWith("viggora's chainmace") || weapon.startsWith("ursine chainmace");
	}



	/** The Twisted bow hits monsters with high magic better, up to 140%. */
	static int twistedBowPercent(NpcStats.Npc npc)
	{
		int magic = Math.min(250, Math.max(npc.magicLevel, npc.magicAttack));
		int bonus = (3 * magic - 10) / 100;
		int penalty = (3 * magic / 10 - 100) * (3 * magic / 10 - 100) / 100;
		return Math.min(140, 140 + bonus - penalty);
	}
}

package com.goldendps.model;

import java.util.Random;

/** Random hungry lines for the top healer: one line for a few seconds, then a pause. */
public class HungryTalk
{
	static final long SHOW_MS = 5000;
	static final long MIN_PAUSE_MS = 6000;
	static final long MAX_PAUSE_MS = 14000;

	static final String[] LINES = {
		"So hungry...",
		"Is that a shark?",
		"Anyone got fries?",
		"Nom nom nom",
		"I could eat a whole Vorkath",
		"Brb, eating",
		"Who ate my karambwan?",
		"One more burger won't hurt",
		"Snack time!",
		"Healing? I just love food",
	};

	private final Random random;
	private String line;
	private long showUntil;
	private long nextAt;

	public HungryTalk(Random random)
	{
		this.random = random;
	}

	/** The line to show now, or null during a pause. */
	public String line(long now)
	{
		if (now < showUntil)
		{
			return line;
		}
		if (now < nextAt)
		{
			return null;
		}
		String next;
		do
		{
			next = LINES[random.nextInt(LINES.length)];
		}
		while (next.equals(line));
		line = next;
		showUntil = now + SHOW_MS;
		nextAt = showUntil + MIN_PAUSE_MS + (long) (random.nextDouble() * (MAX_PAUSE_MS - MIN_PAUSE_MS));
		return line;
	}
}

package com.goldendps.model;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The kill counts the game tells you in the chat ("Your Vorkath kill count is: 123.",
 * "Your Barrows chest count is: 19.", "Your completed Chambers of Xeric count is: 21."),
 * so a report can add the KC of the kill it reports.
 */
public class KillCounts
{
	/** A count belongs to a fight that ended this close to the message. */
	static final long NEAR_MS = 30_000;

	private static final Pattern COUNT = Pattern.compile(
		"^Your (?:completed )?(.+?) (?:kill |chest |completion )?count is: ([\\d,]+)", Pattern.CASE_INSENSITIVE);

	/** Bosses whose kill count the game tells under another name. */
	private static final Map<String, String> COUNT_NAMES = new HashMap<>();

	static
	{
		COUNT_NAMES.put("dusk", "grotesque guardians");
		COUNT_NAMES.put("dawn", "grotesque guardians");
		COUNT_NAMES.put("branda the fire queen", "royal titans");
		COUNT_NAMES.put("eldric the ice king", "royal titans");
		COUNT_NAMES.put("blue moon", "lunar");
		COUNT_NAMES.put("eclipse moon", "lunar");
		COUNT_NAMES.put("blood moon", "lunar");
		COUNT_NAMES.put("crystalline hunllef", "gauntlet");
		COUNT_NAMES.put("corrupted hunllef", "corrupted gauntlet");
	}

	private static final class Count
	{
		final int value;
		final long atMs;

		Count(int value, long atMs)
		{
			this.value = value;
			this.atMs = atMs;
		}
	}

	private final Map<String, Count> counts = new HashMap<>();

	/** A game message. */
	public void message(long now, String text)
	{
		Matcher m = COUNT.matcher(ChatText.withoutTags(text));
		if (m.find())
		{
			int value = Integer.parseInt(m.group(2).replace(",", ""));
			counts.put(normalize(m.group(1)), new Count(value, now));
		}
	}

	/** Lower case without a leading "the": the game says "Nightmare" for The Nightmare. */
	private static String normalize(String name)
	{
		String n = name.toLowerCase(Locale.ROOT);
		return n.startsWith("the ") ? n.substring(4) : n;
	}

	/**
	 * The KC of this boss, raid or chest told close to {@code atMs}, or 0. Raid modes have their own
	 * count ("Tombs of Amascut: Expert Mode", "Chambers of Xeric Challenge Mode"), so a count whose
	 * name starts with the raid name also belongs to it.
	 */
	public int near(String name, long atMs)
	{
		if (name == null)
		{
			return 0;
		}
		String wanted = normalize(name);
		wanted = COUNT_NAMES.getOrDefault(wanted, wanted);
		for (Map.Entry<String, Count> e : counts.entrySet())
		{
			Count c = e.getValue();
			if (e.getKey().startsWith(wanted) && Math.abs(c.atMs - atMs) <= NEAR_MS)
			{
				return c.value;
			}
		}
		return 0;
	}
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Kills per hour in one session: every monster, every boss, and completions of every raid.
 * A rate runs from the start of the first kill until now, so it drops while you do something else.
 */
public final class KillRates
{
	public enum Kind
	{
		RAID,
		/** Barrows chests. */
		RUN,
		BOSS,
		MONSTER
	}

	/** One raid, boss or monster. */
	public static final class Rate
	{
		public final String name;
		public final Kind kind;
		public int kills;
		/** Kills per hour. */
		public double perHour;
		/** Average kill (or raid) time. */
		public long averageMs;
		long firstStartMs = Long.MAX_VALUE;
		long totalMs;

		Rate(String name, Kind kind)
		{
			this.name = name;
			this.kind = kind;
		}
	}

	private KillRates()
	{
	}

	/** Rates for the fights of one session: raids first, then bosses, then monsters, most kills first. */
	public static List<Rate> of(List<Fight> fights, long nowMs)
	{
		Map<String, Rate> rates = new LinkedHashMap<>();
		for (Fight f : fights)
		{
			if (f.mergedFights > 0)
			{
				continue;
			}
			if (f.isCompleteRaid())
			{
				add(rates, f.raid, f.run ? Kind.RUN : Kind.RAID, f.startMs, 1, f.durationMs(f.endMs));
			}
			BossRecords.Kill kill = BossRecords.kill(f);
			// Barrows brothers die once per chest: chests per hour says it
			if (kill != null && !BarrowsRun.isBrother(kill.boss))
			{
				add(rates, kill.boss, Kind.BOSS, f.startMs, 1, kill.timeMs);
			}
			if (f.partOf == null && !f.run)
			{
				addMonsters(rates, f);
			}
		}
		List<Rate> out = new ArrayList<>(rates.values());
		for (Rate r : out)
		{
			r.averageMs = r.totalMs / r.kills;
			r.perHour = r.kills * 3_600_000.0 / Math.max(1, nowMs - r.firstStartMs);
		}
		out.sort((a, b) -> a.kind != b.kind ? a.kind.compareTo(b.kind)
			: b.kills != a.kills ? Integer.compare(b.kills, a.kills) : a.name.compareTo(b.name));
		return out;
	}

	/** Non-boss NPCs you or your party fought that died. Raid boss fights are skipped: their raid has them. */
	private static void addMonsters(Map<String, Rate> rates, Fight f)
	{
		for (TargetStats t : f.targets.values())
		{
			if (!t.boss && t.engaged && t.killCount() > 0 && t.name != null && t.firstMs > 0)
			{
				add(rates, t.name, Kind.MONSTER, t.firstMs, t.killCount(), t.kills > 0 ? t.killTimeMs : t.lastKillTimeMs());
			}
		}
	}

	/** @param timeMs the time of all these kills together */
	private static void add(Map<String, Rate> rates, String name, Kind kind, long startMs, int kills, long timeMs)
	{
		Rate r = rates.computeIfAbsent(kind + "|" + name, k -> new Rate(name, kind));
		r.kills += kills;
		r.firstStartMs = Math.min(r.firstStartMs, startMs);
		r.totalMs += timeMs;
	}
}

