package com.goldendps.model;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.UnaryOperator;

/** Everything one player did in one fight. Plain fields for Gson. */
public class PlayerStats
{
	public String name;
	public PlayerKind kind;
	/** Damage per target key. */
	public Map<String, TargetDamage> byTarget = new LinkedHashMap<>();
	/** Guessed damage per target, used for {@link PlayerKind#ESTIMATE} players. */
	public Map<String, TargetDamage> estByTarget = new LinkedHashMap<>();
	/** Damage per source (weapon, special attack or spell), then per target key. */
	public Map<String, Map<String, TargetDamage>> bySource = new LinkedHashMap<>();
	public long damageTaken;
	/** Hitsplats seen on this player, used for {@link PlayerKind#ESTIMATE} players. */
	public long seenTaken;
	public long healFood;
	public long healLifesteal;
	public long healOther;
	/** Wasted food and potion healing. Lifesteal past full health is not counted: you cannot avoid it. */
	public long overFood;

	public PlayerStats()
	{
	}

	public PlayerStats(String name, PlayerKind kind)
	{
		this.name = name;
		this.kind = kind;
	}

	public void addHit(String targetKey, int amount, boolean miss)
	{
		addHit(targetKey, amount, miss, null);
	}

	public void addHit(String targetKey, int amount, boolean miss, String source)
	{
		byTarget.computeIfAbsent(targetKey, k -> new TargetDamage()).add(amount, miss);
		if (source != null && !source.isEmpty())
		{
			sources().computeIfAbsent(source, k -> new LinkedHashMap<>())
				.computeIfAbsent(targetKey, k -> new TargetDamage()).add(amount, miss);
		}
	}

	/** Never null; files saved by older versions have no sources. */
	public Map<String, Map<String, TargetDamage>> sources()
	{
		if (bySource == null)
		{
			bySource = new LinkedHashMap<>();
		}
		return bySource;
	}

	public void addEstimate(String targetKey, int amount, boolean miss)
	{
		estByTarget.computeIfAbsent(targetKey, k -> new TargetDamage()).add(amount, miss);
	}

	public Map<String, TargetDamage> damageByTarget()
	{
		return kind == PlayerKind.ESTIMATE ? estByTarget : byTarget;
	}

	public long takenTotal()
	{
		return kind == PlayerKind.ESTIMATE ? seenTaken : damageTaken;
	}

	public void addHeal(HealType type, int amount)
	{
		addHeal(type, amount, 0);
	}

	public void addHeal(HealType type, int amount, int overheal)
	{
		if (overheal > 0 && type == HealType.FOOD)
		{
			overFood += overheal;
		}
		if (amount <= 0)
		{
			return;
		}
		switch (type)
		{
			case FOOD:
				healFood += amount;
				break;
			case LIFESTEAL:
				healLifesteal += amount;
				break;
			case HEAL_OTHER:
				healOther += amount;
				break;
			default:
				break;
		}
	}

	public long overheal()
	{
		return overFood;
	}

	/** Healing without natural regeneration, which every player gets the same. */
	public long healing()
	{
		return healFood + healLifesteal + healOther;
	}

	public void merge(PlayerStats o)
	{
		merge(o, UnaryOperator.identity());
	}

	/** Adds {@code o} to this player, renaming target keys with {@code keyMap}. */
	public void merge(PlayerStats o, UnaryOperator<String> keyMap)
	{
		if (o.kind == PlayerKind.LOCAL || (o.kind == PlayerKind.PARTY && kind == PlayerKind.ESTIMATE))
		{
			kind = o.kind;
		}
		mergeTargets(byTarget, o.byTarget, keyMap);
		mergeTargets(estByTarget, o.estByTarget, keyMap);
		for (Map.Entry<String, Map<String, TargetDamage>> s : o.sources().entrySet())
		{
			mergeTargets(sources().computeIfAbsent(s.getKey(), k -> new LinkedHashMap<>()), s.getValue(), keyMap);
		}
		damageTaken += o.damageTaken;
		seenTaken += o.seenTaken;
		healFood += o.healFood;
		healLifesteal += o.healLifesteal;
		healOther += o.healOther;
		overFood += o.overFood;
	}

	private static void mergeTargets(Map<String, TargetDamage> into, Map<String, TargetDamage> from,
		UnaryOperator<String> keyMap)
	{
		for (Map.Entry<String, TargetDamage> e : from.entrySet())
		{
			into.computeIfAbsent(keyMap.apply(e.getKey()), k -> new TargetDamage()).merge(e.getValue());
		}
	}

	/** Drops the damage on every target that is not in {@code keys}. */
	public void keepTargets(Set<String> keys)
	{
		byTarget.keySet().retainAll(keys);
		estByTarget.keySet().retainAll(keys);
		for (Map<String, TargetDamage> s : sources().values())
		{
			s.keySet().retainAll(keys);
		}
		sources().values().removeIf(Map::isEmpty);
	}

	public PlayerStats copy()
	{
		PlayerStats c = new PlayerStats(name, kind);
		c.merge(this);
		c.kind = kind;
		return c;
	}
}

package com.goldendps.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Party for raids. Every member derives the same party name from data the game gives all of them
 * (the member names, or the CoX raid party id), so they all join the same RuneLite party
 * without exchanging anything. The party is left again when the raid party is gone, and a party
 * joined by hand is never changed.
 */
public class RaidParty
{
	/** The raid party must stay the same this long before it is joined (people join one by one). */
	public static final int STABLE_TICKS = 5;
	/**
	 * No raid party for this long outside a raid means the raid is over (short gaps happen while
	 * loading). Inside CoX the game clears the raid party id, so the party is kept there.
	 */
	public static final int LEAVE_TICKS = 10;
	public static final String PREFIX = "goldendps ";

	/** What to do with the RuneLite party this tick. */
	public static final class Action
	{
		public static final Action NONE = new Action(null, false);
		public static final Action LEAVE = new Action(null, true);

		/** The party to join, or null. */
		public final String join;
		public final boolean leave;

		private Action(String join, boolean leave)
		{
			this.join = join;
			this.leave = leave;
		}
	}

	private String candidate;
	private int stableTicks;
	private int ticksWithoutRaidParty;
	/**
	 * The last raid party the game showed. Inside a CoX raid the game clears it, so someone who
	 * restarts the client or leaves their own party there can still join the team from memory.
	 */
	private String remembered;

	/** Party name for a raid with a member list, or null when fewer than two names are known. */
	public static String partyName(String raid, int world, List<String> names)
	{
		List<String> clean = new ArrayList<>();
		for (String n : names)
		{
			if (n == null)
			{
				continue;
			}
			String c = ChatText.withoutTags(n.replace(' ', ' ')).trim().toLowerCase(Locale.ROOT);
			if (!c.isEmpty() && !clean.contains(c))
			{
				clean.add(c);
			}
		}
		if (clean.size() < 2)
		{
			return null;
		}
		clean.sort(null);
		return PREFIX + raid.toLowerCase(Locale.ROOT) + " " + hash(raid + "|" + world + "|" + String.join(",", clean));
	}

	/**
	 * Party name for Chambers of Xeric, from the raid party id (varp RAIDS_PARTY_GROUPHOLDER).
	 * Null without a party or when you are alone in it.
	 */
	public static String coxPartyName(int world, int partyId, int partySize)
	{
		if (partyId <= 0 || partySize == 1)
		{
			return null;
		}
		return PREFIX + "cox " + hash("CoX|" + world + "|" + partyId);
	}

	/** Your own party made outside raids (setting "Own party"). Never left here, a raid party may replace it. */
	public static final String OWN_PREFIX = PREFIX + "own ";

	/** A party GoldenDPS joined by itself: a raid party or your own party. */
	public static boolean isAuto(String party)
	{
		return party != null && party.startsWith(PREFIX);
	}

	public static boolean isOwn(String party)
	{
		return party != null && party.startsWith(OWN_PREFIX);
	}

	/**
	 * Call every game tick.
	 *
	 * @param shown        party name for the raid party the game shows you, or null
	 * @param currentParty the RuneLite party you are in, or null
	 * @param inRaid       you are inside a raid
	 */
	public Action tick(String shown, String currentParty, boolean inRaid)
	{
		if (shown != null)
		{
			remembered = shown;
		}
		String name = shown != null ? shown : inRaid ? remembered : null;
		boolean inAutoParty = isAuto(currentParty);
		boolean inRaidParty = inAutoParty && !isOwn(currentParty);
		if (name == null)
		{
			candidate = null;
			stableTicks = 0;
			ticksWithoutRaidParty = inRaid ? 0 : ticksWithoutRaidParty + 1;
			if (ticksWithoutRaidParty < LEAVE_TICKS)
			{
				return Action.NONE;
			}
			remembered = null;
			return inRaidParty && ticksWithoutRaidParty == LEAVE_TICKS ? Action.LEAVE : Action.NONE;
		}
		ticksWithoutRaidParty = 0;
		if (!name.equals(candidate))
		{
			candidate = name;
			stableTicks = 0;
		}
		stableTicks++;
		boolean manual = currentParty != null && !inAutoParty;
		if (manual || name.equals(currentParty) || stableTicks < STABLE_TICKS)
		{
			return Action.NONE;
		}
		return new Action(name, false);
	}

	/** The raid party kept in memory, to save it over a client restart; null without one. */
	public String getRemembered()
	{
		return remembered;
	}

	public void remember(String name)
	{
		remembered = name;
	}

	private static String hash(String s)
	{
		try
		{
			byte[] d = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < 8; i++)
			{
				sb.append(String.format("%02x", d[i] & 0xff));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			return Integer.toHexString(s.hashCode());
		}
	}
}

package com.goldendps.model;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** The CoX points the game tells at the end of a raid ("Total points: 31,408, Personal points: 31,408 (100%)"). */
public class RaidPoints
{
	private static final Pattern POINTS = Pattern.compile(
		"^Total points: ([\\d,]+), Personal points: ([\\d,]+)");

	private long total;
	private long personal;
	private long atMs;

	/** A game message. */
	public void message(long now, String text)
	{
		Matcher m = POINTS.matcher(ChatText.withoutTags(text));
		if (m.find())
		{
			total = Long.parseLong(m.group(1).replace(",", ""));
			personal = Long.parseLong(m.group(2).replace(",", ""));
			atMs = now;
		}
	}

	/** "31,408 pts", or "12,000 of 31,408 pts" in a group; null when none were told close to {@code atMs}. */
	public String near(long atMs)
	{
		if (this.atMs == 0 || Math.abs(this.atMs - atMs) > KillCounts.NEAR_MS)
		{
			return null;
		}
		return personal == total ? exact(total) + " pts" : exact(personal) + " of " + exact(total) + " pts";
	}

	/** Points are shown exactly, as the game does: 31,408 (not 31.4k). */
	private static String exact(long points)
	{
		return String.format(Locale.US, "%,d", points);
	}
}

package com.goldendps.model;

import java.util.HashMap;
import java.util.Map;

/**
 * Knows when you are inside a raid (by the map region of the raid instance), so the meter can
 * make one fight for the whole raid. Regions are the same as RuneLite's Discord plugin uses.
 */
public class RaidZone
{
	/** Not in the raid for this many ticks = you left (loading between rooms is shorter). */
	public static final int LEAVE_TICKS = 5;

	public static final String COX = "Chambers of Xeric";
	public static final String TOB = "Theatre of Blood";
	public static final String TOA = "Tombs of Amascut";
	public static final String TFA = "The Fractured Archive";

	private static final Map<Integer, String> REGIONS = new HashMap<>();

	static
	{
		put(COX, 12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
		put(TOB, 12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
		put(TOA, 14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);
		put(TFA, 16214, 16726, 16215, 16727, 16216, 16728, 16472, 16474);
	}

	private static void put(String raid, int... regions)
	{
		for (int r : regions)
		{
			REGIONS.put(r, raid);
		}
	}

	/** The raid this instance region belongs to, or null. */
	public static String raidFor(int region, boolean instance)
	{
		return instance ? REGIONS.get(region) : null;
	}

	/** What the tracker should do this tick. */
	public static final class Change
	{
		public static final Change NONE = new Change(null, false);

		/** Raid that started now, or null. */
		public final String start;
		public final boolean end;

		Change(String start, boolean end)
		{
			this.start = start;
			this.end = end;
		}
	}

	private String inside;
	private int outTicks;

	/** Call every game tick with {@link #raidFor} of where you are now. */
	public Change tick(String raidNow)
	{
		if (raidNow != null)
		{
			outTicks = 0;
			if (raidNow.equals(inside))
			{
				return Change.NONE;
			}
			inside = raidNow;
			return new Change(raidNow, false);
		}
		if (inside != null && ++outTicks >= LEAVE_TICKS)
		{
			inside = null;
			outTicks = 0;
			return new Change(null, true);
		}
		return Change.NONE;
	}

	public String getInside()
	{
		return inside;
	}

	public void reset()
	{
		inside = null;
		outTicks = 0;
	}
}

package com.goldendps.model;

import java.util.ArrayList;
import java.util.List;

/**
 * Builds a short report of a fight, one chat line per player:
 * <pre>
 * Boss damage - Vorkath 1:23 - total 27.4k (330.1/s)
 * 1. Kurt Yoghurt 12.3k 148.2/s 45%
 * 2. Zezima 9.1k 109.6/s 33%
 * </pre>
 * Every line fits in one RuneLite party chat message.
 */
public final class ReportFormatter
{
	/** RuneLite party chat cuts messages at 150 characters; stay below that. */
	public static final int MAX_LINE = 140;
	public static final int DEFAULT_TOP = 5;

	private ReportFormatter()
	{
	}

	/**
	 * @param report the fight to report
	 * @param mode   what to report (damage, DPS, healing, damage taken)
	 * @param title  what the fight is called ("Vorkath", "Session")
	 * @param top    how many players
	 * @return the lines to send, header first; only the header when there is nothing to report
	 */
	public static List<String> lines(FightReport report, MeterMode mode, String title, int top)
	{
		return lines(report, mode, mode.getLabel(), title, top);
	}

	/** @param label what the header calls the report ("Boss damage", "Healing") */
	public static List<String> lines(FightReport report, MeterMode mode, String label, String title, int top)
	{
		return lines(report, mode, label, title, top, false);
	}

	/**
	 * @param withKills the header gives the kills instead of the DPS: over many monsters
	 *                  ("Overall damage") the kills say more than a DPS with walking in it
	 */
	public static List<String> lines(FightReport report, MeterMode mode, String label, String title, int top,
		boolean withKills)
	{
		List<String> out = new ArrayList<>();
		List<FightReport.PlayerRow> rows = report.sorted(mode);
		double total = report.total(mode);

		StringBuilder header = new StringBuilder(label);
		if (title != null && !title.isEmpty())
		{
			header.append(" - ").append(title);
		}
		header.append(' ').append(Format.preciseDuration(report.getDurationMs()));
		if (!rows.isEmpty())
		{
			header.append(" - total ").append(withKills ? killsText(report, mode, total) : totalText(report, mode, total));
		}
		out.add(cut(header.toString()));
		if (report.isSolo())
		{
			// the header already has your total and DPS
			return out;
		}

		int n = Math.min(Math.max(1, top), rows.size());
		for (int i = 0; i < n; i++)
		{
			FightReport.PlayerRow row = rows.get(i);
			String name = (row.isEstimate() ? "~" : "") + row.name;
			out.add(cut((i + 1) + ". " + name + " " + valueText(row, mode, total)));
		}
		return out;
	}

	private static String killsText(FightReport report, MeterMode mode, double total)
	{
		int kills = report.getKills();
		String amount = Format.amount(mode == MeterMode.DPS ? report.getTotalDamage() : total);
		return kills == 0 ? amount : amount + " - " + kills + (kills == 1 ? " kill" : " kills");
	}

	private static String totalText(FightReport report, MeterMode mode, double total)
	{
		switch (mode)
		{
			case DAMAGE:
			case DPS:
				return Format.amount(report.getTotalDamage()) + " (" + Format.dps(report.getGroupDps()) + "/s)";
			case HEALING:
				double oh = report.groupOverhealPercent();
				return Format.amount(total) + (oh > 0 ? " OH " + Format.percent(oh) : "");
			default:
				return Format.amount(total);
		}
	}

	private static String valueText(FightReport.PlayerRow row, MeterMode mode, double total)
	{
		double v = FightReport.value(row, mode);
		String share = Format.percent(total <= 0 ? 0 : 100.0 * v / total);
		switch (mode)
		{
			case DAMAGE:
				return Format.amount(row.damage) + " " + Format.dps(row.dps) + "/s " + Format.percent(row.percent);
			case DPS:
				return Format.dps(row.dps) + "/s " + Format.amount(row.damage) + " " + Format.percent(row.percent);
			case HEALING:
				return Format.amount(v) + (row.overheal > 0 ? " OH " + Format.percent(row.overhealPercent()) : "") + " " + share;
			default:
				return Format.amount(v) + " " + share;
		}
	}

	private static String cut(String s)
	{
		return s.length() <= MAX_LINE ? s : s.substring(0, MAX_LINE);
	}
}

package com.goldendps.model;

import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/** Short names for the compact meter: two letters, more where two players would look the same. */
public final class ShortNames
{
	private static final int LETTERS = 2;

	private ShortNames()
	{
	}

	/** "Franz" and "Bob" give "Fr" and "Bo"; "Franz" and "Frank" grow until they differ: "Franz", "Frank". */
	public static Map<String, String> of(Collection<String> names)
	{
		Map<String, Integer> length = new HashMap<>();
		names.forEach(n -> length.put(n, LETTERS));
		boolean grew = true;
		while (grew)
		{
			grew = false;
			Map<String, List<String>> byShort = names.stream().distinct()
				.collect(Collectors.groupingBy(n -> cut(n, length.get(n))));
			for (List<String> same : byShort.values())
			{
				if (same.size() < 2)
				{
					continue;
				}
				for (String n : same)
				{
					if (length.get(n) < n.length())
					{
						length.put(n, length.get(n) + 1);
						grew = true;
					}
				}
			}
		}
		Map<String, String> out = new HashMap<>();
		names.forEach(n -> out.put(n, cut(n, length.get(n))));
		return out;
	}

	private static String cut(String name, int letters)
	{
		return name.substring(0, Math.min(letters, name.length()));
	}
}

package com.goldendps.model;

import java.util.Locale;

/**
 * The Soulreaper axe's soul stacks: one per attack (hit or miss), at most five; one is lost every 50 ticks
 * without an attack; its special attack (Behead) uses them all, for 12% more accuracy each. Client thread only.
 */
public class SoulreaperStacks
{
	static final int MAX_STACKS = 5;
	static final int DECAY_TICKS = 50;

	private int stacks;
	private int lastChangeTick;

	/**
	 * You attacked.
	 * @param spec it was the special attack, which uses all stacks
	 */
	public void attack(int tick, String weapon, boolean spec)
	{
		decay(tick);
		if (weapon == null || !weapon.toLowerCase(Locale.ROOT).startsWith("soulreaper axe"))
		{
			return;
		}
		stacks = spec ? 0 : Math.min(MAX_STACKS, stacks + 1);
		lastChangeTick = tick;
	}

	public int stacks(int tick)
	{
		decay(tick);
		return stacks;
	}

	private void decay(int tick)
	{
		while (stacks > 0 && tick - lastChangeTick >= DECAY_TICKS)
		{
			stacks--;
			lastChangeTick += DECAY_TICKS;
		}
	}
}

package com.goldendps.model;

/** One player's damage on one target. */
public class TargetDamage
{
	public long damage;
	public int hits;
	public int misses;
	public int biggestHit;

	public void add(int amount, boolean miss)
	{
		if (miss || amount <= 0)
		{
			misses++;
			return;
		}
		hits++;
		damage += amount;
		biggestHit = Math.max(biggestHit, amount);
	}

	public void merge(TargetDamage o)
	{
		damage += o.damage;
		hits += o.hits;
		misses += o.misses;
		biggestHit = Math.max(biggestHit, o.biggestHit);
	}

	public TargetDamage copy()
	{
		TargetDamage c = new TargetDamage();
		c.merge(this);
		return c;
	}
}

package com.goldendps.model;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Decides if a party member's target is the same NPC as yours.
 *
 * <p>NPC numbers (index) are only unique inside one world or instance. Two party
 * members in different instances on the same world (for example each doing their
 * own Vorkath) can have NPCs with the same number. So we also compare where the NPC
 * is: every instance has its own map coordinates, far away from the others.</p>
 */
public class TargetMatcher
{
	/** Same NPC if it is this close (tiles) to where we last saw it. NPCs move between ticks. */
	static final int MAX_DISTANCE = 15;
	private static final int MAX_REMEMBERED = 512;

	private final Map<String, int[]> lastSeen = new LinkedHashMap<String, int[]>(64, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, int[]> eldest)
		{
			return size() > MAX_REMEMBERED;
		}
	};

	public static String key(int world, int npcIndex)
	{
		return world + ":" + npcIndex;
	}

	/** Remember where an NPC near you is (call on hitsplats and when checking party hits). */
	public void seen(String key, int x, int y, int plane)
	{
		lastSeen.put(key, new int[]{x, y, plane});
	}

	/**
	 * Target key for a party member's hit. Your own key when it is the same NPC as yours,
	 * else a separate key for that member (so it never mixes with your targets).
	 */
	public String partyKey(int myWorld, int world, int npcIndex, int x, int y, int plane, String sender)
	{
		String key = key(world, npcIndex);
		if (world == myWorld)
		{
			int[] p = lastSeen.get(key);
			if (p != null && p[2] == plane && Math.abs(p[0] - x) <= MAX_DISTANCE && Math.abs(p[1] - y) <= MAX_DISTANCE)
			{
				return key;
			}
		}
		return "p:" + sender + ":" + key;
	}

	public void clear()
	{
		lastSeen.clear();
	}
}

package com.goldendps.model;

/** One NPC in a fight, keyed by "world:npcIndex" (the same on every client in that world). */
public class TargetStats
{
	public String key;
	public int npcId;
	public String name;
	public boolean boss;
	/** All damage hitsplats seen on the NPC. */
	public long seenDamage;
	/** Poison, venom, burn and bleed damage. */
	public long effectDamage;
	/** Hit by you or a party member; only these count towards unknown damage. */
	public boolean engaged;
	public boolean died;
	public long firstMs;
	public long lastMs;
	public long diedMs;
	/**
	 * A monster that respawns at the same place gets the same key, so one target can die many times.
	 * Old saved fights have 0 here: see killCount().
	 */
	public int kills;
	/** Sum of the kill times, each from the first hit on that NPC to its death. */
	public long killTimeMs;
	/** First hit on the NPC that is at this key now. */
	public long lifeStartMs;

	public TargetStats()
	{
	}

	public TargetStats(String key, int npcId, String name, boolean boss)
	{
		this.key = key;
		this.npcId = npcId;
		this.name = name;
		this.boss = boss;
	}

	/** Hit by you or a party member. */
	public void hitAt(long now)
	{
		engaged = true;
		// a party report can come a little after the death; a real respawn takes longer
		if (died && now - diedMs > FightTracker.LATE_REPORT_MS)
		{
			died = false;
			lifeStartMs = now;
		}
		if (firstMs == 0)
		{
			firstMs = now;
			lifeStartMs = now;
		}
		lastMs = Math.max(lastMs, now);
	}

	public void diedAt(long now)
	{
		if (died)
		{
			return;
		}
		died = true;
		diedMs = now;
		kills++;
		killTimeMs += lastKillTimeMs();
	}

	public int killCount()
	{
		return kills > 0 ? kills : died ? 1 : 0;
	}

	/** Time of the last kill, 0 if unknown. */
	public long lastKillTimeMs()
	{
		long start = lifeStartMs > 0 ? lifeStartMs : firstMs;
		return died && start > 0 && diedMs >= start ? diedMs - start : 0;
	}

	public void merge(TargetStats o)
	{
		seenDamage += o.seenDamage;
		effectDamage += o.effectDamage;
		engaged |= o.engaged;
		died |= o.died;
		boss |= o.boss;
		if (o.firstMs > 0 && (firstMs == 0 || o.firstMs < firstMs))
		{
			firstMs = o.firstMs;
		}
		lastMs = Math.max(lastMs, o.lastMs);
		diedMs = Math.max(diedMs, o.diedMs);
		kills += o.kills;
		killTimeMs += o.killTimeMs;
		lifeStartMs = Math.max(lifeStartMs, o.lifeStartMs);
	}

	public TargetStats copy()
	{
		TargetStats c = new TargetStats(key, npcId, name, boss);
		c.merge(this);
		return c;
	}
}

package com.goldendps.model;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * The attack styles of each weapon category (the buttons in the combat tab), and the category of each
 * weapon, from weapon_categories.tsv (made from the OSRS Wiki).
 */
public class WeaponStyles
{
	/** What you attack with, and so which defence bonus of the monster blocks it. */
	public enum Type
	{
		STAB, SLASH, CRUSH, MAGIC,
		/** Ranged: darts, knives, thrown weapons. */
		LIGHT,
		/** Ranged: bows and arrows. */
		STANDARD,
		/** Ranged: crossbows, ballistae, chinchompas. */
		HEAVY,
		/** Ranged: salamanders, the average of the three. */
		MIXED;

		public boolean isRanged()
		{
			return this == LIGHT || this == STANDARD || this == HEAVY || this == MIXED;
		}

		public boolean isMelee()
		{
			return this == STAB || this == SLASH || this == CRUSH;
		}
	}

	/** One attack style. */
	public static final class Style
	{
		public final Type type;
		/** The hidden level bonus of the stance: +3 accurate, +1 controlled, +2 accurate on powered staves. */
		public final int stanceBonus;

		Style(Type type, int stanceBonus)
		{
			this.type = type;
			this.stanceBonus = stanceBonus;
		}
	}

	/** A spell you click by hand: no stance bonus. */
	public static final Style CLICKED_SPELL = new Style(Type.MAGIC, 0);

	private static final String UNARMED = "unarmed";
	/** Category to its styles, by the slot of the style in the combat tab ("-" = no style there). */
	private static final Map<String, Style[]> STYLES = new HashMap<>();

	static
	{
		// slot 4 of staves is autocast; a style with three buttons leaves slot 2 empty
		add("2h sword", "slash+3 slash crush slash");
		add("axe", "slash+3 slash crush slash");
		add("banner", "stab+3 slash crush+1 stab");
		add("bladed staff", "stab+3 slash - crush magic");
		add("bludgeon", "crush crush - crush");
		add("blunt", "crush+3 crush - crush");
		add("bulwark", "crush+3");
		add("claw", "slash+3 slash stab+1 slash");
		add("extending chain mace", "crush+3 crush - crush");
		add("flail", "slash+3 slash - slash");
		add("multi-melee", "stab+3 slash crush slash");
		add("partisan", "stab+3 stab crush stab");
		add("pickaxe", "stab+3 stab crush stab");
		add("polearm", "stab+1 slash - stab");
		add("polestaff", "crush+3 crush - crush");
		add("powered book", "magic+2 magic+2 - magic");
		add("powered staff", "magic+2 magic+2 - magic");
		add("powered wand", "magic+2 magic+2 - magic");
		add("scythe", "slash+3 slash crush slash");
		add("slash sword", "slash+3 slash stab+1 slash");
		add("spear", "stab+1 slash+1 crush+1 stab");
		add("spiked", "crush+3 crush stab+1 crush");
		add("staff", "crush+3 crush - crush magic");
		add("stab sword", "stab+3 stab slash stab");
		add(UNARMED, "crush+3 crush - crush");
		add("whip", "slash+3 slash+1 - slash");
		add("thrown", "light+3 light - light");
		add("bow", "standard+3 standard - standard");
		add("crossbow", "heavy+3 heavy - heavy");
		add("chinchompas", "heavy+3 heavy - heavy");
		add("salamander", "slash mixed - magic");
	}

	private static void add(String category, String styles)
	{
		String[] slots = styles.split(" ");
		Style[] parsed = new Style[slots.length];
		for (int i = 0; i < slots.length; i++)
		{
			if (!slots[i].equals("-"))
			{
				String[] typeAndBonus = slots[i].split("\\+");
				int bonus = typeAndBonus.length > 1 ? Integer.parseInt(typeAndBonus[1]) : 0;
				parsed[i] = new Style(Type.valueOf(typeAndBonus[0].toUpperCase(Locale.ROOT)), bonus);
			}
		}
		STYLES.put(category, parsed);
	}

	private final Map<Integer, String> categoryById = new HashMap<>();
	private final Map<String, String> categoryByName = new HashMap<>();

	/** @param lines the lines of weapon_categories.tsv */
	public WeaponStyles(List<String> lines)
	{
		for (String line : lines)
		{
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] cells = line.split("\t", -1);
			String category = cells[2].toLowerCase(Locale.ROOT);
			categoryById.put(Integer.parseInt(cells[0]), category);
			categoryByName.putIfAbsent(cells[1].toLowerCase(Locale.ROOT), category);
		}
	}

	/** The weapons of weapon_categories.tsv, which ships inside the plugin. */
	public static WeaponStyles load() throws IOException
	{
		try (InputStream in = WeaponStyles.class.getResourceAsStream("/com/goldendps/weapon_categories.tsv"))
		{
			if (in == null)
			{
				throw new IOException("weapon_categories.tsv is missing");
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			return new WeaponStyles(reader.lines().collect(Collectors.toList()));
		}
	}

	/**
	 * The style you attack with, or null when it is not known.
	 * @param weaponName null when you hold no weapon
	 * @param slot the selected style in the combat tab (0-3, 4 for autocast)
	 */
	public Style style(int weaponId, String weaponName, int slot)
	{
		String category = weaponName == null ? UNARMED : categoryById.get(weaponId);
		if (category == null)
		{
			category = categoryByName.get(weaponName.toLowerCase(Locale.ROOT));
		}
		Style[] styles = category == null ? null : STYLES.get(category);
		return styles == null || slot < 0 || slot >= styles.length ? null : styles[slot];
	}
}

