	public void bossesByIdAndName()
	{
		Bosses b = new Bosses();
		assertTrue(b.isBoss(net.runelite.api.gameval.NpcID.VORKATH, "Vorkath"));
		assertTrue(b.isBoss(-1, "Duke Sucellus"));
		assertFalse(b.isBoss(-1, "Goblin"));
		assertFalse(b.isBoss(-1, null));
	}
}

