		assertNull("too late for this kill",
			tracker.gameTime(43_000 + FightTracker.GAME_TIME_NEAR_MS + 1, GameTimes.parse("Fight duration: 0:30.00")));
		assertEquals(42_600, f.bossDurationMs(0));
