package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class HealthWatcherTest
{
	private HealthWatcher w;

	@Before
	public void setUp()
	{
		w = new HealthWatcher();
		w.hpChanged(50); // first value only sets the start
		assertTrue(w.endTick(0).isEmpty());
	}

	private void assertHeal(List<HealthWatcher.Heal> heals, HealType type, int amount)
	{
		assertHeal(heals, type, amount, 0);
	}

	private void assertHeal(List<HealthWatcher.Heal> heals, HealType type, int amount, int overheal)
	{
		assertEquals(heals.toString(), 1, heals.size());
		assertEquals(type, heals.get(0).type);
		assertEquals(amount, heals.get(0).amount);
		assertEquals("overheal", overheal, heals.get(0).overheal);
	}

	/** New watcher at this HP, max HP 99. */
	private HealthWatcher at(int hp)
	{
		HealthWatcher h = new HealthWatcher();
		h.setMaxHp(99);
		h.hpChanged(hp);
		h.endTick(0);
		return h;
	}

	// ---- overhealing: food ----

	@Test
	public void sharkAtFullHpIsAllOverheal()
	{
		HealthWatcher h = at(99);
		h.foodEaten(10, 20, 0);
		assertTrue("wait for the HP update", h.endTick(10).isEmpty());
		assertTrue(h.endTick(11).isEmpty());
		assertHeal(h.endTick(12), HealType.FOOD, 0, 20);
	}

	@Test
	public void sharkPartlyWasted()
	{
		HealthWatcher h = at(90);
		h.foodEaten(10, 20, 0);
		h.hpChanged(99);
		assertHeal(h.endTick(10), HealType.FOOD, 9, 11);
	}

	@Test
	public void sharkFullyUsedHasNoOverheal()
	{
		HealthWatcher h = at(50);
		h.foodEaten(10, 20, 0);
		h.hpChanged(70);
		assertHeal(h.endTick(10), HealType.FOOD, 20, 0);
	}

	@Test
	public void hpUpdateOneTickLater()
	{
		HealthWatcher h = at(90);
		h.foodEaten(10, 20, 0);
		assertTrue(h.endTick(10).isEmpty());
		h.hpChanged(99);
		assertHeal(h.endTick(11), HealType.FOOD, 9, 11);
	}

	@Test
	public void brewAboveMaxWastesOnlyAboveItsCap()
	{
		HealthWatcher h = at(110);
		h.foodEaten(10, 16, 16); // cap = 99 + 16 = 115
		h.hpChanged(115);
		assertHeal(h.endTick(10), HealType.FOOD, 5, 11);
	}

	@Test
	public void brewBelowItsCapHasNoOverheal()
	{
		HealthWatcher h = at(98);
		h.foodEaten(10, 16, 16);
		h.hpChanged(114);
		assertHeal(h.endTick(10), HealType.FOOD, 16, 0);
	}

	@Test
	public void karambwanWhileBrewBoostedIsWasted()
	{
		HealthWatcher h = at(105);
		h.foodEaten(10, 18, 0);
		h.endTick(10);
		h.endTick(11);
		assertHeal(h.endTick(12), HealType.FOOD, 0, 18);
	}

	@Test
	public void comboEatSharkAndKarambwan()
	{
		HealthWatcher h = at(70);
		h.foodEaten(10, 20, 0);
		h.foodEaten(10, 18, 0);
		h.hpChanged(99);
		assertHeal(h.endTick(10), HealType.FOOD, 29, 9);
	}

	@Test
	public void unknownFoodHasNoOverheal()
	{
		HealthWatcher h = at(50);
		h.foodEaten(10, HealTable.UNKNOWN, 0);
		h.hpChanged(57);
		assertHeal(h.endTick(10), HealType.FOOD, 7, 0);

		HealthWatcher full = at(99);
		full.foodEaten(10, HealTable.UNKNOWN, 0);
		full.endTick(10);
		full.endTick(11);
		assertTrue(full.endTick(12).isEmpty());
	}

	@Test
	public void eatAndGetHitSameTickWithOverheal()
	{
		HealthWatcher h = at(90);
		h.foodEaten(10, 20, 0);
		h.damageOnMe(10);
		h.hpChanged(89); // healed to 99 (9 used), then hit for 10
		// effective 9 is right; HP did not end at the cap, so no overheal is counted (we can't be sure)
		assertHeal(h.endTick(10), HealType.FOOD, 9, 0);
	}

	// ---- overhealing: lifesteal ----

	@Test
	public void sanguinestiProcAtFullHpIsAllOverheal()
	{
		HealthWatcher h = at(99);
		h.myHit(20);
		h.lifesteal(20, 15, 0);
		assertTrue(h.endTick(20).isEmpty());
		assertHeal(h.endTick(21), HealType.LIFESTEAL, 0, 15);
	}

	@Test
	public void sanguinestiPartlyWasted()
	{
		HealthWatcher h = at(95);
		h.myHit(20);
		h.lifesteal(20, 15, 0);
		h.hpChanged(99);
		assertHeal(h.endTick(20), HealType.LIFESTEAL, 4, 11);
	}

	@Test
	public void bloodSpellNotCappedHasNoOverheal()
	{
		HealthWatcher h = at(50);
		h.myHit(20);
		h.lifesteal(20, 12, 0);
		h.hpChanged(60); // table said 12, game gave 10: not capped, so no waste
		assertHeal(h.endTick(20), HealType.LIFESTEAL, 10, 0);
	}

	@Test
	public void bloodSceptreCanHealAboveMax()
	{
		HealthWatcher h = at(99);
		h.myHit(20);
		h.lifesteal(20, 30, 9); // cap 108
		h.hpChanged(108);
		assertHeal(h.endTick(20), HealType.LIFESTEAL, 9, 21);
	}

	@Test
	public void foodAndLifestealSameTick()
	{
		HealthWatcher h = at(60);
		h.myHit(20);
		h.foodEaten(20, 20, 0);
		h.lifesteal(20, 10, 0);
		h.hpChanged(90);
		List<HealthWatcher.Heal> heals = h.endTick(20);
		assertEquals(heals.toString(), 2, heals.size());
		assertEquals(HealType.FOOD, heals.get(0).type);
		assertEquals(20, heals.get(0).amount);
		assertEquals(HealType.LIFESTEAL, heals.get(1).type);
		assertEquals(10, heals.get(1).amount);
	}

	@Test
	public void eatingIsFood()
	{
		w.consumed(10);
		w.hpChanged(70);
		assertHeal(w.endTick(11), HealType.FOOD, 20);
	}

	@Test
	public void foodWindowEndsAfterTwoTicks()
	{
		w.consumed(10);
		w.hpChanged(70);
		assertHeal(w.endTick(13), HealType.RECEIVED, 20);
	}

	@Test
	public void healWhenIHitIsLifesteal()
	{
		w.myHit(20);
		w.hpChanged(58);
		assertHeal(w.endTick(20), HealType.LIFESTEAL, 8);
	}

	@Test
	public void smallHealWithoutReasonIsRegen()
	{
		w.hpChanged(51);
		assertHeal(w.endTick(30), HealType.REGEN, 1);
	}

	@Test
	public void bigHealWithoutReasonIsReceived()
	{
		w.hpChanged(80);
		assertHeal(w.endTick(30), HealType.RECEIVED, 30);
	}

	@Test
	public void eatAndGetHitInTheSameTick()
	{
		w.consumed(40);
		w.damageOnMe(15);
		w.hpChanged(55); // +20 food, -15 hit
		assertHeal(w.endTick(40), HealType.FOOD, 20);
	}

	@Test
	public void plainHitIsNoHeal()
	{
		w.damageOnMe(15);
		w.hpChanged(35);
		assertTrue(w.endTick(40).isEmpty());
	}

	@Test
	public void healOtherIsTheHpIGaveAway()
	{
		w.healOtherCast(50);
		w.hpChanged(13); // gave 37 hp
		assertHeal(w.endTick(52), HealType.HEAL_OTHER, 37);
		// only once per cast
		w.hpChanged(10);
		assertTrue(w.endTick(53).isEmpty());
	}

	@Test
	public void hpDropLongAfterCastIsNotHealOther()
	{
		w.healOtherCast(50);
		w.hpChanged(13);
		assertTrue(w.endTick(50 + HealthWatcher.HEAL_OTHER_TICKS + 1).isEmpty());
	}

	@Test
	public void resetForgetsOldHp()
	{
		w.reset();
		w.hpChanged(99);
		assertTrue(w.endTick(60).isEmpty());
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import net.runelite.client.util.Filepath;

public class HistoryStoreTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Fight sampleFight()
	{
		FightTracker t = new FightTracker();
		t.playerHit(0, "Me", PlayerKind.LOCAL, "301:5", 8059, "Vorkath", true, 44, false);
		t.seenHit(0, "301:5", 8059, "Vorkath", true, 44);
		t.playerHit(600, "Friend", PlayerKind.PARTY, "301:5", 8059, "Vorkath", true, 30, false);
		t.seenHit(600, "301:5", 8059, "Vorkath", true, 30);
		t.seenHit(1200, "301:5", 8059, "Vorkath", true, 12);
		t.heal(1200, "Me", PlayerKind.LOCAL, HealType.FOOD, 22);
		t.damageTaken(1200, "Me", PlayerKind.LOCAL, 9);
		t.npcDied(3000, "301:5", true);
		return t.getHistory().get(0);
	}

	/** Tests only: the plugin gets its folder from RuneLite (Plugin.getPluginDirectory). */
	private static Filepath rooted(Path dir)
	{
		return Filepath.Unchecked.getRooted(dir);
	}

	@Test
	public void saveAndLoadGivesTheSameNumbers() throws Exception
	{
		Path dir = folder.getRoot().toPath().resolve("goldendps");
		HistoryStore store = new HistoryStore(new Gson(), rooted(dir));
		store.save(12345L, Collections.singletonList(sampleFight()), 1000);

		assertTrue(Files.exists(dir.resolve("12345.json")));
		assertFalse("temp file is gone", Files.exists(dir.resolve("12345.json.tmp")));

		List<Fight> loaded = store.load(12345L);
		assertEquals(1, loaded.size());
		FightReport r = FightReport.of(loaded.get(0), false, 0);
		assertEquals(44, r.row("Me").damage);
		assertEquals(30, r.row("Friend").damage);
		assertEquals(12, r.row(FightReport.UNKNOWN_NAME).damage);
		assertEquals(22, r.row("Me").healing);
		assertEquals(9, r.row("Me").damageTaken);
		assertEquals(PlayerKind.LOCAL, r.row("Me").kind);
		assertEquals(3000, loaded.get(0).durationMs(0));
		assertEquals("Vorkath", loaded.get(0).title());
	}

	@Test
	public void accountsHaveTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		store.save(1L, Collections.singletonList(sampleFight()), 0);
		assertEquals(1, store.load(1L).size());
		assertTrue(store.load(2L).isEmpty());
	}

	@Test
	public void brokenFileIsKeptAndHistoryStartsEmpty() throws Exception
	{
		Path dir = folder.getRoot().toPath();
		Files.write(dir.resolve("7.json"), "{ not json".getBytes(StandardCharsets.UTF_8));
		HistoryStore store = new HistoryStore(new Gson(), rooted(dir));

		assertTrue(store.load(7L).isEmpty());
		try (Stream<Path> files = Files.list(dir))
		{
			assertTrue(files.anyMatch(p -> p.getFileName().toString().startsWith("7.broken-")));
		}
	}

	@Test
	public void trackerKeepsLoadedHistory() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		store.save(3L, Collections.singletonList(sampleFight()), 0);

		FightTracker t = new FightTracker();
		t.setHistory(store.load(3L));
		assertEquals(1, t.getHistory().size());
		assertEquals("Vorkath", t.getDisplayFight().title());
		// old fights are from another session: not in this session's total
		assertEquals(null, t.getSessionTotal(0));
	}

	@Test
	public void recordsAreSavedInTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		assertTrue(store.loadRecords(7) == null);
		BossRecords r = new BossRecords();
		BossRecords.Kill k = new BossRecords.Kill();
		k.boss = "Zulrah";
		k.timeMs = 61_000;
		k.myDps = 5.5;
		r.add(k);
		store.saveRecords(7, r);
		BossRecords back = store.loadRecords(7);
		assertEquals(61_000, back.get("Zulrah", false).fastestMs);
		assertEquals(1, back.get("Zulrah", false).kills);
		assertTrue("fights file untouched", store.load(7).isEmpty());
	}

	@Test
	public void monsterStatsAreSavedInTheirOwnFile() throws Exception
	{
		HistoryStore store = new HistoryStore(new Gson(), rooted(folder.getRoot().toPath()));
		assertTrue(store.loadMonsters(7).byName.isEmpty());
		MonsterStats stats = new MonsterStats();
		MonsterStats.Monster m = new MonsterStats.Monster();
		m.name = "Gargoyle";
		m.kills = 3;
		m.attacks.add(25, false);
		m.weapons.put("Bow", m.attacks.copy());
		stats.byName.put(m.name, m);
		store.saveMonsters(7, stats);
		MonsterStats.Monster back = store.loadMonsters(7).byName.get("Gargoyle");
		assertEquals(3, back.kills);
		assertEquals(25, back.weapons.get("Bow").biggestHit);
		assertTrue("records file untouched", store.loadRecords(7) == null);
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Before;
import org.junit.Test;

public class HitAttributorTest
{
	private static final String BOSS = "301:10";
	private static final String RAT = "301:20";
	private HitAttributor a;

	@Before
	public void setUp()
	{
		a = new HitAttributor();
	}

	@Test
	public void meleeHitGoesToTheAttacker()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
	}

	@Test
	public void oneAttackGivesOneHit()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertNull("next tick: no attack left", a.assign(102, BOSS));
	}

	@Test
	public void twoPlayersOldestAttackFirst()
	{
		a.attack(100, "Bob", BOSS);   // ranged, lands later
		a.attack(101, "Ann", BOSS);
		assertEquals("Bob", a.assign(103, BOSS));
		assertEquals("Ann", a.assign(104, BOSS));
	}

	@Test
	public void attackOnOtherNpcDoesNotMatch()
	{
		a.attack(100, "Bob", RAT);
		assertNull(a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, RAT));
	}

	@Test
	public void tooOldAttackIsForgotten()
	{
		a.attack(100, "Bob", BOSS);
		assertNull(a.assign(100 + HitAttributor.MAX_DELAY_TICKS + 1, BOSS));
	}

	@Test
	public void scytheThreeHitsplatsSameTick()
	{
		a.attack(100, "Bob", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Bob", a.assign(101, BOSS));
	}

	@Test
	public void extraHitWithTwoAttackersLandedIsUnknown()
	{
		a.attack(100, "Bob", BOSS);
		a.attack(100, "Ann", BOSS);
		assertEquals("Bob", a.assign(101, BOSS));
		assertEquals("Ann", a.assign(101, BOSS));
		assertNull(a.assign(101, BOSS));
	}

	@Test
	public void animationTwiceInOneAttackIsOneAttack()
	{
		a.attack(100, "Bob", BOSS);
		a.attack(101, "Bob", BOSS); // for example a block animation right after
		assertEquals("Bob", a.assign(102, BOSS));
		assertNull(a.assign(103, BOSS));
	}
}

package com.goldendps.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

public class HitChanceTest
{
	private static final double D = 0.0001;
	private static final WeaponStyles WEAPONS = new WeaponStyles(Arrays.asList(
		"# id\tname\tcategory",
		"4151\tAbyssal whip\tWhip",
		"20997\tTwisted bow\tBow",
		"12926\tToxic blowpipe\tThrown",
		"12899\tTrident of the swamp\tPowered Staff",
		"13652\tDragon claws\tClaw"));

	private NpcStats.Npc vorkath;
	private NpcStats.Npc demon;
	private NpcStats.Npc blueDragon;
	private NpcStats.Npc kalphiteQueen;
	private NpcStats.Npc revenant;
	private NpcStats.Npc golem;
	private NpcStats.Npc vyrewatch;
	private PlayerState me;

	@Before
	public void setUp()
	{
		NpcStats stats = new NpcStats(Arrays.asList(
			"8059\tVorkath\t214\t150\t150\t26\t108\t108\t240\t26\t26\t26\tdragon,undead\t\t\t1",
			"415\tAbyssal demon\t135\t1\t0\t20\t20\t20\t0\t20\t20\t20\tdemon\t\t\t1",
			"963\tKalphite Queen\t300\t150\t0\t50\t50\t10\t100\t100\t100\t100\tkalphite\t\t\t1",
			"7881\tRevenant demon\t140\t100\t0\t10\t10\t10\t10\t10\t10\t10\tdemon\t\t\t1",
			"6503\tGolem\t100\t1\t0\t10\t10\t10\t10\t10\t10\t10\tgolem\t\t\t1",
			"9700\tVyrewatch\t100\t1\t0\t10\t10\t10\t10\t10\t10\t10\tvampyre2\t\t\t1",
			"265\tBlue dragon\t95\t1\t0\t0\t70\t70\t60\t50\t50\t10\tdragon,fiery\twater:50\t\t1"));
		blueDragon = stats.get(265, "Blue dragon");
		kalphiteQueen = stats.get(963, "Kalphite Queen");
		revenant = stats.get(7881, "Revenant demon");
		golem = stats.get(6503, "Golem");
		vyrewatch = stats.get(9700, "Vyrewatch");
		vorkath = stats.get(8059, "Vorkath");
		demon = stats.get(415, "Abyssal demon");
		me = new PlayerState();
		me.attack = 118;
		me.ranged = 112;
		me.magic = 99;
		me.weaponId = 4151;
		me.weaponName = "Abyssal whip";
		me.slashBonus = 132;
		me.rangedBonus = 100;
		me.magicBonus = 50;
	}

	@Test
	public void meleeWithPietyOnAccurate()
	{
		me.prayers.add("PIETY");
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		// (118 * 1.2 = 141) + 3 + 8 = 152; 152 * (132 + 64)
		assertEquals(29_792, HitChance.attackRoll(me, flick, vorkath));
		// (214 + 9) * (108 + 64)
		assertEquals(38_356, HitChance.defenceRoll(WeaponStyles.Type.SLASH, vorkath, 214, 150));
		assertEquals(29_792 / (2.0 * 38_357), HitChance.of(me, flick, vorkath, 214, 150), D);
	}

	@Test
	public void loweredDefenceRaisesTheChance()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		assertTrue(HitChance.of(me, flick, vorkath, 150, 150) > HitChance.of(me, flick, vorkath, 214, 150));
	}

	@Test
	public void magicUsesTheMagicLevelSoDefenceDrainsDoNotHelp()
	{
		me.weaponId = 12899;
		me.weaponName = "Trident of the swamp";
		WeaponStyles.Style accurate = WEAPONS.style(12899, me.weaponName, 0);
		assertEquals(WeaponStyles.Type.MAGIC, accurate.type);
		// 99 + 2 + 9 = 110; 110 * (50 + 64)
		assertEquals(12_540, HitChance.attackRoll(me, accurate, demon));
		assertEquals(HitChance.of(me, accurate, vorkath, 214, 150), HitChance.of(me, accurate, vorkath, 0, 150), D);
	}

	@Test
	public void attackStylesPickStabSlashOrCrush()
	{
		assertEquals(WeaponStyles.Type.SLASH, WEAPONS.style(13652, "Dragon claws", 0).type);
		assertEquals(WeaponStyles.Type.STAB, WEAPONS.style(13652, "Dragon claws", 2).type);
		assertEquals(1, WEAPONS.style(13652, "Dragon claws", 2).stanceBonus);
		assertEquals("whips have no slot 2", null, WEAPONS.style(4151, "Abyssal whip", 2));
		assertEquals(WeaponStyles.Type.SLASH, WEAPONS.style(4151, "Abyssal whip", 3).type);
		assertEquals("unarmed punches", WeaponStyles.Type.CRUSH, WEAPONS.style(0, null, 0).type);
		assertEquals("by name for an id the wiki misses", WeaponStyles.Type.SLASH,
			WEAPONS.style(99999, "Abyssal whip", 0).type);
		assertNull(WEAPONS.style(99999, "Mystery stick", 0));
		assertEquals(WeaponStyles.Type.LIGHT, WEAPONS.style(12926, "Toxic blowpipe", 1).type);
	}

	@Test
	public void voidGivesTenPercentMoreLevel()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		long without = HitChance.attackRoll(me, flick, demon);
		me.worn = Arrays.asList("Void melee helm", "Elite void top", "Elite void robe", "Void knight gloves");
		// (118 + 3 + 8) * 1.1 = 141
		assertEquals(141 * 196, HitChance.attackRoll(me, flick, demon));
		assertEquals(129 * 196, without);
	}

	@Test
	public void salveAgainstUndeadAndArclightAgainstDemons()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		long base = 129 * 196;
		me.worn = Collections.singletonList("Salve amulet(ei)");
		assertEquals(base * 6 / 5, HitChance.attackRoll(me, flick, vorkath));
		me.weaponName = "Arclight";
		assertEquals(base * 17 / 10, HitChance.attackRoll(me, flick, demon));
	}

	@Test
	public void slayerHelmetOnTaskButNotTogetherWithASalve()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		long base = 129 * 196;
		me.worn = Collections.singletonList("Slayer helmet");
		assertEquals("not on task", base, HitChance.attackRoll(me, flick, demon));
		me.onTask = true;
		assertEquals(base * 7 / 6, HitChance.attackRoll(me, flick, demon));
		me.worn = Arrays.asList("Twisted slayer helmet (i)", "Salve amulet(ei)");
		assertEquals("the salve wins on undead", base * 6 / 5, HitChance.attackRoll(me, flick, vorkath));
	}

	@Test
	public void onlyAnImbuedHelmetHelpsRanged()
	{
		me.onTask = true;
		me.weaponId = 20997;
		me.weaponName = "Twisted bow";
		WeaponStyles.Style rapid = WEAPONS.style(20997, "Twisted bow", 1);
		me.worn = Collections.singletonList("Slayer helmet");
		long plain = HitChance.attackRoll(me, rapid, demon);
		me.worn = Collections.singletonList("Slayer helmet (i)");
		assertEquals(plain * 23 / 20, HitChance.attackRoll(me, rapid, demon), 1);
	}

	@Test
	public void twistedBowLikesHighMagic()
	{
		assertEquals(114, HitChance.twistedBowPercent(vorkath));
		NpcStats.Npc strong = new NpcStats(Collections.singletonList(
			"1\tStrong\t200\t250\t0\t0\t0\t0\t0\t0\t0\t0\t\t\t\t1")).get(1, null);
		assertEquals(140, HitChance.twistedBowPercent(strong));
	}

	@Test
	public void chanceFormulaBothSides()
	{
		assertEquals(1 - 102 / (2.0 * 201), HitChance.chance(200, 100), D);
		assertEquals(100 / (2.0 * 201), HitChance.chance(100, 200), D);
	}

	@Test
	public void theWeaponFileLoads() throws Exception
	{
		assertEquals(WeaponStyles.Type.STANDARD, WeaponStyles.load().style(20997, "Twisted bow", 0).type);
	}

	@Test
	public void tumekensShadowTriplesTheMagicBonus()
	{
		me.weaponName = "Tumeken's shadow";
		WeaponStyles.Style accurate = WeaponStyles.CLICKED_SPELL;
		// 99 + 0 + 9 = 108; 108 * (50 * 3 + 64)
		assertEquals(108 * 214, HitChance.attackRoll(me, accurate, demon));
		me.clickedSpell = "Ice Barrage";
		assertEquals("not for a spell you click", 108 * 114, HitChance.attackRoll(me, accurate, demon));
	}

	@Test
	public void elementalWeaknessAddsItsPercent()
	{
		me.clickedSpell = "Water Surge";
		long roll = 108L * 114;
		assertEquals("Blue dragon: +50% for water", roll + roll / 2,
			HitChance.attackRoll(me, WeaponStyles.CLICKED_SPELL, blueDragon));
		me.clickedSpell = "Fire Surge";
		assertEquals(roll, HitChance.attackRoll(me, WeaponStyles.CLICKED_SPELL, blueDragon));
		me.clickedSpell = null;
		me.autocastElement = "water";
		assertEquals("autocast counts too", roll + roll / 2,
			HitChance.attackRoll(me, WeaponStyles.CLICKED_SPELL, blueDragon));
	}

	@Test
	public void elementsOfSpells()
	{
		assertEquals("air", HitChance.elementOf("Wind Strike"));
		assertEquals("fire", HitChance.elementOf("Fire Surge"));
		assertNull(HitChance.elementOf("Ice Barrage"));
		assertNull(HitChance.elementOf("Flames of Zamorak"));
	}

	@Test
	public void aClickedSpellIsMagicWhateverYouHold()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		double melee = HitChance.of(me, flick, vorkath, 214, 150);
		me.clickedSpell = "Ice Barrage";
		// Vorkath: magic level 150, magic defence 240
		assertEquals(HitChance.chance(108L * 114, (150 + 9) * (240 + 64)), HitChance.of(me, flick, vorkath, 214, 150), D);
		assertTrue(melee != HitChance.of(me, flick, vorkath, 214, 150));
	}

	@Test
	public void specialAttacksHaveTheirOwnAccuracyAndDefence()
	{
		me.weaponName = "Bandos godsword";
		me.crushBonus = 0;
		WeaponStyles.Style smash = new WeaponStyles(Collections.singletonList("11804\tBandos godsword\t2h Sword"))
			.style(11804, "Bandos godsword", 2);
		assertEquals(WeaponStyles.Type.CRUSH, smash.type);
		me.specialAttack = true;
		// a godsword spec rolls twice as accurately and against slash defence, whatever the style
		long roll = HitChance.attackRoll(me, smash, vorkath) * 2;
		assertEquals(HitChance.chance(roll, HitChance.defenceRoll(WeaponStyles.Type.SLASH, vorkath, 214, 150)),
			HitChance.of(me, smash, vorkath, 214, 150), D);
	}

	@Test
	public void weaponsWithoutASpecialRuleSpecLikeANormalAttack()
	{
		WeaponStyles.Style flick = WEAPONS.style(4151, "Abyssal whip", 0);
		me.weaponName = "Dragon warhammer";
		double normal = HitChance.of(me, flick, vorkath, 214, 150);
		me.specialAttack = true;
		assertEquals(normal, HitChance.of(me, flick, vorkath, 214, 150), D);
	}

	@Test
	public void dragonClawsSpecHitsWhenAnyOfFourRollsHits()
	{
		me.weaponName = "Dragon claws";
